import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        if (args.length < 1) {
            System.exit(1);
        }

        String dir = args[0];
        File dirFile = new File(dir);
        if (!dirFile.isDirectory()) {
            System.exit(1);
        }

        File[] files = dirFile.listFiles((d, name) -> name.toLowerCase().endsWith(".bmp"));
        if (files == null) {
            System.exit(0);
        }

        Arrays.sort(files, (f1, f2) -> f1.getName().compareTo(f2.getName()));

        for (File bmpFile : files) {
            try {
                processBMP(bmpFile);
            } catch (IOException e) {
                System.exit(1);
            }
        }
    }

    private static void processBMP(File file) throws IOException {
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] header = new byte[14];
            fis.read(header);

            if (!Arrays.equals(header, new byte[]{'B', 'M'})) {
                return;
            }

            int bfOffBits = readU32Little(header, 2);

            FileChannel ch = fis.getChannel();
            ch.position(bfOffBits);

            // Read DIB header
            byte[] dibHeader = new byte[128];
            ch.read(dibHeader);

            int dibSize = readU32Little(dibHeader, 0);
            boolean isSupported = true;
            int compression = 0;
            int bpp = 0;
            int width = 0;
            int height = 0;
            boolean bottomUp = false;

            if (dibSize == 40) {
                width = readI32Little(dibHeader, 4);
                height = readI32Little(dibHeader, 8);
                bpp = readU16Little(dibHeader, 12);
                compression = readU32Little(dibHeader, 14);
                height = Math.abs(height);
                bottomUp = height < 0;
            } else if (dibSize == 108) {
                width = readI32Little(dibHeader, 4);
                height = readI32Little(dibHeader, 8);
                bpp = readU16Little(dibHeader, 12);
                compression = readU32Little(dibHeader, 14);
                height = Math.abs(height);
                bottomUp = height < 0;
            } else if (dibSize == 124) {
                width = readI32Little(dibHeader, 4);
                height = readI32Little(dibHeader, 8);
                bpp = readU16Little(dibHeader, 12);
                compression = readU32Little(dibHeader, 14);
                height = Math.abs(height);
                bottomUp = height < 0;
            } else {
                System.exit(1);
            }

            if (compression != 0 && compression != 3) {
                System.out.println("error: unsupported compression " + compression);
                return;
            }

            if (bpp != 1 && bpp != 4 && bpp != 8 && bpp != 24 && bpp != 32) {
                System.exit(1);
            }

            if (compression == 0 && (bpp != 24 && bpp != 32)) {
                isSupported = false;
            } else if (compression == 3 && bpp != 32) {
                isSupported = false;
            }

            if (!isSupported) {
                System.out.println("error: unsupported compression " + compression);
                return;
            }

            // Read pixel data
            byte[] pixels = new byte[(int) (dibSize + dibSize)];
            ch.read(pixels);

            int rowBytes = (width * bpp + 31) / 32 * 4;
            int totalPixels = width * height;

            int[] rowOffsets = new int[height];
            int[] rowBytesOffsets = new int[height];

            for (int y = 0; y < height; y++) {
                int rowOffset = rowBytes * y;
                if (bottomUp) {
                    rowOffsets[y] = rowOffset;
                } else {
                    rowOffsets[y] = rowOffset + rowBytes * height;
                }
                rowBytesOffsets[y] = rowOffset;
            }

            // Find ink pixels and connected components
            boolean[][] visited = new boolean[height][width];
            ArrayList<Component> components = new ArrayList<>();

            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    if (isInk(pixels, x, y, bpp, dibHeader, width, height)) {
                        if (!visited[y][x]) {
                            Component comp = findComponent(pixels, visited, y, x, width, height, bpp, dibHeader, compression, width, height, bottomUp);
                            comp.setFirstPixel(x, y);
                            components.add(comp);
                        }
                    }
                }
            }

            // Sort components by first pixel (y then x)
            components.sort(Comparator.comparingInt(c -> c.firstY).thenComparingInt(c -> c.firstX));

            System.out.println("size " + width + "x" + height + " bpp " + bpp + " header " + dibSize + " " + (bottomUp ? "bottom-up" : "top-down") + " ink " + totalPixels);
            System.out.println("components " + components.size());

            for (Component comp : components) {
                System.out.println(comp.firstX + "," + comp.firstY + " bbox " + comp.bboxX + "," + comp.bboxY + "-" + comp.bboxX + "," + comp.bboxY + " pixels " + comp.pixelCount);
            }
        }
    }

    private static boolean isInk(byte[] pixels, int x, int y, int bpp, byte[] dibHeader, int width, int height) {
        int rowOffset = (bpp == 1 || bpp == 4 || bpp == 8) ? 0 : y * width * (bpp / 8);
        int pixelIndex = rowOffset + x * (bpp / 8);

        int r = 0, g = 0, b = 0;

        if (bpp == 1) {
            int index = (pixels[pixelIndex] >> 7) & 1;
            r = readU32Little(dibHeader, index * 4 + 0) & 0xFF;
            g = readU32Little(dibHeader, index * 4 + 1) & 0xFF;
            b = readU32Little(dibHeader, index * 4 + 2) & 0xFF;
        } else if (bpp == 4) {
            int index = (pixels[pixelIndex] >> 4) & 0xF;
            r = readU32Little(dibHeader, index * 4 + 0) & 0xFF;
            g = readU32Little(dibHeader, index * 4 + 1) & 0xFF;
            b = readU32Little(dibHeader, index * 4 + 2) & 0xFF;
        } else if (bpp == 8) {
            int index = pixels[pixelIndex] & 0xFF;
            r = readU32Little(dibHeader, index * 4 + 0) & 0xFF;
            g = readU32Little(dibHeader, index * 4 + 1) & 0xFF;
            b = readU32Little(dibHeader, index * 4 + 2) & 0xFF;
        } else if (bpp == 24) {
            b = pixels[pixelIndex] & 0xFF;
            g = pixels[pixelIndex + 1] & 0xFF;
            r = pixels[pixelIndex + 2] & 0xFF;
        } else if (bpp == 32) {
            b = pixels[pixelIndex] & 0xFF;
            g = pixels[pixelIndex + 1] & 0xFF;
            r = pixels[pixelIndex + 2] & 0xFF;
        }

        int value = (299 * r + 587 * g + 114 * b) / 1000;
        return value < 128;
    }

    private static Component findComponent(byte[] pixels, boolean[][] visited, int x, int y, int width, int height, int bpp, byte[] dibHeader, int compression, int width2, int height2, boolean bottomUp) {
        Deque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{x, y});
        visited[y][x] = true;

        int minX = x, minY = y, maxX = x, maxY = y;
        int pixelCount = 0;

        while (!queue.isEmpty()) {
            int[] pos = queue.poll();
            int cx = pos[0];
            int cy = pos[1];

            if (cx < minX) minX = cx;
            if (cy < minY) minY = cy;
            if (cx > maxX) maxX = cx;
            if (cy > maxY) maxY = cy;
            pixelCount++;

            int[] neighbors = new int[]{
                {cx - 1, cy}, {cx + 1, cy}, {cx, cy - 1}, {cx, cy + 1},
                {cx - 1, cy - 1}, {cx + 1, cy - 1}, {cx - 1, cy + 1}, {cx + 1, cy + 1}
            };

            for (int[] n : neighbors) {
                int nx = n[0];
                int ny = n[1];

                if (nx >= 0 && nx < width && ny >= 0 && ny < height && !visited[ny][nx]) {
                    if (isInk(pixels, nx, ny, bpp, dibHeader, width, height)) {
                        visited[ny][nx] = true;
                        queue.offer(n);
                    }
                }
            }
        }

        return new Component(minX, minY, maxX, maxY, pixelCount);
    }

    private static int readU16Little(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8);
    }

    private static int readU32Little(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8) |
               ((data[offset + 2] & 0xFF) << 16) | ((data[offset + 3] & 0xFF) << 24);
    }

    private static int readI32Little(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8) |
               ((data[offset + 2] & 0xFF) << 16) | ((data[offset + 3] & 0xFF) << 24);
    }

    static class Component {
        int firstX, firstY, bboxX, bboxY, bboxX2, bboxY2;
        int pixelCount;

        Component(int minX, int minY, int maxX, int maxY, int count) {
            this.firstX = minX;
            this.firstY = minY;
            this.bboxX = minX;
            this.bboxY = minY;
            this.bboxX2 = maxX;
            this.bboxY2 = maxY;
            this.pixelCount = count;
        }

        void setFirstPixel(int x, int y) {
            if (firstY > y || (firstY == y && firstX > x)) {
                firstX = x;
                firstY = y;
            }
        }
    }
}

