import Foundation
import Network

enum QueryType: String {
    case A = "A"
    case AAAA = "AAAA"
    case MX = "MX"
    case TXT = "TXT"
    case CNAME = "CNAME"

    static let allTypes: [QueryType] = [.A, .AAAA, .MX, .TXT, .CNAME]

    var code: UInt16 {
        switch self {
        case .A: return 1
        case .AAAA: return 28
        case .MX: return 15
        case .TXT: return 16
        case .CNAME: return 5
        }
    }
}

func compress(name: String, offset: inout UInt32) -> UInt32 {
    var offset = UInt32(offset)
    let labels = name.split(separator: ".").map { String($0) }
    var labelOffset = UInt32(offset)
    var pointerOffset: UInt32?

    for (idx, label) in labels.enumerated() {
        let data = label.data(using: .utf8)!
        offset = UInt32(offset) + UInt32(data.count) + 1
        if offset == UInt32(labelOffset) {
            pointerOffset = offset
            break
        }
    }

    return pointerOffset ?? UInt32(offset)
}

func decompress(data: [UInt8], offset: UInt32) -> String {
    var pos = UInt32(0)
    var result = ""
    var currentOffset = offset

    while pos < UInt32(data.count) {
        let labelLen = data[Int32(pos)]
        pos += 1
        if labelLen & 24 != 0 {
            let pointer = (UInt32(labelLen) >> 6) * 256 + UInt32(labelLen) & 63
            let targetOffset = UInt32(currentOffset) + UInt32(data[Int32(currentOffset) + UInt32(pointer)])
            return String(data: data[Int32(currentOffset)..<Int32(currentOffset) + UInt32(labelLen)], encoding: .utf8) ?? ""
        }
        let label = String(data: data[Int32(currentOffset)..<Int32(currentOffset) + UInt32(labelLen)], encoding: .utf8) ?? ""
        result += label
        currentOffset += UInt32(labelLen) + 1
        pos += 1
    }
    return result
}

func buildQuery(name: String, queryType: QueryType, id: UInt16) -> Data {
    var data = Data()
    data.append(contentsOf: UInt8(id >> 8))
    data.append(contentsOf: UInt8(id & 0xFF))
    data.append(contentsOf: UInt8(0x0100))
    data.append(contentsOf: UInt8(0x0001))
    data.append(contentsOf: UInt8(0x0001))
    data.append(contentsOf: UInt8(0x0000))
    data.append(contentsOf: UInt8(0x0000))
    data.append(contentsOf: UInt8(0x0000))

    var offset = UInt32(12)
    let labels = name.split(separator: ".").map { String($0) }
    for label in labels {
        let labelData = label.data(using: .utf8)!
        data.append(contentsOf: UInt8(labelData.count))
        data.append(contentsOf: labelData)
    }
    data.append(contentsOf: UInt8(0))
    data.append(contentsOf: UInt8(queryType.code))
    data.append(contentsOf: UInt8(1))

    return data
}

func sendUDP(data: Data, port: Int) -> Data? {
    let host = "127.0.0.1"
    let socket = try! Socket(domain: .udp, type: .dgram, protocol: .udp)
    try! socket.connect(host, port: port)
    let result = try! socket.send(data)
    socket.close()
    return result
}

func receiveUDP(id: UInt16, port: Int) -> Data? {
    let host = "127.0.0.1"
    var socket = Socket(domain: .udp, type: .dgram, protocol: .udp)
    try! socket.connect(host, port: port)
    var data = Data()
    while !socket.isClosed {
        try! socket.read(&data)
        if let response = parseUDPResponse(data, id: id) {
            socket.close()
            return response
        }
    }
    socket.close()
    return nil
}

func receiveTCP(id: UInt16, port: Int) -> Data? {
    let host = "127.0.0.1"
    var socket = Socket(domain: .tcp, type: .stream, protocol: .tcp)
    try! socket.connect(host, port: port)
    var data = Data()
    while !socket.isClosed {
        let len = try! socket.read(&data)
        if let response = parseTCPResponse(data, id: id) {
            socket.close()
            return response
        }
    }
    socket.close()
    return nil
}

func parseUDPResponse(_ data: Data, id: UInt16) -> Data? {
    guard data.count >= 12 else { return nil }
    let header = data[0..<12]
    var headerData = Data(header)
    let responseID = headerData[UInt32(0)]
    if responseID != id {
        return nil
    }
    return data
}

func parseTCPResponse(_ data: Data, id: UInt16) -> Data? {
    guard data.count >= 2 else { return nil }
    let len = Data(data[0..1])
    let lenInt = len.withUnsafeBytes { UInt16($0.load(as: .bigEndian)) }
    return data.subdata(with: 2..<2 + UInt32(lenInt))
}

func parseDNSResponse(_ data: Data) -> (rcode: UInt16, answers: [(owner: String, ttl: UInt32, type: QueryType, data: String)]) {
    guard data.count >= 12 else { return (0, []) }
    var offset = UInt32(12)
    var rcode = UInt16(data[Int32(offset)])
    offset += 1
    let qdcount = UInt16(data[Int32(offset)])
    offset += 1
    let ancount = UInt16(data[Int32(offset)])
    offset += 1

    var answers = [(owner: String, ttl: UInt32, type: QueryType, data: String)]()
    var currentOffset = offset
    for _ in 0..<Int(ancount) {
        let owner = parseName(&currentOffset)
        let type = UInt16(data[Int32(currentOffset)])
        let rdataOffset = currentOffset + 2
        let rdataLen = UInt32(data[Int32(rdataOffset)])
        let rdata = data.subdata(with: UInt32(rdataOffset)..<UInt32(rdataOffset) + rdataLen)
        let dataString = parseRData(rdata, type)
        answers.append((owner, currentOffset, type, dataString))
        currentOffset += rdataLen + 1
    }
    return (rcode, answers)
}

func parseName(_ offset: inout UInt32) -> String {
    var name = ""
    var currentOffset = offset
    while true {
        let labelLen = data[Int32(currentOffset)]
        currentOffset += 1
        if labelLen & 24 != 0 {
            let pointer = (UInt32(labelLen) >> 6) * 256 + UInt32(labelLen) & 63
            let targetOffset = UInt32(currentOffset) + UInt32(data[Int32(currentOffset) + UInt32(pointer)])
            return String(data: data[Int32(currentOffset)..<Int32(currentOffset) + UInt32(labelLen)], encoding: .utf8) ?? ""
        }
        let label = String(data: data[Int32(currentOffset)..<Int32(currentOffset) + UInt32(labelLen)], encoding: .utf8) ?? ""
        name += label
        currentOffset += UInt32(labelLen) + 1
    }
}

func parseRData(_ rdata: Data, _ type: UInt16) -> String {
    switch type {
    case 1:
        return rdata.map {
            if $0 == 0 { return "." }
            else { return String(format: "%u", $0) }
        }.joined(separator: ".")
    case 28:
        return formatIPv6(rdata)
    case 5:
        return rdata.map {
            if $0 == 0 { return "." }
            else { return String(format: "%u", $0) }
        }.joined(separator: ".")
    case 15:
        let preference = UInt16(rdata[Int32(0)])
        let exchange = String(data: rdata.subdata(with: UInt32(2)..<UInt32(2) + UInt32(rdata.count)), encoding: .utf8) ?? ""
        return "\(preference) \(exchange)"
    case 16:
        return formatTXT(rdata)
    default:
        return "#" + rdata.count.description
    }
}

func formatIPv6(_ rdata: Data) -> String {
    var groups = [String]()
    for i in 0..<16 {
        let byte = rdata[Int32(i)]
        if byte == 0 {
            groups.append("0")
        } else {
            groups.append(String(format: "%02x", byte))
        }
    }
    var result = groups.joined()
    if result.contains("0000") {
        result = result.replacingOccurrences(of: "0000", with: "::")
    }
    return result
}

func formatTXT(_ rdata: Data) -> String {
    var result = ""
    var offset = 0
    while offset < rdata.count {
        let len = UInt32(rdata[Int32(offset)])
        offset += 1
        if len == 0 {
            result += " \"\""
        } else {
            let data = rdata.subdata(with: UInt32(offset)..<UInt32(offset) + len)
            var str = String(data: data, encoding: .utf8) ?? ""
            str = str.replacingOccurrences(of: "\"", with: "\\\"")
            result += " \"\(str)\""
        }
        offset += len
    }
    return result
}

func formatType(_ type: UInt16) -> String {
    switch type {
    case 1: return "A"
    case 28: return "AAAA"
    case 5: return "CNAME"
    case 15: return "MX"
    case 16: return "TXT"
    default: return "TYPE\(type)"
    }
}

func sendQuery(id: UInt16, query: Data, port: Int) -> Data? {
    var data = query
    data.append(contentsOf: UInt8(0))
    data.append(contentsOf: UInt8(0))
    data.append(contentsOf: UInt8(0))
    data.append(contentsOf: UInt8(0))
    return sendUDP(data: data, port: port)
}

func processQuery(_ name: String, _ type: QueryType, _ port: Int) {
    var id = UInt16.random(in: 0..<65536)
    let query = buildQuery(name: name, queryType: type, id: id)
    var response: Data?
    var tcpResponse: Data?
    var attempt = 0

    while response == nil && attempt < 5 {
        response = sendQuery(id: id, query: query, port: port)
        if response == nil {
            tcpResponse = receiveTCP(id: id, port: port)
            response = tcpResponse
        }
        attempt += 1
    }

    if let data = response {
        let (rcode, answers) = parseDNSResponse(data)
        print("\(name.lowercased()) \(type.rawValue) \(rcode)")
        for answer in answers {
            print("  \(answer.owner) \(answer.ttl) \(formatType(answer.type.code)) \(answer.data)")
        }
    }
}

func main() {
    guard let args = CommandLine.arguments,
          args.count >= 3,
          let dir = args[1],
          let portStr = args[2],
          let port = Int(portStr) else {
        print("Usage: <args> <directory> <port>", file: #file, line: #line)
        exit(1)
    }

    let fileURL = URL(fileURLWithPath: dir).appendingPathComponent("queries.txt")
    if !FileManager.default.fileExists(atPath: fileURL.path) {
        return
    }

    do {
        let content = try String(contentsOf: fileURL, encoding: .utf8)
        let lines = content.components(separatedBy: .newlines).filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
        for line in lines {
            let parts = line.split(separator: " ").map(String.init)
            guard parts.count >= 2,
                  let name = parts[0],
                  let typeStr = parts[1],
                  let type = QueryType(rawValue: typeStr) else {
                continue
            }
            processQuery(name, type, port)
        }
    } catch {
        print("Error reading file: \(error.localizedDescription)", file: #file, line: #line)
    }
}

