import * as fs from 'fs';
import * as path from 'path';

function main() {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    console.error('Usage: node main.ts <directory>');
    process.exit(1);
  }

  const dir = args[0];
  const files = fs.readdirSync(dir)
    .filter(f => f.endsWith('.bmp'))
    .sort();

  for (const fileName of files) {
    const filePath = path.join(dir, fileName);
    const fileBuffer = fs.readFileSync(filePath);
    processBmpFile(fileName, fileBuffer);
  }
}

function processBmpFile(fileName: string, buffer: Buffer): void {
  const magic = buffer[0] + 0x4000; // 'BM' = 0x4252
  if (buffer[0] !== 0x42 || buffer[1] !== 0x4D) {
    console.error(`== ${fileName}`);
    console.error('error: invalid BMP file');
    return;
  }

  const fileSize = buffer.readUInt32LE(2);
  const bfOffBits = buffer.readUInt32LE(10);

  const dibSize = buffer.readUInt32LE(14);
  const width = buffer.readInt32LE(18);
  const height = buffer.readInt32LE(22);
  const planes = buffer.readUInt16LE(26);
  const bitsPerPixel = buffer.readUInt16LE(28);
  const compression = buffer.readUInt32LE(30);
  const imageSize = buffer.readUInt32LE(34);
  const xPixelsPerMeter = buffer.readInt32LE(38);
  const yPixelsPerMeter = buffer.readInt32LE(42);
  const coloursUsed = buffer.readUInt32LE(46);
  const importantColours = buffer.readUInt32LE(50);

  const absHeight = Math.abs(height);
  const cols = Math.abs(width);
  const isBottomUp = height > 0;

  if (compression !== 0 && compression !== 3) {
    console.error(`== ${fileName}`);
    console.error(`error: unsupported compression ${compression}`);
    return;
  }

  const rowPadding = (bitsPerPixel / 8 + 3) & ~3;
  const rowSize = (cols * bitsPerPixel / 8) + rowPadding;
  const pixelDataStart = bfOffBits;
  const pixelData = buffer.slice(pixelDataStart);

  const rows = absHeight;
  const inkPixels: Set<string> = new Set();

  if (bitsPerPixel === 1) {
    for (let y = 0; y < rows; y++) {
      const rowStart = y * rowSize;
      const rowEnd = Math.min(rowStart + rowSize, pixelData.length);
      const rowBuffer = pixelData.slice(rowStart, rowEnd);
      for (let x = 0; x < cols; x++) {
        const byteIndex = Math.floor(x / 8);
        const bitIndex = 7 - (x % 8);
        const v = (rowBuffer[byteIndex] >> bitIndex) & 1;
        if (v === 1) {
          inkPixels.add(`${x},${y}`);
        }
      }
    }
  } else if (bitsPerPixel === 4) {
    for (let y = 0; y < rows; y++) {
      const rowStart = y * rowSize;
      const rowEnd = Math.min(rowStart + rowSize, pixelData.length);
      const rowBuffer = pixelData.slice(rowStart, rowEnd);
      for (let x = 0; x < cols; x++) {
        const byteIndex = Math.floor(x / 2);
        const bitIndex = 7 - ((x % 2) * 4);
        const v = (rowBuffer[byteIndex] >> bitIndex) & 0xF;
        if (v === 1) {
          inkPixels.add(`${x},${y}`);
        }
      }
    }
  } else if (bitsPerPixel === 8) {
    for (let y = 0; y < rows; y++) {
      const rowStart = y * rowSize;
      const rowEnd = Math.min(rowStart + rowSize, pixelData.length);
      const rowBuffer = pixelData.slice(rowStart, rowEnd);
      for (let x = 0; x < cols; x++) {
        if (rowBuffer[x] !== 0) {
          inkPixels.add(`${x},${y}`);
        }
      }
    }
  } else if (bitsPerPixel === 24) {
    for (let y = 0; y < rows; y++) {
      const rowStart = y * rowSize;
      const rowEnd = Math.min(rowStart + rowSize, pixelData.length);
      const rowBuffer = pixelData.slice(rowStart, rowEnd);
      for (let x = 0; x < cols; x++) {
        const b = rowBuffer[x * 3];
        const g = rowBuffer[x * 3 + 1];
        const r = rowBuffer[x * 3 + 2];
        const ink = (299 * r + 587 * g + 114 * b) / 1000 < 128;
        if (ink) {
          inkPixels.add(`${x},${y}`);
        }
      }
    }
  } else if (bitsPerPixel === 32) {
    if (compression === 0) {
      for (let y = 0; y < rows; y++) {
        const rowStart = y * rowSize;
        const rowEnd = Math.min(rowStart + rowSize, pixelData.length);
        const rowBuffer = pixelData.slice(rowStart, rowEnd);
        for (let x = 0; x < cols; x++) {
          const b = rowBuffer[x * 4];
          const g = rowBuffer[x * 4 + 1];
          const r = rowBuffer[x * 4 + 2];
          const ink = (299 * r + 587 * g + 114 * b) / 1000 < 128;
          if (ink) {
            inkPixels.add(`${x},${y}`);
          }
        }
      }
    } else if (compression === 3) {
      for (let y = 0; y < rows; y++) {
        const rowStart = y * rowSize;
        const rowEnd = Math.min(rowStart + rowSize, pixelData.length);
        const rowBuffer = pixelData.slice(rowStart, rowEnd);
        let x = 0;
        while (x < cols) {
          const mask = (isBottomUp ? 0 : 1) === 0 ? 0 : 0;
          const pixel = rowBuffer[x * 4];
          const redMask = isBottomUp ? 0 : 0;
          const greenMask = isBottomUp ? 0 : 0;
          const blueMask = isBottomUp ? 0 : 0;
          const r = pixel & 0xFF;
          const g = (pixel >> 8) & 0xFF;
          const b = (pixel >> 16) & 0xFF;
          const ink = (299 * r + 587 * g + 114 * b) / 1000 < 128;
          if (ink) {
            inkPixels.add(`${x},${y}`);
          }
          x++;
        }
      }
    }
  }

  const visited = new Set<string>();
  const components: Component[] = [];
  let inkCount = inkPixels.size;

  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const key = `${x},${y}`;
      if (inkPixels.has(key) && !visited.has(key)) {
        const component = findComponent(inkPixels, x, y, visited, cols, rows);
        components.push(component);
      }
    }
  }

  console.log(`== ${fileName}`);
  console.log(`size ${cols}x${absHeight} bpp ${bitsPerPixel} header ${dibSize} ${isBottomUp ? 'bottom-up' : 'top-down'} ink ${inkCount}`);
  console.log(`components ${components.length}`);

  for (const component of components) {
    console.log(`${component.firstX},${component.firstY} bbox ${component.minX},${component.minY}-${component.maxX},${component.maxY} pixels ${component.pixelCount}`);
  }
}

function findComponent(inkPixels: Set<string>, startX: number, startY: number, visited: Set<string>, cols: number, rows: number): Component {
  const component: Component = { minX: startX, minY: startY, maxX: startX, maxY: startY, firstX: startX, firstY: startY, pixelCount: 0, pixels: [] };
  const stack: {x: number, y: number}[] = [{x: startX, y: startY}];
  visited.add(`${startX},${startY}`);
  component.pixelCount++;

  while (stack.length > 0) {
    const current = stack.pop()!;
    const x = current.x;
    const y = current.y;

    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx;
        const ny = y + dy;
        if (nx >= 0 && nx < cols && ny >= 0 && ny < rows) {
          const key = `${nx},${ny}`;
          if (inkPixels.has(key) && !visited.has(key)) {
            visited.add(key);
            stack.push({x: nx, y: ny});
          }
        }
      }
    }
  }

  for (const key of visited) {
    const [x, y] = key.split(',').map(Number);
    component.pixels.push({x, y});
    if (x < component.minX) component.minX = x;
    if (x > component.maxX) component.maxX = x;
    if (y < component.minY) component.minY = y;
    if (y > component.maxY) component.maxY = y;
  }

  component.firstX = Infinity;
  component.firstY = Infinity;
  for (const pixel of component.pixels) {
    if (pixel.y < component.firstY || (pixel.y === component.firstY && pixel.x < component.firstX)) {
      component.firstX = pixel.x;
      component.firstY = pixel.y;
    }
  }

  return component;
}

interface Component {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
  firstX: number;
  firstY: number;
  pixelCount: number;
  pixels: {x: number, y: number}[];
}

