import { readFileSync } from 'fs';

type Account = {
  name: string;
  currency: string;
  balance: bigint;
  minorUnits: number;
  limit: bigint;
};

type Currency = {
  code: string;
  minorUnits: number;
};

type SplitTarget = {
  account: string;
  weight: number;
};

class Ledger {
  private accounts: Map<string, Account> = new Map();
  private currencies: Map<string, Currency> = new Map();
  private rejected: string[] = [];

  constructor() {}

  currency(code: string, minorUnits: number): void {
    this.currencies.set(code, { code, minorUnits });
  }

  open(account: string, code: string, limit: bigint): void {
    if (!this.currencies.has(code)) {
      throw new Error(`currency ${code} undefined`);
    }
    if (this.accounts.has(account)) {
      throw new Error(`account exists ${account}`);
    }
    this.accounts.set(account, {
      name: account,
      currency: code,
      balance: 0n,
      minorUnits: this.currencies.get(code)!.minorUnits,
      limit: limit,
    });
  }

  deposit(account: string, amount: string): void {
    const account = this.getAccount(account);
    if (!account) {
      throw new Error(`unknown account ${account}`);
    }
    const roundedAmount = this.roundAmount(amount, account.minorUnits);
    if (roundedAmount <= 0n) {
      throw new Error('non-positive amount');
    }
    const newBalance = account.balance + roundedAmount;
    if (newBalance < -account.limit) {
      throw new Error(`insufficient funds ${account.name}`);
    }
    account.balance = newBalance;
  }

  withdraw(account: string, amount: string): void {
    const account = this.getAccount(account);
    if (!account) {
      throw new Error(`unknown account ${account}`);
    }
    const roundedAmount = this.roundAmount(amount, account.minorUnits);
    if (roundedAmount <= 0n) {
      throw new Error('non-positive amount');
    }
    const newBalance = account.balance - roundedAmount;
    if (newBalance < -account.limit) {
      throw new Error(`insufficient funds ${account.name}`);
    }
    account.balance = newBalance;
  }

  transfer(from: string, to: string, amount: string): void {
    const fromAcc = this.getAccount(from);
    const toAcc = this.getAccount(to);
    if (!fromAcc || !toAcc) {
      throw new Error(`unknown account ${from || to}`);
    }
    if (fromAcc.currency !== toAcc.currency) {
      throw new Error('currency mismatch');
    }
    const roundedAmount = this.roundAmount(amount, fromAcc.minorUnits);
    if (roundedAmount <= 0n) {
      throw new Error('non-positive amount');
    }
    const newBalance = fromAcc.balance - roundedAmount;
    if (newBalance < -fromAcc.limit) {
      throw new Error(`insufficient funds ${from}`);
    }
    fromAcc.balance = newBalance;
    toAcc.balance += roundedAmount;
  }

  convert(from: string, to: string, amount: string, rate: string): void {
    const fromAcc = this.getAccount(from);
    const toAcc = this.getAccount(to);
    if (!fromAcc || !toAcc) {
      throw new Error(`unknown account ${from || to}`);
    }
    if (fromAcc.currency !== toAcc.currency) {
      throw new Error('currency mismatch');
    }
    const fromRate = this.parseDecimal(rate);
    const roundedAmount = this.roundAmount(amount, fromAcc.minorUnits);
    if (roundedAmount <= 0n) {
      throw new Error('non-positive amount');
    }
    const fromBalance = fromAcc.balance - roundedAmount;
    if (fromBalance < -fromAcc.limit) {
      throw new Error(`insufficient funds ${from}`);
    }
    fromAcc.balance = fromBalance;
    const toAmount = this.roundAmount(fromBalance * fromRate, toAcc.minorUnits);
    toAcc.balance += toAmount;
  }

  interest(account: string, rate: string): void {
    const account = this.getAccount(account);
    if (!account) {
      throw new Error(`unknown account ${account}`);
    }
    const rateDecimal = this.parseDecimal(rate);
    const interest = this.roundAmount(account.balance * rateDecimal, account.minorUnits);
    account.balance += interest;
  }

  split(from: string, amount: string, targets: SplitTarget[]): void {
    const fromAcc = this.getAccount(from);
    if (!fromAcc) {
      throw new Error(`unknown account ${from}`);
    }
    const roundedAmount = this.roundAmount(amount, fromAcc.minorUnits);
    if (roundedAmount <= 0n) {
      throw new Error('non-positive amount');
    }
    const totalWeight = targets.reduce((sum, t) => sum + t.weight, 0);
    if (totalWeight === 0) {
      throw new Error('non-positive amount');
    }
    const remainder = fromAcc.balance - roundedAmount;
    if (remainder < -fromAcc.limit) {
      throw new Error(`insufficient funds ${from}`);
    }
    fromAcc.balance = remainder;
    for (const target of targets) {
      const account = this.getAccount(target.account);
      if (!account) {
        throw new Error(`unknown account ${target.account}`);
      }
      if (account.currency !== fromAcc.currency) {
        throw new Error('currency mismatch');
      }
      const base = (roundedAmount * BigInt(target.weight)) / BigInt(totalWeight);
      const remainder = (roundedAmount * BigInt(target.weight)) % BigInt(totalWeight);
      const targetRemainder = remainder;
      account.balance += base;
      if (targetRemainder !== 0n) {
        account.balance += 1n;
      }
    }
  }

  getAccount(name: string): Account | undefined {
    return this.accounts.get(name);
  }

  checkUnknownAccount(name: string): void {
    if (!this.accounts.has(name)) {
      throw new Error(`unknown account ${name}`);
    }
  }

  parseDecimal(amount: string): bigint {
    if (!amount.includes('.')) {
      return BigInt(amount);
    }
    const [integerPart, decimalPart] = amount.split('.');
    const decimalPart = decimalPart || '0';
    let decimalLen = decimalPart.length;
    if (decimalLen < 18) {
      decimalPart += '0'.repeat(18 - decimalLen);
      decimalLen = 18;
    }
    return BigInt(integerPart || '0') * 10n ** BigInt(decimalLen) + BigInt(decimalPart);
  }

  roundAmount(amount: string, minorUnits: number): bigint {
    const decimal = this.parseDecimal(amount);
    const divisor = 10n ** BigInt(minorUnits);
    const remainder = decimal % divisor;
    const half = divisor / 2n;

    if (remainder < 0n) {
      remainder = remainder + divisor;
    }

    if (remainder < half) {
      return decimal - remainder;
    } else if (remainder > half) {
      return decimal + remainder;
    } else {
      const digit = (decimal / divisor) % 10n;
      if (digit % 2n === 0n) {
        return decimal - remainder;
      } else {
        return decimal + remainder;
      }
    }
  }

  printBalance(account: Account): string {
    const balance = account.balance;
    const sign = balance < 0n ? '-' : '';
    const absBalance = balance < 0n ? -balance : balance;
    const minorUnits = account.minorUnits;
    const divisor = 10n ** BigInt(minorUnits);

    const integerPart = (absBalance / divisor).toString();
    const decimalPart = (absBalance % divisor).toString().padEnd(minorUnits, '0');

    const formattedInteger = integerPart.replace(/(\d)(?=(\d{3})+(?!\d))/g, '$1,');
    return `${sign}${formattedInteger}.${decimalPart}`;
  }

  printTotal(currency: string): string {
    const currencyInfo = this.currencies.get(currency);
    if (!currencyInfo) return '';

    const total = this.accounts
      .filter((a) => a.currency === currency)
      .reduce((sum, a) => sum + a.balance, 0n);
    const count = this.accounts.filter((a) => a.currency === currency).length;
    const totalStr = this.printBalance({ name: '', currency, balance: total, minorUnits: currencyInfo.minorUnits, limit: 0n });
    return `${totalStr} (${count} accounts)`;
  }

  run(lines: string[]): void {
    let lineNum = 1;
    for (const line of lines) {
      const trimmedLine = line.trim();
      if (trimmedLine === '' || trimmedLine.startsWith('#')) {
        continue;
      }

      const parts = trimmedLine.split(/\s+/);
      if (parts.length === 0) continue;

      const cmd = parts[0].toLowerCase();
      const args = parts.slice(1);

      try {
        if (cmd === 'currency') {
          const code = args[0];
          const minorUnits = parseInt(args[1]);
          this.currency(code, minorUnits);
        } else if (cmd === 'open') {
          const account = args[0];
          const code = args[1];
          const limitStr = args.length > 2 ? args[2] : '0';
          const limit = BigInt(limitStr);
          this.open(account, code, limit);
        } else if (cmd === 'deposit') {
          const account = args[0];
          const amount = args[1];
          this.deposit(account, amount);
        } else if (cmd === 'withdraw') {
          const account = args[0];
          const amount = args[1];
          this.withdraw(account, amount);
        } else if (cmd === 'transfer') {
          const from = args[0];
          const to = args[1];
          const amount = args[2];
          this.transfer(from, to, amount);
        } else if (cmd === 'convert') {
          const from = args[0];
          const to = args[1];
          const amount = args[2];
          const rate = args[3];
          this.convert(from, to, amount, rate);
        } else if (cmd === 'interest') {
          const account = args[0];
          const rate = args[1];
          this.interest(account, rate);
        } else if (cmd === 'split') {
          const from = args[0];
          const amount = args[1];
          const targetParts = args.slice(2);
          const targets: SplitTarget[] = [];
          for (const target of targetParts) {
            const [account, weightStr] = target.split(':');
            targets.push({ account, weight: parseInt(weightStr) });
          }
          this.split(from, amount, targets);
        } else {
          this.rejected.push(`line ${lineNum}: REJECT unknown command ${cmd}`);
        }
      } catch (e: any) {
        this.rejected.push(`line ${lineNum}: REJECT ${e.message}`);
      }
      lineNum++;
    }
  }

  output(): void {
    for (const reject of this.rejected) {
      console.log(reject);
    }
    console.log('');

    const sortedAccounts = Array.from(this.accounts.entries()).sort((a, b) => a[0].localeCompare(b[0]));
    for (const [name, acc] of sortedAccounts) {
      console.log(`${name} ${acc.currency} ${this.printBalance(acc)}`);
    }
    console.log('');

    const sortedCurrencies = Array.from(this.currencies.entries()).sort((a, b) => a[0].localeCompare(b[0]));
    for (const [code, info] of sortedCurrencies) {
      if (this.accounts.some(a => a.currency === code)) {
        console.log(`total ${code} ${this.printTotal(code)}`);
      }
    }
  }
}

const ledger = new Ledger();

const args = process.argv.slice(2);
if (args.length === 0) {
  process.exit(1);
}

const filename = args[0];
