                    bool nink = is_ink(pixels + ny * width + nx, bpp);
                    if (!nink) continue;

                    // Mark visited
                    pixels[ny * width + nx] = 0;

                    // Update component
                    comp->max_x = nx;
                    comp->max_y = ny;
                    comp->pixel_count++;

                    queue_x[tail] = nx;
                    queue_y[tail] = ny;
                    tail++;
                }
            }

            free(queue_x);
            free(queue_y);
        }
    }

    // Restore pixels
    if (bpp == 1) {
        uint8_t *expanded = calloc(width * height, 1);
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int bit = expanded[y * width + x];
                pixels[y * width + x] = bit ? 0xFF : 0;
            }
        }
        free(expanded);
    } else if (bpp == 4) {
        uint8_t *expanded = calloc(width * height, 1);
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int bit = expanded[y * width + x];
                pixels[y * width + x] = bit ? 0xF0 : 0;
            }
        }
        free(expanded);
    }
}

void output_component(Component *comp) {
    printf("%d,%d bbox %d,%d-%d,%d pixels %d\n",
           comp->first_x, comp->first_y,
           comp->min_x, comp->min_y,
           comp->max_x, comp->max_y,
           comp->pixel_count);
}

void process_file(const char *filename) {
    ImageInfo info;
    if (!parse_bmp_header(filename, &info)) return;

    printf("== %s\n", filename);

    printf("size %dx%d bpp %d header %d ", info.width, info.height, info.bpp, info.header_size);
    if (info.height < 0) printf("top-down");
    else printf("bottom-up");
    printf(" ink ");

    uint8_t *pixels = decode_image(filename, &info);
    if (!pixels) return;

    int ink_count = 0;
    for (int y = 0; y < info.height; y++) {
        for (int x = 0; x < info.width; x++) {
            if (is_ink(pixels + y * info.width * (info.bpp / 8) + x * (info.bpp / 8), info.bpp)) {
                ink_count++;
            }
        }
    }
    printf("%d\n", ink_count);

    // Find components
    int component_count = 0;
    find_components(pixels, &info, &component_count);

    printf("components %d\n", component_count);
    for (int i = 0; i < component_count; i++) {
        output_component(&components[i]);
    }

    free(pixels);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        return 1;
    }

    DIR *dir = opendir(argv[1]);
    if (!dir) {
        return 1;
    }

    char file_path[1024];
    struct dirent *entry;
    char **files = malloc(1024 * sizeof(char *));
    int file_count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, ".bmp") == NULL) continue;
        snprintf(file_path, sizeof(file_path), "%s/%s", argv[1], entry->d_name);
        files[file_count++] = strdup(file_path);
    }
    closedir(dir);

    qsort(files, file_count, sizeof(char *), compare_files);

    for (int i = 0; i < file_count; i++) {
        process_file(files[i]);
        free(files[i]);
    }

    free(files);
    return 0;
}

