    return bool(re.match(r'^[A-Za-z0-9_-]*$', s))

def decode_json_escapes(s):
    """Decode JSON escape sequences in a string"""
    return json.loads('"' + s + '"')

def verify_signature(signature_segment, secret, alg):
    """Verify HMAC signature"""
    if alg == 'HS256':
        hash_func = hashlib.sha256
    elif alg == 'HS384':
        hash_func = hashlib.sha384
    elif alg == 'HS512':
        hash_func = hashlib.sha512
    else:
        return False

    data = f"{header_segment}.{payload_segment}".encode('ascii')
    expected = hmac.new(secret.encode('ascii'), data, hash_func).digest()
    return hmac.compare_digest(signature_segment.encode('ascii'), expected.hex())

def verify_token(token, config):
    """Verify a single JWT token and return result string or None if valid"""
    parts = token.strip().split('.')

    if len(parts) != 3:
        return "MALFORMED"

    header_segment, payload_segment, signature_segment = parts

    if not all(is_valid_base64url(part) for part in parts):
        return "MALFORMED"

    try:
        header_bytes = base64url_decode(header_segment)
        header = json.loads(header_bytes.decode('utf-8'))
    except (ValueError, UnicodeDecodeError, json.JSONDecodeError):
        return "MALFORMED"

    if not isinstance(header, dict):
        return "MALFORMED"

    try:
        payload_bytes = base64url_decode(payload_segment)
        payload = json.loads(payload_bytes.decode('utf-8'))
    except (ValueError, UnicodeDecodeError, json.JSONDecodeError):
        return "MALFORMED"

    if not isinstance(payload, dict):
        return "MALFORMED"

    if header.get('alg') is None or not isinstance(header.get('alg'), str):
        return "UNSUPPORTED_ALG"

    alg = header['alg']

    if alg not in ('HS256', 'HS384', 'HS512'):
        return "UNSUPPORTED_ALG"

    if 'kid' not in header or not isinstance(header.get('kid'), str):
        return "UNKNOWN_KEY"

    kid = header['kid']

    keys = config.get('keys', [])
    key_found = None
    for key in keys:
        if isinstance(key, dict) and key.get('kid') == kid:
            key_found = key
            break

    if key_found is None:
        return "UNKNOWN_KEY"

    key_alg = key_found.get('alg')
    if key_alg is None:
        return "ALG_MISMATCH"

    if key_alg != alg:
        return "ALG_MISMATCH"

    key_secret = key_found.get('k')
    if key_secret is None:
        return "ALG_MISMATCH"

    try:
        secret = base64url_decode(key_secret)
    except ValueError:
        return "ALG_MISMATCH"

    try:
        sig = base64url_decode(signature_segment)
    except ValueError:
        return "BAD_SIGNATURE"

    if not verify_signature(signature_segment, secret, alg):
        return "BAD_SIGNATURE"

    now = config.get('now', 0)
    leeway = config.get('leeway', 0)
    issuer = config.get('issuer', '')
    audience = config.get('audience', '')

    if 'exp' in payload:
        exp = payload['exp']
        if isinstance(exp, (int, float)) and now >= exp + leeway:
            return "EXPIRED"

    if 'nbf' in payload:
        nbf = payload['nbf']
        if isinstance(nbf, (int, float)) and now + leeway < nbf:
            return "NOT_YET_VALID"

    if 'iss' not in payload or payload['iss'] != issuer:
        return "BAD_ISSUER"

    aud = payload.get('aud')
    if aud is None:
        return "BAD_AUDIENCE"

    if isinstance(aud, str) and aud != audience:
        return "BAD_AUDIENCE"

    if isinstance(aud, list):
        if not any(a == audience for a in aud):
            return "BAD_AUDIENCE"
    elif not isinstance(aud, (str, list)):
        return "BAD_AUDIENCE"

    sub = payload.get('sub')
    if sub is None:
        return "MALFORMED"

    sub_str = decode_json_escapes(str(sub))

    scope = payload.get('scope')
    if scope is None:
        scope_list = []
    else:
        if isinstance(scope, str):
            scope_list = [s for s in scope.split() if s]
        elif isinstance(scope, list):
            scope_list = [s for s in scope if s]
        else:
            scope_list = []

    scope_list = sorted(set(scope_list), key=lambda x: ord(x))
    scope_str = ','.join(scope_list)

    return f"VALID sub={sub_str} scope={scope_str}"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    config_path = 'config.json'
    tokens_path = 'tokens.txt'

    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        sys.exit(1)

    try:
        with open(tokens_path, 'r', encoding='utf-8') as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        lines = []

    results = []
    valid_count = 0
    invalid_count = 0

    for i, line in enumerate(lines, 1):
        token = line.strip()
        if not token:
            continue

        result = verify_token(token, config)
        results.append(result)

        if result == "VALID":
            valid_count += 1
        else:
            invalid_count += 1

    for i, result in enumerate(results, 1):
        print(f"{i}: {result}")

    print()
    print(f"valid={valid_count} invalid={invalid_count}")

if __name__ == '__main__':
    main()

