// Parse multipart
func parseMultipart(_ lines: [String], boundary: String, lineBreak: String, headers: [String: String]) -> [Entity] {
    var parts: [Entity] = []
    var currentPart: [String] = []
    var inPart = false
    var delimiterFound = false
    var ct: String?
    var disposition: String?
    var encoding: String?
    var charset: String?
    var name: String?
    var filename: String?

    let boundary = boundary

    for (i, line) in lines.enumerated() {
        if delimiterFound {
            continue
        }

        // Check for delimiter
        if line.hasPrefix("--\(boundary)") {
            delimiterFound = true
            continue
        }

        if line.hasPrefix("--\(boundary)--") {
            continue
        }

        if line.hasPrefix("--\(boundary)") {
            delimiterFound = true
            continue
        }

        // Parse headers
        if inPart {
            currentPart.append(line)
            inPart = false
            continue
        }

        if !line.hasPrefix(lineBreak) {
            // Parse header
            if let colonIndex = line.firstIndex(of: ":") {
                let headerName = String(line[..<colonIndex])
                let headerValue = String(line[colonIndex+1...])

                if headerName.lowercased() == "content-type" {
                    let ctParsed = parseContentType(headerValue)
                    ct = ctParsed.type + "/" + ctParsed.subtype
                    if let b = ctParsed.boundary {
                        // Will be handled by multipart parsing
                    }
                    if let enc = ctParsed.attributes["content-transfer-encoding"] {
                        encoding = enc
                    }
                    if let ch = ctParsed.attributes["charset"] {
                        charset = ch
                    }
                    if let n = ctParsed.attributes["name"] {
                        name = n
                    }
                } else if headerName.lowercased() == "content-disposition" {
                    let cd = parseContentDisposition(headerValue)
                    disposition = cd.disposition
                    filename = cd.filename
                }
            }
        }

        // Start of part body
        if line.hasPrefix(lineBreak) {
            inPart = true
            continue
        }

        // Check for multipart/alternative
        if ct != nil && ct.contains("multipart") {
            inPart = true
            continue
        }
    }

    return parts
}

// Parse file
func parseFile(_ path: String) -> (headers: [String: String], parts: [Entity]) {
    guard let contents = try? String(contentsOfFile: path, encoding: .utf8),
          let lines = contents.components(separatedBy: String(CharacterSet(charactersIn: "\r\n"))),
          let firstLine = lines.first else {
        return ([], [Entity(type: "text", subtype: "plain")])
    }

    // Determine line break
    let lineBreak = "\r\n"

    var headers: [String: String] = [:]
    var currentPart: [String] = []
    var inBody = false

    for (i, line) in lines.enumerated() {
        if inBody {
            if line.hasPrefix(lineBreak) {
                inBody = false
                currentPart = []
            } else {
                currentPart.append(line)
            }
            continue
        }

        if line.hasPrefix(lineBreak) {
            inBody = true
            currentPart = []
            continue
        }

        // Parse header
        if let colonIndex = line.firstIndex(of: ":") {
            let headerName = String(line[..<colonIndex])
            let headerValue = String(line[colonIndex+1...])

            let lowerName = headerName.lowercased()
            headers[lowerName] = headerValue

            // Check for multipart boundary
            if lowerName == "content-type" {
                let ctParsed = parseContentType(headerValue)
                if let boundary = ctParsed.boundary {
                    // Will be handled in multipart parsing
                }
            }
        }
    }

    // Build body
    let body = currentPart.joined(separator: lineBreak)

    // Parse Content-Type
    let ct = headers["content-type"]
    var parts: [Entity] = []

    if let ct = ct {
        let ctParsed = parseContentType(ct)
        if let boundary = ctParsed.boundary {
            parts = parseMultipart(lines, boundary: boundary, lineBreak: lineBreak, headers: headers)
        } else {
            let encoding = ctParsed.attributes["content-transfer-encoding"] ?? "7bit"
            let charset = ctParsed.attributes["charset"] ?? "us-ascii"
            parts = [Entity(type: ctParsed.type, subtype: ctParsed.subtype, text: decodeContent(body, encoding, charset))]
        }
    } else {
        parts = [Entity(type: "text", subtype: "plain", text: decodeContent(body, "7bit", "us-ascii"))]
    }

    return (headers, parts)
}

// Main function
func main() {
    guard let args = Array(CommandLine.arguments).suffices(1), !args.isEmpty else {
        print("Usage: main <directory>")
        exit(1)
    }

    let directory = args[0]
    var files: [String] = []

    do {
        let dirContents = try FileManager.default.contentsOfDirectory(atPath: directory)
        files = dirContents.sorted { $0 < $1 }
    } catch {
        print("Error accessing directory: \(error)")
        exit(1)
    }

    for file in files {
        let path = "\(directory)/\(file)"
        let (headers, parts) = parseFile(path)

        print("== \(file)")

        // From
        if let from = headers["from"] {
            print("From: \"\(decodeHeader(from))\"")
        }

        // Subject
        if let subject = headers["subject"] {
            print("Subject: \"\(decodeHeader(subject))\"")
        }

        // Print tree
        for part in parts {
            printTree(part)
        }
        print()
    }
}

func printTree(_ entity: Entity, indent: Int = 0) {
    let indentStr = String(repeating: "  ", count: indent)

    if entity.type == "multipart" {
        print("\(indentStr)multipart/\(entity.subtype) parts=\(entity.parts.count)")
        for part in entity.parts {
            printTree(part, indent: indent + 1)
        }
    } else if entity.type == "text" {
        let disposition = entity.disposition ?? "-"
        let encoding = entity.encoding ?? "7bit"
        let charset = entity.charset ?? "us-ascii"

