            print("\(indentStr)text/\(entity.subtype) charset=\(charset) cte=\(encoding) disposition=\(disposition) name=\(entity.name ?? "-")")
        } else {
            if let text = entity.text {
                let charCount = text.count
                print("\(indentStr)text/\(entity.subtype) charset=\(charset) cte=\(encoding) chars=\(charCount)")
