// Base64url decode with padding
function base64urlDecode(input: string): Buffer {
  const padding = 4 - (input.length % 4);
  if (padding !== 4) {
    input += '='.repeat(padding);
  }
  return Buffer.from(input.replace(/-/g, '+').replace(/_/g, '/'), 'base64');
}

// Validate base64url string (only A-Z a-z 0-9 - _)
function isValidBase64url(input: string): boolean {
  if (input === '') return false;
  return /^[A-Za-z0-9_-]*$/.test(input);
}

// Decode JSON from Buffer (UTF-8)
function decodeJSON(buffer: Buffer): any {
  return JSON.parse(buffer.toString('utf-8'));
}

// Validate JWT structure: check segments and decode header/payload
function validateStructure(token: string): string {
  const parts = token.split('.');
  if (parts.length !== 3) return 'MALFORMED';
  for (const part of parts) {
    if (part === '') return 'MALFORMED';
    if (!isValidBase64url(part)) return 'MALFORMED';
  }
  try {
    const headerBuffer = base64urlDecode(parts[0]);
    const header = decodeJSON(headerBuffer);
    if (typeof header !== 'object' || header === null || Array.isArray(header)) return 'MALFORMED';
  } catch {
    return 'MALFORMED';
  }
  try {
    const payloadBuffer = base64urlDecode(parts[1]);
    const payload = decodeJSON(payloadBuffer);
    if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) return 'MALFORMED';
  } catch {
    return 'MALFORMED';
  }
  return '';
}

// Validate algorithm
function validateAlgorithm(header: any): string {
  if (header.alg === undefined || typeof header.alg !== 'string') return 'UNSUPPORTED_ALG';
  const alg = header.alg;
  if (alg === 'none') return 'UNSUPPORTED_ALG';
  if (!['HS256', 'HS384', 'HS512'].includes(alg)) return 'UNSUPPORTED_ALG';
  return '';
}

// Find key by kid
function findKey(kid: string, keys: any[]): any | null {
  return keys.find((k) => k.kid === kid) || null;
}

// Validate key match
function validateKeyMatch(header: any, keys: any[]): string {
  if (header.kid === undefined) return 'UNKNOWN_KEY';
  const key = findKey(header.kid, keys);
  if (key === null) return 'UNKNOWN_KEY';
  if (key.alg !== header.alg) return 'ALG_MISMATCH';
  return '';
}

// Calculate HMAC signature
function calculateHMAC(alg: string, input: string, key: string): Buffer {
  const hash = crypto.createHmac(alg, key);
  hash.update(input);
  return hash.digest();
}

// Validate signature
function validateSignature(token: string, header: any, key: string): string {
  const [headerPart, payloadPart, signaturePart] = token.split('.');
  const signingInput = `${headerPart}.${payloadPart}`;
  const signatureBuffer = base64urlDecode(signaturePart);
  const expectedSignature = calculateHMAC(header.alg, signingInput, key);
  if (!crypto.timingSafeEqual(signatureBuffer, expectedSignature)) {
    return 'BAD_SIGNATURE';
  }
  return '';
}

// Main program
function main(): void {
  const config = JSON.parse(fs.readFileSync('config.json', 'utf-8'));
  const configKeys = config.keys;

  const tokensContent = fs.readFileSync('tokens.txt', 'utf-8');
  const lines = tokensContent.split('\n');
  const results: { lineNum: number; result: string; sub: string; scopes: string[] }[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();
    if (trimmed === '') continue;
    results.push({ lineNum: i + 1, result: '', sub: '', scopes: [] });
  }

  const validCount = 0;
  const invalidCount = 0;

  for (const res of results) {
    const token = res.lineNum > 0 ? lines[res.lineNum - 1].trim() : '';
    if (token === '') continue;
    const parts = token.split('.');
    if (parts.length !== 3) {
      res.result = 'MALFORMED';
      invalidCount++;
      continue;
    }
    for (const part of parts) {
      if (part === '' || !isValidBase64url(part)) {
        res.result = 'MALFORMED';
        invalidCount++;
        break;
      }
    }
    if (res.result === 'MALFORMED') {
      continue;
    }
    let header: any;
    let payload: any;
    let headerBuffer: Buffer;
    let payloadBuffer: Buffer;
    try {
      headerBuffer = base64urlDecode(parts[0]);
      header = decodeJSON(headerBuffer);
      payloadBuffer = base64urlDecode(parts[1]);
      payload = decodeJSON(payloadBuffer);
    } catch {
      res.result = 'MALFORMED';
      invalidCount++;
      continue;
    }
    const alg = header.alg;
    if (alg === undefined || typeof alg !== 'string' || !['HS256', 'HS384', 'HS512'].includes(alg)) {
      res.result = 'UNSUPPORTED_ALG';
      invalidCount++;
      continue;
    }
    if (header.kid === undefined) {
      res.result = 'UNKNOWN_KEY';
      invalidCount++;
      continue;
    }
    const key = findKey(header.kid, configKeys);
    if (key === null) {
      res.result = 'UNKNOWN_KEY';
      invalidCount++;
      continue;
    }
    if (key.alg !== alg) {
      res.result = 'ALG_MISMATCH';
      invalidCount++;
      continue;
    }
    const signingInput = `${parts[0]}.${parts[1]}`;
    const expectedSig = calculateHMAC(alg, signingInput, key.k);
    const sigBuffer = base64urlDecode(parts[2]);
    if (!crypto.timingSafeEqual(sigBuffer, expectedSig)) {
      res.result = 'BAD_SIGNATURE';
      invalidCount++;
      continue;
    }
    const now = config.now;
    const leeway = config.leeway;
    if (payload.exp !== undefined && now >= payload.exp + leeway) {
      res.result = 'EXPIRED';
      invalidCount++;
      continue;
    }
    if (payload.nbf !== undefined && now + leeway < payload.nbf) {
      res.result = 'NOT_YET_VALID';
      invalidCount++;
      continue;
    }
    if (payload.iss === undefined || payload.iss !== config.issuer) {
      res.result = 'BAD_ISSUER';
      invalidCount++;
      continue;
    }
    const aud = payload.aud;
    if (aud === undefined || typeof aud !== 'string' || aud !== config.audience) {
      if (!Array.isArray(aud)) {
        res.result = 'BAD_AUDIENCE';
        invalidCount++;
        continue;
      }
      if (aud.length === 0 || !aud.includes(config.audience)) {
        res.result = 'BAD_AUDIENCE';
        invalidCount++;
        continue;
      }
    }
    res.result = 'VALID';
    validCount++;
    if (payload.sub !== undefined) {
      let decodedSub = payload.sub;
      decodedSub = decodedSub.replace(/\\u([0-9a-fA-F]{2})/g, (m, p) => String.fromCharCode(parseInt(p, 16)));
      res.sub = decodedSub;
    }
    if (payload.scope !== undefined) {
      const scopes = payload.scope.split(' ').filter((s) => s.trim() !== '');
      res.scopes = [...new Set(scopes)].sort((a, b) => a.codePointAt(0) - b.codePointAt(0));
    }
  }

  for (const res of results) {
    if (res.result === 'VALID') {
      const scopeStr = res.scopes.join(',');
      console.log(`${res.lineNum}: VALID sub=${res.sub} scope=${scopeStr}`);
    } else {
      console.log(`${res.lineNum}: ${res.result}`);
    }
  }
  console.log('');
  console.log(`valid=${validCount} invalid=${invalidCount}`);
}

main();

