use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::Path;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <directory>", args[0]);
        std::process::exit(1);
    }

    let dir = &args[1];

    let config_content = match fs::read_to_string(Path::new(dir).join("config.json")) {
        Ok(content) => content,
        Err(_) => {
            eprintln!("Error reading config.json");
            std::process::exit(1);
        }
    };

    let config = match parse_config(&config_content) {
        Ok(config) => config,
        Err(e) => {
            eprintln!("Error parsing config: {}", e);
            std::process::exit(1);
        }
    };

    let tokens_content = match fs::read_to_string(Path::new(dir).join("tokens.txt")) {
        Ok(content) => content,
        Err(_) => {
            eprintln!("Error reading tokens.txt");
            std::process::exit(1);
        }
    };

    let tokens = parse_tokens(&tokens_content);

    let mut valid_count = 0;
    let mut invalid_count = 0;

    for (n, token) in tokens {
        let result = verify_token(n, &config, &token);
        println!("{}: {}", n, result);
        if result == "VALID" {
            valid_count += 1;
        } else {
            invalid_count += 1;
        }
    }

    println!();
    println!("valid={} invalid={}", valid_count, invalid_count);
}

fn parse_config(content: &str) -> Result<Config, String> {
    let mut now = 0;
    let mut leeway = 0;
    let mut issuer = String::new();
    let mut audience = String::new();
    let mut keys = HashMap::new();

    let mut in_keys = false;
    let mut key_idx = 0;
    let mut line = String::new();

    for ch in content.chars() {
        if ch == '{' {
            in_keys = false;
            line.clear();
            continue;
        }

        if ch == '{' || ch == '[' {
            if !line.is_empty() && line.trim().ends_with('}')) {
                in_keys = true;
                line.clear();
                continue;
            }
            line.push(ch);
            continue;
        }

        if ch == '}' {
            in_keys = false;
            line.clear();
            continue;
        }

        if ch == '\n' {
            if let Some(idx) = line.find(|c: char| c.is_whitespace()) {
                let key = line[..idx].trim().to_string();
                let val = line[idx + 1..].trim().to_string();
                if key == "now" {
                    now = parse_number(&val);
                } else if key == "leeway" {
                    leeway = parse_number(&val);
                } else if key == "issuer" {
                    issuer = val;
                } else if key == "audience" {
                    audience = val;
                }
            }

            if in_keys {
                let key = line.trim();
                let val = line.trim();
                if let Some(kid) = keys.get(key) {
                    if let Some(val) = parse_key_value(val) {
                        keys.insert(kid.clone(), val);
                    }
                }
            }
            line.clear();
            continue;
        }

        line.push(ch);
    }

    Ok(Config {
        now,
        leeway,
        issuer,
        audience,
        keys,
    })
}

fn parse_tokens(content: &str) -> Vec<(usize, String)> {
    let mut tokens = Vec::new();
    for line in content.lines() {
        let trimmed = line.trim();
        if !trimmed.is_empty() {
            tokens.push((tokens.len() + 1, trimmed.to_string()));
        }
    }
    tokens
}

fn verify_token(n: usize, config: &Config, token: &str) -> String {
    let segments: Vec<&str> = token.split('.').collect();

    if segments.len() != 3 {
        return format!("{}. MALFORMED", n);
    }

    if segments[0].is_empty() || segments[1].is_empty() || segments[2].is_empty() {
        return format!("{}. MALFORMED", n);
    }

    if !segments[0].is_valid_base64url() {
        return format!("{}. MALFORMED", n);
    }

    if !segments[1].is_valid_base64url() {
        return format!("{}. MALFORMED", n);
    }

    if !segments[2].is_valid_base64url() {
        return format!("{}. MALFORMED", n);
    }

    let header = decode_base64url(&segments[0]);
    let header_json = match parse_json(&header) {
        Ok(j) => j,
        Err(_) => return format!("{}. MALFORMED", n),
    };

    if !header_json.is_object() {
        return format!("{}. MALFORMED", n);
    }

    let payload = decode_base64url(&segments[1]);
    let payload_json = match parse_json(&payload) {
        Ok(j) => j,
        Err(_) => return format!("{}. MALFORMED", n),
    };

    if !payload_json.is_object() {
        return format!("{}. MALFORMED", n);
    }

    let alg = match header_json.get("alg") {
        Some(a) => a.as_str(),
        None => return format!("{}. MALFORMED", n),
    };

    if alg.is_none() || !["HS256", "HS384", "HS512"].contains(&alg.as_str()) {
        return format!("{}. UNSUPPORTED_ALG", n);
    }

    let kid = match header_json.get("kid") {
        Some(k) => k.as_str(),
        None => return format!("{}. UNKNOWN_KEY", n),
    };

    let key = match config.keys.get(kid) {
        Some(k) => k,
        None => return format!("{}. UNKNOWN_KEY", n),
    };

    if key.alg != alg {
        return format!("{}. ALG_MISMATCH", n);
    }

    let signature = decode_base64url(&segments[2]);

    let signing_input = format!("{}.{}", segments[0], segments[1]);

    let expected_signature = match compute_hmac(&signing_input, &key.k) {
        Ok(s) => s,
        Err(_) => return format!("{}. BAD_SIGNATURE", n),
    };

    if signature != expected_signature {
        return format!("{}. BAD_SIGNATURE", n);
    }

    if payload_json.get("exp").is_some() {
        if let Some(exp) = payload_json.get("exp").and_then(|v| v.as_i64()) {
            if config.now >= exp + config.leeway {
                return format!("{}. EXPIRED", n);
            }
        }
    }

    if payload_json.get("nbf").is_some() {
        if let Some(nbf) = payload_json.get("nbf").and_then(|v| v.as_i64()) {
            if config.now + config.leeway < nbf {
                return format!("{}. NOT_YET_VALID", n);
            }
        }
    }

    if let Some(iss) = payload_json.get("iss") {
        if !iss.is_string() || iss.as_str() != config.issuer {
            return format!("{}. BAD_ISSUER", n);
        }
    }

    if let Some(aud) = payload_json.get("aud") {
        match aud {
            Some(a) => {
                if a.is_string() {
                    if a.as_str() != config.audience {
                        return format!("{}. BAD_AUDIENCE", n);
                    }
                } else if a.is_array() {
                    if a.as_array().iter().any(|a| a.as_str() == Some(config.audience)) {
                        // OK
                    } else {
                        return format!("{}. BAD_AUDIENCE", n);
                    }
                } else {
                    return format!("{}. BAD_AUDIENCE", n);
                }
            }
            None => return format!("{}. BAD_AUDIENCE", n),
        }
    }

    let sub = payload_json
        .get("sub")
        .and_then(|v| v.as_str())
        .map(|s| decode_json_escapes(s))
        .unwrap_or_default();

    let scope = payload_json
        .get("scope")
        .and_then(|v| v.as_str())
        .map(|s| {
            let parts: Vec<&str> = s.split_whitespace().filter(|p| !p.is_empty()).collect();
            let mut sorted = parts.clone();
            sorted.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));
            sorted.dedup();
            sorted.join(",")
        })
        .unwrap_or_default();

    format!("VALID sub={}", sub)
}

fn decode_base64url(input: &str) -> Result<Vec<u8>, String> {
    let mut result = Vec::new();
    let mut remainder = 0;
    let mut remainder_shift = 0;

    for c in input.chars() {
        let value = base64url_value(c);
        result.push((remainder + value) as u8);
        remainder = value >> 6;
        remainder_shift = 6;
    }

    if remainder != 0 {
        return Err("Invalid base64url".to_string());
    }

    Ok(result)
}

fn base64url_value(c: u8) -> u8 {
    match c {
        b'A'..=b'Z' => c - b'A',
        b'a'..=b'z' => c - b'a' + 26,
        b'0'..=b'9' => c - b'0' + 52,
        b'-' => 62,
        b'_' => 63,
        _ => return 0,
    }
}

fn parse_json(input: &[u8]) -> Result<serde_json::Value, String> {
    let s = String::from_utf8_lossy(input);
    serde_json::from_str(&s)
}

fn parse_number(s: &str) -> u64 {
    s.trim().parse().unwrap_or(0)
}

fn parse_key_value(s: &str) -> Option<(String, String)> {
    let mut parts = s.split(':');
    let kid = parts.next()?.trim().to_string();
    let k = parts.next()?.trim().to_string();
    Some((kid, k))
}

fn is_valid_json_object(s: &str) -> bool {
    let trimmed = s.trim();
    if trimmed.starts_with('{') && trimmed.ends_with('}') {
        true
    } else {
        false
    }
}

fn is_valid_base64url(s: &str) -> bool {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            'A'..='Z' | 'a'..='z' | '0'..='9' | '-' | '_' => {}
            _ => return false,
        }
        i += 1;
    }
    let len = chars.len();
    if len % 4 != 0 {
        return false;
    }
    true
}

fn compute_hmac(input: &str, key: &[u8]) -> Result<Vec<u8>, String> {
    let input_bytes = input.as_bytes();
    match key.len() {
        32 => hmac::new(key, hmac::sha256()).map(|h| h.finalize().to_vec()),
        48 => hmac::new(key, hmac::sha384()).map(|h| h.finalize().to_vec()),
        64 => hmac::new(key, hmac::sha512()).map(|h| h.finalize().to_vec()),
        _ => Err("Invalid key length".to_string()),
    }
}

