    }

    private static void parseMimeFile(File file) throws Exception {
        byte[] data = Files.readAllBytes(file.toPath());
        Message message = parseMime(data);
        printMessage(message, 0);
    }

    private static Message parseMime(byte[] data) throws Exception {
        String content = new String(data, StandardCharsets.ISO_8859_1);
        return parseMessage(content);
    }

    private static Message parseMessage(String content) throws Exception {
        String[] lines = content.split("\n", -1);
        int headerEnd = findHeaderEnd(lines);
        List<HeaderLine> headers = parseHeaders(lines, 0, headerEnd);
        String body = content.substring(headerEnd + 1);

        Message message = new Message(headers, body);

        return message;
    }

