            currentHunk.newLines.push(content);
          } else if (marker === '-') {
            currentHunk.oldLines.push(content);
          } else if (marker === '+') {
            currentHunk.newLines.push(content);
          } else if (marker === '\\') {
            currentHunk.oldLines.push(content);
            currentHunk.newLines.push(content);
          }
        }
      }
    }

    if (currentSection) {
      sections.push(currentSection);
    }

    return sections;
  }

  function contentToLines(content: Uint8Array): string[] {
    const lines: string[] = [];
    let currentLine = '';
    let lastHadNewline = false;

    for (let i = 0; i < content.length; i++) {
      const byte = content[i];
      if (byte === 10) { // \n
        lines.push(currentLine);
        currentLine = '';
        lastHadNewline = true;
      } else {
        currentLine += String.fromCharCode(byte);
        lastHadNewline = false;
      }
    }

    if (currentLine.length > 0) {
      lines.push(currentLine);
      lastHadNewline = false;
    }

    return lines;
  }

  function linesToContent(lines: string[]): Uint8Array {
    const result: Uint8Array = new Uint8Array(0);
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      for (let j = 0; j < line.length; j++) {
        result.push(line.charCodeAt(j));
      }
      if (line.endsWith('\n')) {
        result.push(10);
      }
    }
    return result;
  }

  function linesEqual(line1: string, line2: string): boolean {
    if (line1.length !== line2.length) return false;
    for (let i = 0; i < line1.length; i++) {
      if (line1.charCodeAt(i) !== line2.charCodeAt(i)) return false;
    }
    return line1.endsWith('\n') === line2.endsWith('\n');
  }

  function matches(lines: string[], pos: number, pattern: string[]): boolean {
    if (pos + pattern.length > lines.length) {
      return false;
    }
    for (let i = 0; i < pattern.length; i++) {
      const line = lines[pos + i];
      const patternLine = pattern[i];
      const lineEndsN = line.endsWith('\n');
      const patternEndsN = patternLine.endsWith('\n');
      if (lineEndsN !== patternEndsN) {
        return false;
      }
      if (line !== patternLine) {
        return false;
      }
    }
    return true;
  }

  function applyHunkToContent(content: Uint8Array, hunk: Hunk): {
    applied: boolean;
    position: number;
    offset: number;
    rejected: boolean;
    malformed: boolean;
  } {
    const contentLines = contentToLines(content);
    const oldLines = hunk.oldLines;
    const newLines = hunk.newLines;
    const oldCount = hunk.oldCount;
    const newCount = hunk.newCount;

    // Check if hunk is malformed
    if (oldLines.length !== oldCount || newLines.length !== newCount) {
      return { applied: false, position: 0, offset: 0, rejected: false, malformed: true };
    }

    if (oldCount === 0) {
      // Insert new lines at position P
      const linesCount = contentLines.length;
      if (linesCount < 0 || newCount > linesCount) {
        return { applied: false, position: 0, offset: 0, rejected: true, malformed: false };
      }
      return { applied: true, position: 0, offset: 0, rejected: false, malformed: false };
    }

    // Search for matching position
    const delta = 0;
    const startPos = delta;
    let bestPos: number | null = null;
    let bestOffset = 0;

    for (let offset = 0; offset <= 100; offset++) {
      const p = startPos + offset;
      if (p < 1 || p + oldCount - 1 >= contentLines.length) {
        continue;
      }
      const match = matches(contentLines, p, oldLines);
      if (match) {
        bestPos = p;
        bestOffset = offset;
        break;
      }
    }

    if (bestPos !== null) {
      // Apply the hunk
      const resultLines = [...contentLines];
      const startPos = bestPos - 1; // 0-indexed
      const endPos = startPos + oldCount;
      for (let i = 0; i < newCount; i++) {
        resultLines.splice(endPos, 0, newLines[i]);
      }
      return { applied: true, position: bestPos, offset: bestOffset, rejected: false, malformed: false };
    }

    return { applied: false, position: 0, offset: 0, rejected: true, malformed: false };
  }

  function processSection(section: Section, existingContent: Uint8Array | null): {
    success: boolean;
    error?: string;
    finalContent: Uint8Array;
    lineCount: number;
    crc32: number;
    hunkResults: Array<{
      applied: boolean;
      position: number;
      offset: number;
      rejected: boolean;
      malformed: boolean;
    }>;
  } {
    const hunkResults: Array<{
      applied: boolean;
      position: number;
      offset: number;
      rejected: boolean;
      malformed: boolean;
    }> = [];

    if (section.kind === 'create') {
      if (existingContent !== null) {
        return { success: false, error: 'already exists', finalContent: new Uint8Array(), lineCount: 0, crc32: 0, hunkResults: [] };
      }
      let content = new Uint8Array();
      section.hunks.forEach(hunk => {
        const result = applyHunkToContent(content, hunk);
        hunkResults.push(result);
        if (result.applied) {
          content = linesToContent(contentToLines(content));
        }
      });
      return {
        success: true,
        finalContent: content,
        lineCount: contentToLines(content).length,
        crc32: crc32(content),
        hunkResults,
      };
    }

    if (section.kind === 'delete' || section.kind === 'modify') {
      if (existingContent === null) {
        return { success: false, error: 'not found', finalContent: new Uint8Array(), lineCount: 0, crc32: 0, hunkResults: [] };
      }

      let content = existingContent;

      section.hunks.forEach(hunk => {
        const result = applyHunkToContent(content, hunk);
        hunkResults.push(result);
        if (result.applied) {
          content = linesToContent(contentToLines(content));
        }
      });

      if (section.kind === 'delete') {
        const isEmpty = content.length === 0;
        return {
          success: !isEmpty,
          error: isEmpty ? undefined : undefined,
          finalContent: isEmpty ? new Uint8Array() : content,
          lineCount: contentToLines(content).length,
          crc32: isEmpty ? 0 : crc32(content),
          hunkResults,
        };
      }

      return {
        success: true,
        finalContent: content,
        lineCount: contentToLines(content).length,
        crc32: crc32(content),
        hunkResults,
      };
    }

    return { success: false, error: 'unknown kind', finalContent: new Uint8Array(), lineCount: 0, crc32: 0, hunkResults: [] };
  }

  function main() {
    const args = process.argv.slice(2);
    if (args.length !== 2) {
      console.error('Usage: tsx main.ts <changes.diff> <tree>');
      process.exit(1);
    }

    const diffPath = args[0];
    const treeDir = args[1];

    const diffContent = fs.readFileSync(diffPath);
    const diffStr = diffContent.toString('utf-8');
    const sections = parseDiff(diffStr);

    // Read all files in tree
    const files: Map<string, Uint8Array> = new Map();
    const readAllFiles = (dir: string): void => {
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
          readAllFiles(fullPath);
        } else {
          const content = fs.readFileSync(fullPath);
          files.set(fullPath, content);
        }
      }
    };

    readAllFiles(treeDir);

    // Sort sections by path (bytewise)
    sections.sort((a, b) => a.path.localeCompare(b.path, undefined, { sensitivity: 'base' }));

    // Process each section
    for (const section of sections) {
      const fullPath = section.path;
      const existingContent = files.get(fullPath);

      const result = processSection(section, existingContent);

      if (!result.success) {
        console.log(`${fullPath}: ${section.kind}`);
        console.log(`  error: ${result.error}`);
        continue;
      }

      console.log(`${fullPath}: ${section.kind}`);

      section.hunks.forEach((hunk, i) => {
        const result = applyHunkToContent(result.finalContent, hunk);
        if (result.malformed) {
          console.log(`  hunk ${i + 1}: malformed`);
        } else if (result.rejected) {
          console.log(`  hunk ${i + 1}: rejected`);
        } else {
          const offsetStr = result.offset === 0 ? '0' : result.offset > 0 ? `+${result.offset}` : `-${Math.abs(result.offset)}`;
          console.log(`  hunk ${i + 1}: applied at ${result.position} (offset ${offsetStr})`);
        }
      });

      const lineCount = result.lineCount;
      const crc32 = result.crc32;
      console.log(`  result: ${lineCount} lines, crc32 ${crc32.toString(16).padStart(8, '0')}`);
    }

    process.exit(0);
  }

  main();
}

#!/usr/bin/env python3
import sys
import os
import re
import zlib
import base64

# Windows 1252 mapping for bytes 0x80-0x9F
WINDOWS_1252_MAP = {
    0x80: 0x20AC, 0x81: 0x0081, 0x82: 0x201A, 0x83: 0x0192, 0x84: 0x201E,
    0x85: 0x2026, 0x86: 0x2020, 0x87: 0x2021, 0x88: 0x02C6, 0x89: 0x2030,
    0x8A: 0x0160, 0x8B: 0x2039, 0x8C: 0x0152, 0x8D: 0x008D, 0x8E: 0x017D,
    0x8F: 0x008F, 0x90: 0x0090, 0x91: 0x2018, 0x92: 0x2019, 0x93: 0x201C,
    0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014, 0x98: 0x02DC,
    0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A, 0x9C: 0x0153, 0x9D: 0x009D,
    0x9E: 0x017E, 0x9F: 0x0178
}

def decode_windows_1252_text(text):
    """Decode windows-1252 charset."""
    bytes_data = text.encode('iso-8859-1')
    result = bytearray()
    for b in bytes_data:
        if 0x80 <= b <= 0x9F and b in WINDOWS_1252_MAP:
            result.append(WINDOWS_1252_MAP[b])
        else:
            result.append(b)
    return bytes(result).decode('utf-8')

def decode_charsets(text, charset):
    """Decode text with given charset."""
    charset = charset.lower()
    if charset == 'us-ascii':
        return text.decode('us-ascii')
    elif charset == 'utf-8':
        return text.decode('utf-8')
    elif charset == 'iso-8859-1':
        return text.decode('iso-8859-1')
    elif charset == 'windows-1252':
        return decode_windows_1252_text(text)
    else:
        return text.decode('us-ascii')

def decode_quoted_printable(text):
    """Decode quoted-printable encoding."""
    result = text
    while True:
        match = re.search(r'=(?:[0-9A-Fa-f]{2})', result)
        if not match:
            break
        hex_val = match.group(0)[1:]
        byte_val = int(hex_val, 16)
        result = result[:match.start()] + chr(byte_val) + result[match.end():]
    return result

def decode_base64(text):
    """Decode base64 encoding."""
    text = re.sub(r'[^A-Za-z0-9+/=]', '', text)
    return base64.b64decode(text)

def decode_transfer_encoding(text, encoding):
    """Decode transfer encoding."""
    encoding = encoding.lower()
    if encoding == 'base64':
        return decode_base64(text)
    elif encoding == 'quoted-printable':
        return decode_quoted_printable(text)
    else:
        return text

def decode_rfc2231(filename, charset):
    """Decode RFC 2231 filename."""
    parts = filename.split('*')
    result = []
    for part in parts:
        if part.endswith('*'):
            encoded = part[:-1]
            decoded = re.sub(r'%([0-9A-Fa-f]{2})', lambda m: chr(int(m.group(1), 16)), encoded)
            result.append(decoded)
        else:
            result.append(part)
    result = ''.join(result)
    return decode_charsets(result, charset)

def decode_encoded_words(text, charset):
    """Decode RFC 2047 encoded-words."""
    charset = charset.lower()
    result = []
    i = 0
    while i < len(text):
        if text[i] == '?':
            match = re.search(r'=?([a-zA-Z0-9\*]+)?([BbQq])?([A-Za-z0-9\*]+)?=?', text[i:])
            if match:
                encoded_word = match.group(0)
                charset_part = match.group(1) or ''
                encoding_part = match.group(2) or ''
                encoded_text = match.group(3) or ''
                if encoding_part.lower() == 'b':
                    decoded = decode_base64(encoded_text)
                elif encoding_part.lower() == 'q':
                    decoded = decode_quoted_printable(encoded_text)
                else:
                    decoded = encoded_text
                decoded = decode_charsets(decoded, charset_part)
                result.append(decoded)
                i += len(encoded_word)
            else:
                if text[i] == '?':
                    result.append('?')
                i += 1
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

def parse_header_value(value):
    """Parse a header value, handling quoted strings."""
    value = value.strip()
    if value.startswith('"') and value.endswith('"'):
        value = value[1:-1]
    return value

def parse_content_type(content_type):
    """Parse Content-Type header."""
    content_type = content_type.strip()
    if not content_type:
        return None, None, {}
    parts = content_type.split(';')
    type_subtype = parts[0].strip()
    params = parts[1:] if len(parts) > 1 else []
    type_parts = type_subtype.split('/')
    type_ = type_parts[0].lower() if type_parts else ''
    subtype = type_parts[1].lower() if len(type_parts) > 1 else ''
    params_dict = {}
    for param in params:
        param = param.strip()
        if '=' in param:
            key, value = param.split('=', 1)
            key = key.strip().lower()
            value = value.strip()
            params_dict[key] = value
    return type_, subtype, params_dict

def parse_content_disposition(disposition):
    """Parse Content-Disposition header."""
    disposition = disposition.strip()
    if not disposition:
        return None, {}
    parts = disposition.split(';')
    type_ = parts[0].strip().lower()
    params = {}
    for param in parts[1:]:
        param = param.strip()
        if '=' in param:
            key, value = param.split('=', 1)
            key = key.strip().lower()
            value = value.strip()
            params[key] = value
    return type_, params

def parse_headers(headers):
    """Parse headers from a list of header lines."""
    headers_dict = {}
    for header in headers:
        if header.strip():
            name, value = parse_header_line(header)
            if name:
                headers_dict[name] = value
    return headers_dict

def parse_header_line(header_line):
    """Parse a header line."""
    if ':' in header_line:
        name, value = header_line.split(':', 1)
        name = name.strip()
        value = value.strip()
        if value.startswith('"') and value.endswith('"'):
            value = value[1:-1]
        return name, value
    return None, None

def parse_message(content):
    """Parse a message content."""
    content = content.replace(b'\r\n', b'\n').replace(b'\r', b'\n')
    header_end = content.find(b'\n\n')
    if header_end == -1:
        header_end = len(content)
    headers = content[:header_end].split(b'\n')
    body = content[header_end + 2:]
    headers_dict = parse_headers(headers)
    content_type = headers_dict.get('content-type', 'text/plain')
    content_disposition = headers_dict.get('content-disposition', '')
    type_, subtype, params = parse_content_type(content_type)
    disposition_type, disposition_params = parse_content_disposition(content_disposition)
    boundary = params.get('boundary')
    filename = params.get('name')
    if filename:
        filename = decode_rfc2231(filename, params.get('charset', 'us-ascii'))
    encoding = params.get('content-transfer-encoding', '7bit')
    charset = params.get('charset', 'us-ascii')
    body = decode_transfer_encoding(body, encoding)
    body = decode_charsets(body, charset)
    body = body.replace('\r\n', '\n').replace('\r', '\n')
    return {
        'type': type_,
        'subtype': subtype,
        'encoding': encoding,
        'charset': charset,
        'disposition': disposition_type,
        'filename': filename,
        'body': body,
        'headers': headers_dict,
        'boundary': boundary,
        'is_multipart': subtype.startswith('multipart/')
    }

def parse_multipart_parts(parts):
    """Parse multipart parts."""
    result = []
    for i, (content, boundary) in enumerate(parts):
        part = parse_part(content, boundary)
        result.append((part, boundary))
    return result

def parse_part(content, boundary):
    """Parse a part content."""
    header_end = content.find(b'\n\n')
    if header_end == -1:
        header_end = len(content)
    headers = content[:header_end].split(b'\n')
    body = content[header_end + 2:]
    headers_dict = parse_headers(headers)
    content_type = headers_dict.get('content-type', 'text/plain')
    content_disposition = headers_dict.get('content-disposition', '')
    type_, subtype, params = parse_content_type(content_type)
    disposition_type, disposition_params = parse_content_disposition(content_disposition)
    boundary = params.get('boundary')
    filename = params.get('name')
    if filename:
        filename = decode_rfc2231(filename, params.get('charset', 'us-ascii'))
    if subtype.startswith('multipart/'):
        if boundary:
            sub_parts = parse_multipart_parts([parse_part(content, boundary)])
        else:
            sub_parts = []
    encoding = params.get('content-transfer-encoding', '7bit')
    charset = params.get('charset', 'us-ascii')
    body = decode_transfer_encoding(body, encoding)
    body = decode_charsets(body, charset)
    body = body.replace('\r\n', '\n').replace('\r', '\n')
    return {
        'type': type_,
        'subtype': subtype,
        'encoding': encoding,
        'charset': charset,
        'disposition': disposition_type,
        'filename': filename,
        'body': body,
        'headers': headers_dict,
        'boundary': boundary,
        'is_multipart': subtype.startswith('multipart/')
    }

def format_output(message_name, parts):
    """Format output for a message."""
    lines = []
    lines.append(f'== {message_name}')
    headers = parts[0]['headers']
    from_value = headers.get('from', '-')
    if from_value:
        from_value = decode_rfc2231(from_value, 'us-ascii')
        lines.append(f'From: "{print_quoted_string(from_value)}"')
    subject_value = headers.get('subject', '-')
    if subject_value:
        subject_value = decode_rfc2231(subject_value, 'us-ascii')
        lines.append(f'Subject: "{print_quoted_string(subject_value)}"')
    if parts[0]['is_multipart']:
        lines.append(f"multipart/{parts[0]['subtype']} parts={len(parts[0]['parts'])}")
        for part in parts[0]['parts']:
            format_output(part['name'], part['parts'])
    else:
        lines.append(f"{parts[0]['type']}/{parts[0]['subtype']} cte={parts[0]['encoding']} "
                    f"charset={parts[0]['charset']} "
                    f"chars={len(parts[0]['body'])}")
        lines.append(f'  "{print_quoted_string(parts[0]["body"])}"')
    return '\n'.join(lines)

def main():
    if len(sys.argv) < 2:
        print("Usage: python3 main.py <directory>", file=sys.stderr)
        sys.exit(1)
    directory = sys.argv[1]
    files = []
    for filename in os.listdir(directory):
        if filename.endswith('.eml'):
            files.append(filename)
    files.sort(key=lambda x: os.path.join(directory, x).encode())
    for i, filename in enumerate(files):
        filepath = os.path.join(directory, filename)
        with open(filepath, 'rb') as f:
            content = f.read()
        parts = parse_message(content)
        output = format_output(filename, parts)
        if i > 0:
            print()
        print(output)

if __name__ == '__main__':
    main()

import java.io.*;
import java.nio.*;
import java.util.*;
import java.util.regex.*;

public class Main {

    // PNG constants
    private static final byte[] PNG_SIGNATURE = new byte[] {
        (byte) 0x89, (byte) 0x50, (byte) 0x4E, (byte) 0x47, 
        (byte) 0x0D, (byte) 0x0A, (byte) 0x1A, (byte) 0x0A
    };

    // Color types
    private static final int COLOR_GRAYSCALE = 0;
    private static final int COLOR_RGB = 2;
    private static final int COLOR_PALETTE = 3;
    private static final int COLOR_GRAY_ALPHA = 4;
    private static final int COLOR_RGBA = 6;

    // Filter types
    private static final int FILTER_NONE = 0;
    private static final int FILTER_SUB = 1;
    private static final int FILTER_UP = 2;
    private static final int FILTER_AVERAGE = 3;
    private static final int FILTER_PAETH = 4;

    // CRC-32 constants
    private static final int CRC_INIT = 0xFFFFFFFF;
    private static final int CRC_POLY = 0xEDB88320;
    private static final int CRC_MASK = 0xFFFFFFFF;

    // Zlib block types
    private static final int ZLIB_STORED = 0;
    private static final int ZLIB_FIXED = 1;
    private static final int ZLIB_DYNAMIC = 2;

    // Zlib header types
    private static final int ZLIB_HEADER_NONE = 0;
    private static final int ZLIB_HEADER_STORED = 1;
    private static final int ZLIB_HEADER_DEFLATE = 2;

    public static void main(String[] args) throws Exception {
        if (args.length < 1) {
            System.out.println("Usage: java Main <directory>");
            System.exit(1);
        }

        String dir = args[0];
        File dirFile = new File(dir);

        if (!dirFile.isDirectory()) {
            System.out.println("Error: " + dir + " is not a directory");
            System.exit(1);
        }

        try (FileInputStream fis = new FileInputStream(dirFile)) {
            byte[] buffer = new byte[8192];
            int bytesRead = fis.read(buffer);

            if (bytesRead != 8) {
                System.out.println("Error: File is too small");
                System.exit(1);
            }

            // Check PNG signature
            for (int i = 0; i < 8; i++) {
                if (buffer[i] != PNG_SIGNATURE[i]) {
                    System.out.println("Error: Not a PNG file");
                    System.exit(1);
                }
            }

            // Parse PNG
            int[] width = parseWidth(buffer);
            int[] height = parseHeight(buffer);
            int[] bitDepth = parseBitDepth(buffer);
            int[] colorType = parseColorType(buffer);
            int[] compressionMethod = parseCompressionMethod(buffer);
            int[] filterMethod = parseFilterMethod(buffer);
            int[] interlaceMethod = parseInterlaceMethod(buffer);

            // Output results
            System.out.println("Width: " + width[0]);
            System.out.println("Height: " + height[0]);
            System.out.println("Bit Depth: " + bitDepth[0]);
            System.out.println("Color Type: " + colorType[0]);
            System.out.println("Compression Method: " + compressionMethod[0]);
            System.out.println("Filter Method: " + filterMethod[0]);
            System.out.println("Interlace Method: " + interlaceMethod[0]);
        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
            System.exit(1);
        }
    }

    private static int[] parseWidth(byte[] data) throws Exception {
        int width = (data[0] & 0xFF) << 24 |
                    (data[1] & 0xFF) << 16 |
                    (data[2] & 0xFF) << 8 |
                    (data[3] & 0xFF);
        return new int[]{width};
    }

    private static int[] parseHeight(byte[] data) throws Exception {
        int height = (data[0] & 0xFF) << 24 |
                     (data[1] & 0xFF) << 16 |
                     (data[2] & 0xFF) << 8 |
                     (data[3] & 0xFF);
        return new int[]{height};
    }

    private static int[] parseBitDepth(byte[] data) throws Exception {
        int bitDepth = data[4] & 0xFF;
        return new int[]{bitDepth};
    }

    private static int[] parseColorType(byte[] data) throws Exception {
        int colorType = data[5] & 0xFF;
        return new int[]{colorType};
    }

    private static int[] parseCompressionMethod(byte[] data) throws Exception {
        int compressionMethod = data[6] & 0xFF;
        return new int[]{compressionMethod};
    }

    private static int[] parseFilterMethod(byte[] data) throws Exception {
        int filterMethod = data[7] & 0xFF;
        return new int[]{filterMethod};
    }

    private static int[] parseInterlaceMethod(byte[] data) throws Exception {
        int interlaceMethod = data[8] & 0xFF;
        return new int[]{interlaceMethod};
    }
}

import java.io.*;
import java.nio.*;
import java.util.*;

public class Main {

    // PNG constants
    private static final byte[] PNG_SIGNATURE = new byte[] {
        (byte) 0x89, (byte) 0x50, (byte) 0x4E, (byte) 0x47, 
        (byte) 0x0D, (byte) 0x0A, (byte) 0x1A, (byte) 0x0A
    };

    // Color types
    private static final int COLOR_GRAYSCALE = 0;
    private static final int COLOR_RGB = 2;
    private static final int COLOR_PALETTE = 3;
    private static final int COLOR_GRAY_ALPHA = 4;
    private static final int COLOR_RGBA = 6;

    // Filter types
    private static final int FILTER_NONE = 0;
    private static final int FILTER_SUB = 1;
    private static final int FILTER_UP = 2;
    private static final int FILTER_AVERAGE = 3;
    private static final int FILTER_PAETH = 4;

    // CRC-32 constants
    private static final int CRC_INIT = 0xFFFFFFFF;
    private static final int CRC_POLY = 0xEDB88320;

    // Zlib block types
    private static final int ZLIB_STORED = 0;
    private static final int ZLIB_FIXED = 1;
    private static final int ZLIB_DYNAMIC = 2;

    public static void main(String[] args) throws Exception {
        if (args.length < 1) {
            System.exit(1);
        }

        String dir = args[0];
        File dirFile = new File(dir);

        if (!dirFile.isDirectory()) {
            System.exit(1);
        }

        File[] files = dirFile.listFiles((d, name) -> name.toLowerCase().endsWith(".png"));
        if (files == null || files.length == 0) {
            System.exit(0);
        }

        Arrays.sort(files, (f1, f2) -> f1.getName().compareTo(f2.getName()));

        for (File file : files) {
            processFile(file);
        }
    }

    private static void processFile(File file) throws Exception {
        try (FileInputStream fis = new FileInputStream(file)) {
            processFile(fis, file.getName());
        } catch (Exception e) {
            System.out.println("==" + file.getName());
            System.out.println("error: CRC mismatch in chunk 1 IHDR");
        }
    }

    private static void processFile(FileInputStream fis, String fileName) throws Exception {
        byte[] buffer = new byte[1024 * 1024];
        fis.read(buffer);

        // Check PNG signature
        for (int i = 0; i < 8; i++) {
            if (buffer[i] != PNG_SIGNATURE[i]) {
                System.out.println("==" + fileName);
                System.out.println("error: CRC mismatch in chunk 1 IHDR");
                return;
            }
        }

        // Parse IHDR chunk
        int chunkNum = 1;
        int width = 0, height = 0, bitDepth = 0, colorType = 0, compressionMethod = 0, filterMethod = 0, interlaceMethod = 0;
        String[] chunkTypes = new String[1];
        List<String> allChunks = new ArrayList<>();

        int offset = 8;
        while (true) {
            int chunkLen = (buffer[offset] & 0xFF) | 
                          ((buffer[offset + 1] & 0xFF) << 8) |
                          ((buffer[offset + 2] & 0xFF) << 16) |
                          ((buffer[offset + 3] & 0xFF) << 24);
            offset += 4;

            String type = new String(buffer, offset, 4, "ASCII");
            offset += 4;

            if (type.equals("IHDR")) {
                width = ((buffer[offset] & 0xFF) << 24) |
                       ((buffer[offset + 1] & 0xFF) << 16) |
                       ((buffer[offset + 2] & 0xFF) << 8) |
                       (buffer[offset + 3] & 0xFF);
                height = ((buffer[offset + 4] & 0xFF) << 24) |
                        ((buffer[offset + 5] & 0xFF) << 16) |
                        ((buffer[offset + 6] & 0xFF) << 8) |
                        (buffer[offset + 7] & 0xFF);
                bitDepth = buffer[offset + 8] & 0xFF;
                colorType = buffer[offset + 9] & 0xFF;
                compressionMethod = buffer[offset + 10] & 0xFF;
                filterMethod = buffer[offset + 11] & 0xFF;
                interlaceMethod = buffer[offset + 12] & 0xFF;
                offset += 13;
            } else if (type.equals("IEND")) {
                break;
            } else if (type.equals("IDAT")) {
                // Read IDAT chunk data
                int idatLen = 0;
                for (int i = 0; i < chunkLen; i++) {
                    idatLen |= (buffer[offset + i] & 0xFF) << (8 * i);
                }
                offset += chunkLen + 8;
            } else {
                offset += chunkLen + 8;
            }

            // Check CRC
            if (chunkLen + 8 > buffer.length) {
                System.out.println("==" + fileName);
                System.out.println("error: CRC mismatch in chunk " + chunkNum + " " + type);
                return;
            }

            int crc = ((buffer[offset] & 0xFF) << 24) |
                     ((buffer[offset + 1] & 0xFF) << 16) |
                     ((buffer[offset + 2] & 0xFF) << 8) |
                     (buffer[offset + 3] & 0xFF);
            offset += 4;

            int computedCrc = computeCRC(buffer, offset - 8, type.length() + chunkLen);
            computedCrc ^= 0xFFFFFFFF;

            if (crc != computedCrc) {
                System.out.println("==" + fileName);
                System.out.println("error: CRC mismatch in chunk " + chunkNum + " " + type);
                return;
            }

            if (chunkNum == 1) {
                allChunks.add(type);
            } else if (chunkNum == 2) {
                allChunks.add(type);
            } else {
                allChunks.add(type);
            }

            chunkNum++;
        }

        // Collect IDAT chunks
        byte[] idatData = new byte[0];
        while (true) {
            int chunkLen = (buffer[offset] & 0xFF) | 
                          ((buffer[offset + 1] & 0xFF) << 8) |
                          ((buffer[offset + 2] & 0xFF) << 16) |
                          ((buffer[offset + 3] & 0xFF) << 24);
            offset += 4;

            String type = new String(buffer, offset, 4, "ASCII");
            offset += 4;

            if (type.equals("IEND")) {
                break;
            } else if (type.equals("IDAT")) {
                int idatLen = 0;
                for (int i = 0; i < chunkLen; i++) {
                    idatLen |= (buffer[offset + i] & 0xFF) << (8 * i);
                }
                offset += chunkLen + 8;

                byte[] idatChunk = new byte[idatLen];
                System.arraycopy(buffer, offset, idatChunk, 0, idatLen);
                offset += idatLen;

                byte[] combined = Arrays.copyOf(idatData, idatData.length + idatLen);
                System.arraycopy(idatChunk, 0, combined, idatData.length, idatLen);
                idatData = combined;
            } else {
                offset += chunkLen + 8;
            }
        }

        // Decompress zlib
        byte[] zlibData = new byte[0];
        int zlibOffset = 0;
        int zlibLen = 0;

        if (idatData.length > 0) {
            int[] zlibBlocks = parseZlib(idatData);
            zlibData = zlibBlocks[0];
            zlibLen = zlibBlocks[1];
        }

        // Verify zlib checksum
        if (zlibLen > 0) {
            int adler = adler32(zlibData, zlibLen);
            int expectedAdler = adler32(idatData, idatData.length);
            if (adler != expectedAdler) {
                System.out.println("==" + fileName);
                System.out.println("error: Adler-32 mismatch");
                return;
            }
        }

        // Decode pixel data
        int[] pixels = new int[width * height];
        int[] filterTypes = new int[height];
        int[] filterCounts = new int[5];
        int[] blockTypes = new int[3];
        int blockCount = 0;

        int pixelIndex = 0;
        int row = 0;

        while (zlibOffset < zlibLen) {
            int blockType = zlibBlocks[2][blockCount];
            blockTypes[blockCount] = blockType;
            blockCount++;

            zlibOffset += zlibBlocks[3][blockCount];

            int rowPixels = width * ((bitDepth + 7) / 8);
            if (rowPixels == 0) continue;

            int rowStart = row * rowPixels;
            int rowEnd = rowStart + rowPixels;

            for (int col = 0; col < rowPixels; col++) {
                if (row >= height) break;

                int filterType = zlibData[zlibOffset] & 0xFF;
                zlibOffset++;
                filterTypes[row] = filterType;
                filterCounts[filterType]++;

                int pixelVal;
                int bitsPerSample = (bitDepth + 7) / 8;
                int sampleVal = 0;

                for (int b = 0; b < bitsPerSample; b++) {
                    sampleVal = (sampleVal << 1) | ((zlibData[zlibOffset] & 0x80) >> 7);
                    zlibOffset--;
                    sampleVal >>= 1;
                }

                int sample = sampleVal;

                if (colorType == COLOR_GRAYSCALE || colorType == COLOR_GRAY_ALPHA) {
                    pixels[pixelIndex] = sample;
                } else if (colorType == COLOR_RGB) {
                    pixels[pixelIndex] = sample;
                } else if (colorType == COLOR_PALETTE) {
                    // Need to read palette data
                    pixels[pixelIndex] = sample;
                } else if (colorType == COLOR_RGBA) {
                    pixels[pixelIndex] = sample;
                }

                pixelIndex++;
            }
        }

        // Convert to RGBA
        byte[] rgba = new byte[width * height * 4];
        int rgbaIndex = 0;
        int rSum = 0, gSum = 0, bSum = 0, aSum = 0;

        for (int row = 0; row < height; row++) {
            int rowPixels = width * ((bitDepth + 7) / 8);
            for (int col = 0; col < rowPixels; col++) {
                int pixel = pixels[col];
                int r, g, b, a;

                if (colorType == COLOR_GRAYSCALE || colorType == COLOR_GRAY_ALPHA) {
                    r = g = b = pixel;
                    a = 255;
                } else if (colorType == COLOR_RGB) {
                    r = g = b = pixel;
                    a = 255;
                } else if (colorType == COLOR_PALETTE) {
                    r = g = b = pixel;
                    a = 255;
                } else if (colorType == COLOR_RGBA) {
                    r = g = b = pixel;
                    a = pixel;
                }

                if (r >= 256) r = 255;
                if (g >= 256) g = 255;
                if (b >= 256) b = 255;
                if (a >= 256) a = 255;

                if (a < 255) {
                    a = a * 255 / 256;
                }

                r = r * 255 / 256;
                g = g * 255 / 256;
                b = b * 255 / 256;

                rgba[rgbaIndex] = (byte) r;
                rgba[rgbaIndex + 1] = (byte) g;
                rgba[rgbaIndex + 2] = (byte) b;
                rgba[rgbaIndex + 3] = (byte) a;

                rSum += r;
                gSum += g;
                bSum += b;
                aSum += a;

                rgbaIndex += 4;
            }
        }

        // Format chunk list
        StringBuilder chunkList = new StringBuilder();
        for (String type : allChunks) {
            if (chunkList.length() > 0) chunkList.append(" ");
            chunkList.append(type);
        }

        // Format deflate blocks
        StringBuilder deflateList = new StringBuilder();
        for (int i = 0; i < blockCount; i++) {
            if (deflateList.length() > 0) deflateList.append(" ");
            deflateList.append(blockTypes[i]);
        }

        // Format filters
        StringBuilder filterList = new StringBuilder();
        for (int i = 0; i < 5; i++) {
            if (filterList.length() > 0) filterList.append(" ");
            filterList.append(filterCounts[i]);
        }

        // Compute CRC of RGBA
        int rgbaCrc = computeCRC(rgba, rgba.length);

        System.out.println("==" + fileName);
        System.out.println("IHDR " + width + "x" + height + " depth=" + bitDepth + " color=" + colorType);
        System.out.println("chunks " + chunkList.toString());
        System.out.println("deflate " + deflateList.toString());
        System.out.println("filters " + filterList.toString());
        System.out.println("rgba sum=" + rSum + "," + gSum + "," + bSum + "," + aSum + " crc32=" + String.format("%08x", rgbaCrc));
    }

    private static int computeCRC(byte[] data, int len) {
        int crc = CRC_INIT;
        for (int i = 0; i < len; i++) {
            crc ^= (data[i] & 0xFF) << 24;
            for (int j = 0; j < 8; j++) {
                if ((crc & 0x80000000) != 0) {
                    crc = (crc << 1) ^ CRC_POLY;
                } else {
                    crc <<= 1;
                }
            }
        }
        return crc ^ 0xFFFFFFFF;
    }

    private static int[] parseZlib(byte[] data) {
        int[] blocks = new int[4];
        blocks[0] = data.length;
        blocks[1] = data.length;
        blocks[2] = new int[0];
        blocks[3] = new int[0];
        return blocks;
    }

    private static int adler32(byte[] data, int len) {
        int a = 1, b = 0;
        for (int i = 0; i < len; i++) {
            a = (int)((a + data[i]) & 0xFFFF);
            b = (int)((b + a) & 0xFFFF);
        }
        return (a << 16) + b;
    }
}

use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
use std::path::Path;

const CRC32_POLY: u32 = 0xEDB88320;

fn crc32_table() -> [u8; 256] {
    let mut table = [0u8; 256];
    for i in 0..256 {
        let mut crc = i as u32;
        for _ in 0..8 {
            if crc & 1 {
                crc = (crc >> 1) ^ CRC32_POLY;
            } else {
                crc >>= 1;
            }
        }
        table[i as usize] = (crc & 0xFF) as u8;
    }
    table
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFFFFFF;
    for &byte in data {
        crc = ((crc >> 8) ^ crc32_table[(crc ^ byte) as usize]) & 0xFFFFFFFF;
    }
    crc ^ 0xFFFFFFFF
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DiffKind {
    Create,
    Delete,
    Modify,
}

#[derive(Debug)]
struct Hunk {
    old_lines: Vec<String>,
    new_lines: Vec<String>,
}

#[derive(Debug)]
struct Section {
    kind: DiffKind,
    path: String,
    hunks: Vec<Hunk>,
}

struct DiffResult {
    files: BTreeMap<String, SectionResult>,
}

struct SectionResult {
    kind: DiffKind,
    hunks: Vec<HunkResult>,
    result: Option<String>,
}

#[derive(Debug)]
enum HunkResult {
    Applied { p: usize, offset: isize },
    Rejected,
    Malformed,
}

fn parse_lines(content: &[u8]) -> Vec<String> {
    let mut lines = Vec::new();
    let mut current = String::new();
    for &byte in content {
        if byte == b'\n' {
            lines.push(current.clone());
            current.clear();
        } else {
            current.push(byte as char);
        }
    }
    if !current.is_empty() {
        lines.push(current);
    }
    lines
}

fn parse_diff(content: &[u8]) -> Vec<Section> {
    let mut sections = Vec::new();
    let mut buf = String::new();
    let mut current_section: Option<Section> = None;
    let mut pos = 0;
    let len = content.len();

    while pos < len {
        let start = pos;
        let mut line_start = pos;
        while pos < len && content[pos] != b'\n' {
            pos += 1;
        }
        if pos >= len {
            break;
        }
        let line_end = pos;
        let line = &content[line_start..line_end];
        buf.push_str(std::str::from_utf8(line).unwrap_or(""));
        buf.push('\n');
        pos += 1;

        if buf.starts_with("diff --git") {
            if let Some(mut section) = current_section.take() {
                sections.push(section);
            }
            if buf.starts_with("--- a/") || buf.starts_with("--- /dev/null") {
                continue;
            }
            let mut path = String::new();
            if let Some(rest) = buf.strip_prefix("diff --git a/") {
                if let Some(rest2) = rest.strip_prefix(" b/") {
                    path = rest2.to_string();
                } else {
                    path = rest.to_string();
                }
            } else if buf.starts_with("diff --git") {
                let rest = &buf[buf.len() - 5..];
                let rest = rest.strip_prefix(" b/").unwrap_or(rest);
                path = rest.to_string();
            }

            let mut kind = DiffKind::Modify;
            if buf.starts_with("new file mode") {
                kind = DiffKind::Create;
            } else if buf.starts_with("deleted file mode") {
                kind = DiffKind::Delete;
            }

            let mut section = Section {
                kind,
                path,
                hunks: Vec::new(),
            };
            current_section = Some(section);
            continue;
        }

        if let Some(section) = &mut current_section {
            if buf.starts_with("--- a/") || buf.starts_with("--- /dev/null") {
                if let Some(rest) = buf.strip_prefix("--- ") {
                    let rest2 = rest.strip_prefix("b/").unwrap_or(rest);
                    let mut path = rest2.to_string();
                    if path == "/dev/null" && section.kind == DiffKind::Delete {
                        path = String::new();
                    }
                    section.path = path;
                }
            }
            if buf.starts_with("+++ b/") {
                if let Some(rest) = buf.strip_prefix("+++ ") {
                    let rest2 = rest.strip_prefix("b/").unwrap_or(rest);
                    section.path = rest2.to_string();
                }
            }
            if buf.starts_with("@@ -") {
                let mut old_lines = Vec::new();
                let mut new_lines = Vec::new();
                let mut old_count = 0;
                let mut new_count = 0;
                let mut pos = 0;
                let len = buf.len();
                while pos < len {
                    if buf[pos..].starts_with("@@") {
                        break;
                    }
                    pos += 1;
                }
                let hunk_body = &buf[pos..];
                for line in hunk_body.lines() {
                    let line = line.trim();
                    if line.starts_with('-') {
                        old_lines.push(line[1..].to_string());
                    } else if line.starts_with('+') {
                        new_lines.push(line[1..].to_string());
                    } else if line.starts_with('\\') {
                        let line = line.trim();
                        if line.starts_with("\\ No newline") {
                            old_lines.push(String::new());
                            new_lines.push(String::new());
                        }
                    } else if line.starts_with(' ') {
                        old_lines.push(line[1..].to_string());
                        new_lines.push(line[1..].to_string());
                    }
                }
                if !old_lines.is_empty() && !new_lines.is_empty() {
                    section.hunks.push(Hunk {
                        old_lines,
                        new_lines,
                    });
                }
            }
        }
        buf.clear();
    }
    if let Some(section) = current_section {
        sections.push(section);
    }
    sections
}

fn apply_hunk(content: &mut Vec<String>, hunk: &Hunk, expected_pos: usize) -> Option<(usize, isize)> {
    let old_len = hunk.old_lines.len();
    let new_len = hunk.new_lines.len();
    if old_len == 0 {
        if expected_pos > content.len() {
            return None;
        }
        let start = expected_pos;
        if start > content.len() {
            return None;
        }
        return Some((start, 0));
    }
    let mut delta = 0;
    for i in 0..old_len {
        if hunk.old_lines[i] != content[expected_pos + i] {
            break;
        }
        delta += 1;
    }
    if delta == old_len {
        return Some((expected_pos, delta));
    }
    for i in 0..old_len {
        if i + delta < content.len() {
            if hunk.old_lines[i] != content[expected_pos + delta + i] {
                break;
            }
        }
    }
    if delta == old_len {
        return Some((expected_pos + delta, delta));
    }
    None
}

fn apply_section(content: &mut Vec<String>, section: &Section) -> Result<(), String> {
    let mut delta = 0;
    for (idx, hunk) in section.hunks.iter().enumerate() {
        let expected_pos = hunk.old_lines.len() + delta;
        let result = apply_hunk(content, hunk, expected_pos);
        if let Some((p, k)) = result {
            section.hunks[idx] = HunkResult::Applied { p, offset: k };
            delta += hunk.new_lines.len() as isize - hunk.old_lines.len() as isize;
        } else {
            section.hunks[idx] = HunkResult::Rejected;
        }
    }
    Ok(())
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: program <diff_dir> <tree_dir>");
        std::process::exit(1);
    }
    let diff_dir = &args[1];
    let tree_dir = &args[2];
    let diff_path = Path::new(diff_dir).join("changes.diff");
    let tree_path = Path::new(tree_dir);

    let mut diff_bytes = Vec::new();
    fs::File::open(&diff_path).expect("Cannot open diff file").read_to_end(&mut diff_bytes).expect("Cannot read diff file");

    let sections = parse_diff(&diff_bytes);
    let mut results = BTreeMap::new();

    for section in sections {
        let path = &section.path;
        let file_path = tree_path.join(path);
        let file_exists = file_path.exists();

        let mut result = SectionResult {
            kind: section.kind,
            hunks: Vec::new(),
            result: None,
        };
        result.hunks = section.hunks.clone();
        let mut content = Vec::new();

        if section.kind == DiffKind::Create {
            if file_exists {
                result.result = Some("already exists".to_string());
                results.insert(path.clone(), result);
                continue;
            }
            content = Vec::new();
        } else {
            if !file_exists {
                result.result = Some("not found".to_string());
                results.insert(path.clone(), result);
                continue;
            }
            let file = fs::File::open(&file_path).expect("Cannot open file");
            let mut bytes = Vec::new();
            file.read_to_end(&mut bytes).expect("Cannot read file");
            content = parse_lines(&bytes);
        }

        apply_section(&mut content, &section).expect("Apply error");

        if section.kind == DiffKind::Delete {
            let is_empty = content.is_empty();
            if is_empty {
                result.result = Some("deleted".to_string());
            }
        } else {
            result.result = Some(format!("{} lines, crc32 {}", content.len(), crc32(&content.to_vec())));
        }

        results.insert(path.clone(), result);
    }

    for (path, result) in results {
        println!("{}: {}", path, result.kind);
        for hunk in &result.hunks {
            match hunk {
                HunkResult::Applied { p, offset } => {
                    println!("  hunk {}: applied at {} (offset {})", hunk_idx, p, offset);
                }
                HunkResult::Rejected => {
                    println!("  hunk {}: rejected", hunk_idx);
                }
                HunkResult::Malformed => {
                    println!("  hunk {}: malformed", hunk_idx);
                }
            }
        }
        match &result.result {
            Some(s) => println!("  result: {}", s),
            None => {
                if let Some(err) = &result.result {
                    println!("  error: {}", err);
                }
            }
        }
    }
}

fn hunk_idx(hunks: &[HunkResult], idx: usize) -> usize {
    idx + 1
}

use std::collections::BTreeMap;
