fn parse_lines(content: &[u8]) -> Vec<Line> {
    let mut lines = Vec::new();
    let mut current = Vec::new();
    let mut ends_newline = false; // This tracks if the current line ends with \n in the file

    for &byte in content {
        if byte == b'\n' {
            if !current.is_empty() {
                let mut l = Line {
                    bytes: current.clone(),
                    ends_newline: true,
                };
                lines.push(l);
                current.clear();
            }
            if byte == b'\n' {
                ends_newline = true;
            } else {
                ends_newline = false;
            }
        } else {
            current.push(byte);
        }
    }
    if !current.is_empty() {
        let mut l = Line {
            bytes: current,
            ends_newline: ends_newline,
        };
        lines.push(l);
    }
    lines
}

fn parse_diff(content: &[u8]) -> Vec<Section> {
    let mut sections = Vec::new();
    let mut sections_buffer = Vec::new();
    let mut current_section: Option<Section> = None;
    let mut current_buf = Vec::new();
    let mut pos = 0;
    let len = content.len();

    while pos < len {
        // Read line
        let mut line_start = pos;
        while pos < len && content[pos] != b'\n' {
            pos += 1;
        }
        let line_end = pos;
        let line_bytes = &content[line_start..line_end];
        let line_str = std::str::from_utf8(line_bytes).unwrap_or("");
        current_buf.push(line_str);
        pos += 1;

        if current_buf.len() > 1 {
            // Check if we finished a section
            if current_buf.last().unwrap().starts_with("diff --git") {
                if let Some(section) = current_section.take() {
                    sections.push(section);
                }
                current_section = None;
                current_buf.clear();
                continue;
            }
        }

        if let Some(mut section) = current_section {
            if current_buf.first().unwrap().starts_with("--- a/") || current_buf.first().unwrap().starts_with("--- /dev/null") {
                if let Some(rest) = current_buf.first().unwrap().strip_prefix("--- ") {
                    let rest2 = rest.strip_prefix("b/").unwrap_or(rest);
                    section.path = rest2.to_string();
                }
            }
            if current_buf.first().unwrap().starts_with("+++ b/") {
                if let Some(rest) = current_buf.first().unwrap().strip_prefix("+++ ") {
                    let rest2 = rest.strip_prefix("b/").unwrap_or(rest);
                    section.path = rest2.to_string();
                }
            }
            if current_buf.first().unwrap().starts_with("@@ -") {
                let header = current_buf.first().unwrap();
                let mut old_count = 0;
                let mut new_count = 0;
                let mut old_pos = 0;
                let mut new_pos = 0;

                // Parse @@ -a,b +c,d @@
                for ch in header.chars() {
                    if ch == '@' {
                        if ch == ':' {
                            break;
                        }
                    }
                }
                // Actually parse manually
                let mut old_a = 0;
                let mut old_b = 1;
                let mut new_c = 0;
                let mut new_d = 1;

                let mut i = 0;
                while i < header.len() {
                    if header[i..].starts_with("@@") {
                        break;
                    }
                    i += 1;
                }
                let hunk_header = &header[i..];

                // Parse @@ -a,b +c,d @@
                let mut parts = Vec::new();
                let mut current = String::new();
                for ch in hunk_header.chars() {
                    if ch == ' ' {
                        if !current.is_empty() {
                            parts.push(current.clone());
                            current.clear();
                        }
                    } else {
                        current.push(ch);
                    }
                }
                if !current.is_empty() {
                    parts.push(current);
                }

                for part in parts {
                    if part.starts_with("-") {
                        if let Some(rest) = part.strip_prefix("-") {
                            if let Some(rest2) = rest.rsplit_once(',') {
                                old_a = rest2.0.parse::<usize>().unwrap_or(0);
                                old_b = rest2.1.parse::<usize>().unwrap_or(1);
                            } else {
                                old_b = 1;
                            }
                        }
                    } else if part.starts_with("+") {
                        if let Some(rest) = part.strip_prefix("+") {
                            if let Some(rest2) = rest.rsplit_once(',') {
                                new_c = rest2.0.parse::<usize>().unwrap_or(0);
                                new_d = rest2.1.parse::<usize>().unwrap_or(1);
                            } else {
                                new_d = 1;
                            }
                        }
                    }
                }

                section.hunks.push(Hunk {
                    old_lines: Vec::new(),
                    new_lines: Vec::new(),
                    old_count: old_b,
                    new_count: new_d,
                });

                current_section = Some(section);
                continue;
            }
        }
        current_buf.clear();
    }
    if let Some(section) = current_section {
        sections.push(section);
    }
    sections
}

fn parse_hunk_body(body_bytes: &[u8]) -> Vec<Line> {
    let mut lines = Vec::new();
    let mut content_line = Vec::new();
    let mut ends_newline = false;

    for &byte in body_bytes {
        if byte == b'\n' {
            if !content_line.is_empty() {
                lines.push(Line {
                    bytes: content_line.clone(),
                    ends_newline: ends_newline,
                });
                content_line.clear();
            }
            ends_newline = true;
            content_line.clear();
        } else {
            content_line.push(byte);
        }
    }
    if !content_line.is_empty() {
        lines.push(Line {
            bytes: content_line,
            ends_newline: ends_newline,
        });
    }
    lines
}

fn parse_diff_lines(content: &[u8]) -> Vec<Line> {
    parse_lines(content)
}

