    char *func_scope;
} Value;

typedef struct Statement {
    struct Statement *next;
    struct Statement *prev;
    TokenType type;
    int line;
    int col;
    char *ident_val;
    Value *expr_val;
    Scope *scope;
    int param_count;
    char *param_names[MAX_VARS];
    char *param_values[MAX_VARS];
    char *body;
    struct Statement *if_body;
    struct Statement *else_body;
    struct Statement *for_body;
    struct Statement *while_body;
} Statement;

typedef struct AST {
    struct AST *next;
    TokenType type;
    int line;
    int col;
    long long int_val;
    char *str_val;
    char *ident_val;
    struct AST *left;
    struct AST *right;
    struct AST *index;
    struct AST *func_args;
    struct AST *for_expr;
    struct AST *while_expr;
    struct AST *if_expr;
    struct AST *else_expr;
    struct AST *return_expr;
    struct AST *break_expr;
    struct AST *continue_expr;
    struct AST *postfix;
    struct AST *expr;
    Type type;
} AST;

typedef struct ASTNode {
    struct ASTNode *next;
    TokenType type;
    int line;
    int col;
    long long int_val;
    char *str_val;
    char *ident_val;
    struct ASTNode *left;
    struct ASTNode *right;
    struct ASTNode *index;
    struct ASTNode *func_args;
    struct ASTNode *for_expr;
    struct ASTNode *while_expr;
    struct ASTNode *if_expr;
    struct ASTNode *else_expr;
    struct ASTNode *return_expr;
    struct ASTNode *break_expr;
    struct ASTNode *continue_expr;
    struct ASTNode *postfix;
    struct ASTNode *expr;
