} ASTNode;

typedef struct LexerState {
    char *source;
    int pos;
    int line;
    int col;
    Token *tokens;
    int token_count;
    int token_capacity;
} LexerState;

typedef struct ParserState {
    LexerState *lexer;
    Scope *scope;
    Scope *current_scope;
    ASTNode *root;
    int param_count;
    char *param_names[MAX_VARS];
    char *param_values[MAX_VARS];
    int param_index;
} ParserState;

typedef struct InterpreterState {
    Scope *scope;
    Value *builtins;
    Value *stack[MAX_STACK];
    int stack_top;
    int recursion_depth;
} InterpreterState;

Value *create_value(Type type, long long int_val, char *str_val, struct Value **list_val, Function *func_val, char *func_name, char *func_scope) {
    Value *v = (Value *)malloc(sizeof(Value));
    v->type = type;
    v->int_val = int_val;
    v->str_val = str_val;
    v->list_val = list_val;
    v->func_val = func_val;
    v->nil_val = NULL;
    v->func_name = func_name;
    v->func_scope = func_scope;
    return v;
}

Value *create_nil() {
    return create_value(TYPE_NIL, 0, NULL, NULL, NULL, NULL, NULL);
}

Value *create_int(long long int_val) {
    return create_value(TYPE_INT, int_val, NULL, NULL, NULL, NULL, NULL);
}

Value *create_string(char *str_val) {
    return create_value(TYPE_STRING, 0, str_val, NULL, NULL, NULL, NULL);
}

Value *create_list(struct Value **list_val) {
    return create_value(TYPE_LIST, 0, NULL, list_val, NULL, NULL, NULL);
}

Value *create_function(Function *func) {
    return create_value(TYPE_FUNCTION, 0, NULL, NULL, func, func->name, func->scope);
}

Value *create_bool(bool val) {
    return create_value(TYPE_BOOL, 0, NULL, NULL, NULL, NULL, NULL);
}

int type_is_int(Value *v) {
    return v->type == TYPE_INT;
}

int type_is_bool(Value *v) {
    return v->type == TYPE_BOOL;
}

int type_is_string(Value *v) {
    return v->type == TYPE_STRING;
}

int type_is_list(Value *v) {
    return v->type == TYPE_LIST;
}

int type_is_function(Value *v) {
    return v->type == TYPE_FUNCTION;
}

int type_is_nil(Value *v) {
    return v->type == TYPE_NIL;
}

int type_is_truthy(Value *v) {
    if (v->type == TYPE_NIL) return 0;
    if (v->type == TYPE_BOOL) return v->int_val != 0;
    if (v->type == TYPE_INT) return v->int_val != 0;
    if (v->type == TYPE_STRING) return v->str_val && v->str_val[0] != '\0';
    if (v->type == TYPE_LIST) {
        if (v->list_val && v->list_val[0]) {
            for (int i = 0; v->list_val[i]; i++) {
                if (type_is_truthy(v->list_val[i])) return 1;
            }
            return 0;
        }
        return 0;
    }
    return 1;
}

int type_equals(Value *v1, Value *v2) {
    if (v1->type != v2->type) return 0;
    if (v1->type == TYPE_NIL) return 1;
    if (v1->type == TYPE_INT) return v1->int_val == v2->int_val;
    if (v1->type == TYPE_BOOL) return v1->int_val == v2->int_val;
    if (v1->type == TYPE_STRING) {
        if (!v1->str_val || !v2->str_val) return 0;
        return strcmp(v1->str_val, v2->str_val) == 0;
    }
    if (v1->type == TYPE_FUNCTION) return v1->func_val == v2->func_val;
    if (v1->type == TYPE_LIST) {
        if (!v1->list_val || !v2->list_val) return 0;
        int len1 = 0;
        for (; v1->list_val[len1]; len1++);
        int len2 = 0;
        for (; v2->list_val[len2]; len2++);
        if (len1 != len2) return 0;
        for (int i = 0; i < len1; i++) {
            if (!type_equals(v1->list_val[i], v2->list_val[i])) return 0;
        }
        return 1;
    }
    return 0;
}

int type_less_than(Value *v1, Value *v2) {
    if (v1->type != v2->type) return 0;
    if (v1->type == TYPE_INT) return v1->int_val < v2->int_val;
    if (v1->type == TYPE_STRING) {
        if (!v1->str_val || !v2->str_val) return 0;
        return strcmp(v1->str_val, v2->str_val) < 0;
    }
    return 0;
}

int type_less_equal_than(Value *v1, Value *v2) {
    if (v1->type != v2->type) return 0;
    if (v1->type == TYPE_INT) return v1->int_val <= v2->int_val;
    if (v1->type == TYPE_STRING) {
        if (!v1->str_val || !v2->str_val) return 0;
        return strcmp(v1->str_val, v2->str_val) <= 0;
    }
    return 0;
}

int type_greater_than(Value *v1, Value *v2) {
    if (v1->type != v2->type) return 0;
    if (v1->type == TYPE_INT) return v1->int_val > v2->int_val;
    if (v1->type == TYPE_STRING) {
        if (!v1->str_val || !v2->str_val) return 0;
        return strcmp(v1->str_val, v2->str_val) > 0;
    }
    return 0;
}

int type_greater_equal_than(Value *v1, Value *v2) {
    if (v1->type != v2->type) return 0;
    if (v1->type == TYPE_INT) return v1->int_val >= v2->int_val;
    if (v1->type == TYPE_STRING) {
        if (!v1->str_val || !v2->str_val) return 0;
        return strcmp(v1->str_val, v2->str_val) >= 0;
    }
    return 0;
}

int type_not_equal(Value *v1, Value *v2) {
    return !type_equals(v1, v2);
}

int type_equal(Value *v1, Value *v2) {
    return type_equals(v1, v2);
}

Value *type_int_add(Value *v1, Value *v2) {
    if (!type_is_int(v1) || !type_is_int(v2)) return NULL;
    long long a = v1->int_val;
    long long b = v2->int_val;
    if (a > LLONG_MAX - b) return NULL;
    if (a < LLONG_MIN - b) return NULL;
    long long result = a + b;
    if (result < LLONG_MIN || result > LLONG_MAX) return NULL;
    return create_int(result);
}

Value *type_int_sub(Value *v1, Value *v2) {
    if (!type_is_int(v1) || !type_is_int(v2)) return NULL;
    long long a = v1->int_val;
    long long b = v2->int_val;
    if (a > LLONG_MAX - b) return NULL;
    if (a < LLONG_MIN - b) return NULL;
    long long result = a - b;
    if (result < LLONG_MIN || result > LLONG_MAX) return NULL;
    return create_int(result);
}

Value *type_int_mul(Value *v1, Value *v2) {
    if (!type_is_int(v1) || !type_is_int(v2)) return NULL;
    long long a = v1->int_val;
    long long b = v2->int_val;
    if (a != 0 && b != 0) {
        if (a > LLONG_MAX / b) return NULL;
        if (a < LLONG_MIN / b) return NULL;
    }
    long long result = a * b;
    if (result < LLONG_MIN || result > LLONG_MAX) return NULL;
    return create_int(result);
}

Value *type_int_div(Value *v1, Value *v2) {
    if (!type_is_int(v1) || !type_is_int(v2)) return NULL;
    if (v2->int_val == 0) return NULL;
    long long a = v1->int_val;
    long long b = v2->int_val;
    if (b < 0) {
        if (a > LLONG_MAX / b) return NULL;
        if (a < LLONG_MIN / b) return NULL;
    }
    long long result = a / b;
    if (result < LLONG_MIN || result > LLONG_MAX) return NULL;
    return create_int(result);
}

Value *type_int_mod(Value *v1, Value *v2) {
    if (!type_is_int(v1) || !type_is_int(v2)) return NULL;
    if (v2->int_val == 0) return NULL;
    long long a = v1->int_val;
    long long b = v2->int_val;
    long long result = a - (a / b) * b;
    if (result < LLONG_MIN || result > LLONG_MAX) return NULL;
    return create_int(result);
}

Value *type_string_concat(Value *v1, Value *v2) {
    if (!type_is_string(v1) || !type_is_string(v2)) return NULL;
    size_t len1 = strlen(v1->str_val);
    size_t len2 = strlen(v2->str_val);
    char *result = (char *)malloc(len1 + len2 + 1);
    strcpy(result, v1->str_val);
    strcat(result, v2->str_val);
    return create_string(result);
}

Value *type_list_concat(Value *v1, Value *v2) {
    if (!type_is_list(v1) || !type_is_list(v2)) return NULL;
    int len1 = 0;
    for (; v1->list_val[len1]; len1++);
    int len2 = 0;
    for (; v2->list_val[len2]; len2++);
    struct Value **result = (struct Value **)malloc((len1 + len2 + 1) * sizeof(struct Value *));
    for (int i = 0; i < len1; i++) result[i] = v1->list_val[i];
    for (int i = 0; i < len2; i++) result[len1 + i] = v2->list_val[i];
    result[len1 + len2] = NULL;
    return create_list(result);
}

Value *type_list_slice(Value *v, int a, int b) {
    if (!type_is_list(v)) return NULL;
    if (a < 0 || b < 0) return NULL;
    if (a > b) return NULL;
    struct Value **result = (struct Value **)malloc((b - a + 1) * sizeof(struct Value *));
    int len = 0;
    for (; v->list_val[len]; len++);
    for (int i = a; i < b && i < len; i++) result[i - a] = v->list_val[i];
    result[b - a] = NULL;
    return create_list(result);
}

Value *type_list_index(Value *v, int i) {
    if (!type_is_list(v)) return NULL;
    int len = 0;
    for (; v->list_val[len]; len++);
    if (i < 0 || i >= len) return NULL;
    return v->list_val[i];
}

Value *type_list_get(Value *v, int i) {
    if (!type_is_list(v)) return NULL;
    int len = 0;
    for (; v->list_val[len]; len++);
    if (i < 0 || i >= len) return NULL;
    return v->list_val[i];
}

Value *type_list_set(Value *v, int i, Value *val) {
    if (!type_is_list(v)) return NULL;
    int len = 0;
    for (; v->list_val[len]; len++);
    if (i < 0 || i >= len) return NULL;
    v->list_val[i] = val;
    return val;
}

Value *type_list_push(Value *v, Value *val) {
    if (!type_is_list(v)) return NULL;
    struct Value **new_list = (struct Value **)malloc((v->list_val ? v->list_val[0] ? v->list_val[0]->list_val : 0 : 0) + 1 * sizeof(struct Value *));
    int len = 0;
    for (; v->list_val[len]; len++);
    for (int i = 0; i < len; i++) new_list[i] = v->list_val[i];
    new_list[len] = val;
    new_list[len + 1] = NULL;
    return create_list(new_list);
}

Value *type_list_pop(Value *v) {
    if (!type_is_list(v)) return NULL;
    struct Value **new_list = (struct Value **)malloc((v->list_val ? v->list_val[0] ? v->list_val[0]->list_val : 0 : 0) * sizeof(struct Value *));
    int len = 0;
    for (; v->list_val[len]; len++);
    if (len == 0) return NULL;
    for (int i = 0; i < len - 1; i++) new_list[i] = v->list_val[i + 1];
    new_list[len - 1] = NULL;
    return create_list(new_list);
}

Value *type_int_range(int a, int b) {
    if (a > b) return NULL;
    struct Value **result = (struct Value **)malloc((b - a + 1) * sizeof(struct Value *));
    for (int i = a; i < b; i++) result[i - a] = create_int(i);
    result[b - a] = NULL;
    return create_list(result);
}

Value *type_int_str(Value *v) {
    if (!type_is_int(v)) return NULL;
    char *result = (char *)malloc(20);
    snprintf(result, 20, "%lld", v->int_val);
    return create_string(result);
}

Value *type_int_type(Value *v) {
    if (!type_is_int(v)) return NULL;
    char *result = (char *)malloc(16);
    snprintf(result, 16, "int");
    return create_string(result);
}

void print_value(Value *v) {
    if (v->type == TYPE_INT) printf("%lld", v->int_val);
    else if (v->type == TYPE_BOOL) printf("%s", v->int_val ? "true" : "false");
    else if (v->type == TYPE_STRING) printf("%s", v->str_val);
    else if (v->type == TYPE_LIST) {
        printf("[");
        int len = 0;
        for (; v->list_val[len]; len++);
        for (int i = 0; i < len; i++) {
            if (i > 0) printf(", ");
            print_value(v->list_val[i]);
        }
        printf("]");
    }
    else if (v->type == TYPE_FUNCTION) {
        printf("<fn>");
    }
    else if (v->type == TYPE_NIL) {
        printf("nil");
    }
}

