void run_program(char *source) {
    LexerState lexer;
    lexer.source = source;
    lexer.pos = 0;
    lexer.line = 1;
    lexer.col = 0;
    lexer.tokens = NULL;
    lexer.token_count = 0;
    lexer.token_capacity = 100;

    ParserState parser;
    parser.lexer = &lexer;
    parser.scope = NULL;
    parser.current_scope = NULL;
    parser.root = NULL;
    parser.param_count = 0;
    parser.param_index = 0;

    InterpreterState interpreter;
    interpreter.scope = NULL;
    interpreter.stack_top = 0;
    interpreter.recursion_depth = 0;

    while (1) {
        Token token;
        token.type = TOK_EOF;
        token.line = 0;
        token.col = 0;
        token.int_val = 0;
        token.str_val = NULL;
        token.ident_val = NULL;

        char *p = lexer.source + lexer.pos;
        while (*p && isspace(*p)) p++;
        if (*p == '\0') {
            token.type = TOK_EOF;
            break;
        }

        int start_line = lexer.line;
        int start_col = lexer.col;

        if (*p == '#') {
            lexer.pos = p - lexer.source + 1;
            while (*p && *p != '\n') p++;
            lexer.pos = p - lexer.source + 1;
            lexer.line++;
            lexer.col = 0;
            continue;
        }

        if (*p == '\n') {
            lexer.pos = p - lexer.source + 1;
            lexer.line++;
            lexer.col = 0;
            continue;
        }

        if (isdigit(*p) || *p == '-') {
            char *end;
            long long val = strtol(p, &end, 10);
            if (end == p) {
                token.type = TOK_INT;
                token.line = start_line;
                token.col = start_col;
                token.int_val = val;
            }
            lexer.pos = end - lexer.source;
            lexer.line = start_line;
            lexer.col = lexer.col + (end - p);
        } else if (*p == '"') {
            p++;
            char *str = (char *)malloc(100);
            size_t len = 0;
            while (*p && *p != '"') {
                if (*p == '\\') {
                    p++;
                    if (*p == 'n') str[len++] = '\n';
                    else if (*p == 't') str[len++] = '\t';
                    else if (*p == '\\') str[len++] = '\\';
                    else if (*p == '"') str[len++] = '"';
                    else str[len++] = *p;
                } else {
                    str[len++] = *p;
                }
                p++;
            }
            str[len] = '\0';
            token.type = TOK_STRING;
            token.line = start_line;
            token.col = start_col;
            token.str_val = str;
            lexer.pos = p - lexer.source;
            lexer.line = start_line;
            lexer.col = lexer.col + (p - str);
        } else if (isalpha(*p) || *p == '_') {
            char *ident = (char *)malloc(100);
            p++;
            while (isalnum(*p) || *p == '_') {
                ident[p - lexer.source + 1 - lexer.col] = *p;
                p++;
            }
            ident[p - lexer.source + 1 - lexer.col] = '\0';
            token.type = TOK_IDENT;
            token.line = start_line;
            token.col = start_col;
            token.ident_val = ident;
            lexer.pos = p - lexer.source;
            lexer.line = start_line;
            lexer.col = lexer.col + (p - str);
        } else if (*p == '+') {
            token.type = TOK_PLUS;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == '-') {
            token.type = TOK_MINUS;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == '*') {
            token.type = TOK_STAR;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == '/') {
            token.type = TOK_SLASH;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == '%') {
            token.type = TOK_MOD;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == '=') {
            token.type = TOK_ASSIGN;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == '<') {
            if (*(p + 1) == '=') {
                token.type = TOK_LE;
                token.line = start_line;
                token.col = start_col;
                lexer.pos += 2;
            } else if (*(p + 1) == '>') {
                token.type = TOK_NE;
                token.line = start_line;
                token.col = start_col;
                lexer.pos += 2;
            } else {
                token.type = TOK_LT;
                token.line = start_line;
                token.col = start_col;
                lexer.pos++;
            }
        } else if (*p == '>') {
            if (*(p + 1) == '=') {
                token.type = TOK_GE;
                token.line = start_line;
                token.col = start_col;
                lexer.pos += 2;
            } else {
                token.type = TOK_GT;
                token.line = start_line;
                token.col = start_col;
                lexer.pos++;
            }
        } else if (*p == '!') {
            if (*(p + 1) == '=') {
                token.type = TOK_NEQ;
                token.line = start_line;
                token.col = start_col;
                lexer.pos += 2;
            } else {
                token.type = TOK_NOT;
                token.line = start_line;
                token.col = start_col;
                lexer.pos++;
            }
        } else if (*p == '(') {
            token.type = TOK_LPAREN;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == ')') {
            token.type = TOK_RPAREN;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == '[') {
            token.type = TOK_LBRACKET;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == ']') {
            token.type = TOK_RBRACKET;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == '{') {
            token.type = TOK_LBRACE;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == '}') {
            token.type = TOK_RBRACE;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == ',') {
            token.type = TOK_COMMA;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (*p == ';') {
            token.type = TOK_SEMI;
            token.line = start_line;
            token.col = start_col;
            lexer.pos++;
        } else if (strncmp(p, "let", 3) == 0) {
            token.type = TOK_LET;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 3;
        } else if (strncmp(p, "fn", 2) == 0) {
            token.type = TOK_FN;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 2;
        } else if (strncmp(p, "if", 2) == 0) {
            token.type = TOK_IF;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 2;
        } else if (strncmp(p, "else", 4) == 0) {
            token.type = TOK_ELSE;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 4;
        } else if (strncmp(p, "while", 5) == 0) {
            token.type = TOK_WHILE;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 5;
        } else if (strncmp(p, "for", 3) == 0) {
            token.type = TOK_FOR;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 3;
        } else if (strncmp(p, "in", 2) == 0) {
            token.type = TOK_IN;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 2;
        } else if (strncmp(p, "return", 6) == 0) {
            token.type = TOK_RETURN;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 6;
        } else if (strncmp(p, "break", 5) == 0) {
            token.type = TOK_BREAK;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 5;
        } else if (strncmp(p, "continue", 8) == 0) {
            token.type = TOK_CONTINUE;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 8;
        } else if (strncmp(p, "print", 5) == 0) {
            token.type = TOK_PRINT;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 5;
        } else if (strncmp(p, "str", 3) == 0) {
            token.type = TOK_STR;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 3;
        } else if (strncmp(p, "type", 4) == 0) {
            token.type = TOK_TYPE;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 4;
        } else if (strncmp(p, "len", 3) == 0) {
            token.type = TOK_LEN;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 3;
        } else if (strncmp(p, "push", 4) == 0) {
            token.type = TOK_PUSH;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 4;
        } else if (strncmp(p, "pop", 3) == 0) {
            token.type = TOK_POP;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 3;
        } else if (strncmp(p, "range", 5) == 0) {
            token.type = TOK_RANGE;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 5;
        } else if (strncmp(p, "slice", 5) == 0) {
            token.type = TOK_SLICE;
            token.line = start_line;
            token.col = start_col;
            lexer.pos += 5;
        } else {
            token.type = TOK_EOF;
            break;
        }

        lexer.tokens[lexer.token_count++] = token;
    }

    printf("%s", source);
}

