// CRC-32 lookup table
const CRC_TABLE = new Uint32Array(256 * 256);
function initCRCTable() {
    for (let i = 0; i < 256; i++) {
        let crc = i;
        for (let j = 0; j < 8; j++) {
            crc = ((crc << 1) ^ ((crc & 1) ? 0xEDB88320 : 0)) & 0xFFFFFFFF;
        }
        CRC_TABLE[i] = crc;
    }
    for (let i = 0; i < 256; i++) {
        for (let j = 0; j < 256; j++) {
            CRC_TABLE[i + 256 * j] = CRC_TABLE[i] ^ CRC_TABLE[j];
        }
    }
}
function crc32(data: Buffer): number {
    initCRCTable();
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc = CRC_TABLE[(crc ^ data[i]) & 0xFF] ^ (crc >> 8);
    }
    return (crc ^ 0xFFFFFFFF) & 0xFFFFFFFF;
}

