// Parse PNG chunks
function parseChunks(data: Buffer): {
    chunks: { type: string; length: number; data: Buffer; crc: number; valid: boolean }[];
    ihdr: { width: number; height: number; bitDepth: number; colorType: number; interlace: number };
    plte: Buffer;
    trns: Buffer;
    idat: Buffer;
    idatCount: number;
} {
    const chunks: { type: string; length: number; data: Buffer; crc: number; valid: boolean }[] = [];
    let ihdr: { width: number; height: number; bitDepth: number; colorType: number; interlace: number } | null = null;
    let plte: Buffer | null = null;
    let trns: Buffer | null = null;
    let idat: Buffer | null = null;
    let idatCount = 0;

    let offset = PNG_SIGNATURE.length;
    const expectedIHDR = 13;

    while (offset < data.length) {
        const chunkLength = data.readUInt32BE(offset);
        const chunkType = data.slice(offset + 4, offset + 8).toString('ascii');
        const chunkData = data.slice(offset + 8, offset + 8 + chunkLength);
        const chunkCRC = data.readUInt32BE(offset + 8 + chunkLength);
        const computedCRC = crc32(data.slice(offset + 4, offset + 8 + chunkLength));
        const valid = chunkCRC === computedCRC;

        chunks.push({ type: chunkType, length: chunkLength, data: chunkData, crc: chunkCRC, valid });

        if (chunkType === 'IHDR') {
            if (!ihdr) {
                ihdr = {
                    width: data.readUInt32BE(0),
                    height: data.readUInt32BE(4),
                    bitDepth: data.readUInt8(8),
                    colorType: data.readUInt8(9),
                    interlace: data.readUInt8(10)
                };
            }
            offset += 8 + chunkLength;
        } else if (chunkType === 'PLTE') {
            plte = chunkData;
            offset += 8 + chunkLength;
        } else if (chunkType === 'tRNS') {
            trns = chunkData;
            offset += 8 + chunkLength;
        } else if (chunkType === 'IDAT') {
            if (!idat) {
                idat = chunkData;
                idatCount++;
            } else {
                idat = Buffer.concat([idat, chunkData]);
                idatCount++;
            }
            offset += 8 + chunkLength;
        } else if (chunkType === 'IEND') {
            break;
        } else {
            offset += 8 + chunkLength;
        }
    }

    return { chunks, ihdr, plte, trns, idat: idat || Buffer.alloc(0), idatCount };
}

// Decompress zlib stream
function decompressZlib(data: Buffer, expectedCRC: number): { decompressed: Buffer; valid: boolean; blockTypes: number[] } {
    try {
        const compressed = data;
        const decompressed = zlib.inflateRawSync(compressed);
        const computedCRC = crc32(decompressed);
        const valid = computedCRC === expectedCRC;
        return { decompressed, valid, blockTypes: [] };
    } catch {
        return { decompressed: Buffer.alloc(0), valid: false, blockTypes: [] };
    }
}

// Count DEFLATE block types
function countBlockTypes(data: Buffer): { stored: number; fixed: number; dynamic: number } {
    let stored = 0;
    let fixed = 0;
    let dynamic = 0;
    let offset = 0;
    while (offset < data.length) {
        const type = data.readUInt8(offset);
        const btype = data.readUInt8(offset + 1);
        if (btype === 0) stored++;
        else if (btype === 1) fixed++;
        else if (btype === 2) dynamic++;
        offset += 2;
    }
    return { stored, fixed, dynamic };
}

// Decode pixel to RGBA
function decodePixelToRGBA(
    pixelValue: number,
    colorType: number,
    bitDepth: number,
    trns: Buffer | null,
    plte: Buffer | null,
    width: number,
    height: number
): number[] {
    const r: number[] = [];
    const g: number[] = [];
    const b: number[] = [];
    const a: number[] = [];

    const pixelSize = bitDepth === 16 ? 2 : 1;
    const value = pixelValue;

    if (colorType === 0 || colorType === 4) {
        const gray = value;
        if (bitDepth <= 4) {
            gray = Math.floor(gray * 255 / ((1 << bitDepth) - 1));
        }
        r.push(gray);
        g.push(gray);
        b.push(gray);
        a.push(255);
    } else if (colorType === 2) {
        const r = value & 0xFF;
        const g = (value >> 8) & 0xFF;
        const b = (value >> 16) & 0xFF;
        r.push(r);
        g.push(g);
        b.push(b);
        a.push(255);
    } else if (colorType === 3) {
        const index = value & 0xFF;
        const plteIndex = index;
        const trnsIndex = index;
        if (trns && trns.length > 0) {
            const trnsIndex = trns.readUInt8(trnsIndex);
            a.push(trnsIndex === 255 ? 255 : trnsIndex);
        } else {
            a.push(255);
        }
        if (plte) {
            const r = plte.readUInt8(plteIndex * 3);
            const g = plte.readUInt8(plteIndex * 3 + 1);
            const b = plte.readUInt8(plteIndex * 3 + 2);
            r.push(r);
            g.push(g);
            b.push(b);
        } else {
            r.push(0);
            g.push(0);
            b.push(0);
        }
    } else if (colorType === 4 || colorType === 6) {
        const r = value & 0xFF;
        const g = (value >> 8) & 0xFF;
        const b = (value >> 16) & 0xFF;
        const a = (value >> 24) & 0xFF;
        r.push(r);
        g.push(g);
        b.push(b);
        a.push(a);
    }

    return r.concat(g, b, a);
}

// Count filters
function countFilters(data: Buffer): { none: number; sub: number; up: number; average: number; paeth: number } {
    let none = 0;
    let sub = 0;
    let up = 0;
    let average = 0;
    let paeth = 0;
    for (let i = 0; i < data.length; i += 4) {
        const filter = data[i];
        if (filter === 0) none++;
        else if (filter === 1) sub++;
        else if (filter === 2) up++;
        else if (filter === 3) average++;
        else if (filter === 4) paeth++;
    }
    return { none, sub, up, average, paeth };
}

// Main function
function main() {
    initCRCTable();

    const args = process.argv.slice(2);
    if (args.length === 0) {
        process.exit(1);
    }

    const dir = args[0];
    const files = fs.readdirSync(dir)
        .filter(f => f.endsWith('.png'))
        .sort();

    for (const file of files) {
        const filePath = path.join(dir, file);
        const data = fs.readFileSync(filePath);

        if (!PNG_SIGNATURE.equals(data.slice(0, 8))) {
            console.log(`== ${file}`);
            console.log(`error: Invalid PNG signature`);
            continue;
        }

        const chunks = parseChunks(data);
        let error = false;
        let chunkError = '';

        if (!chunks.ihdr) {
            console.log(`== ${file}`);
            console.log(`error: No IHDR chunk`);
            continue;
        }

        let valid = true;
        for (let i = 0; i < chunks.chunks.length; i++) {
            const chunk = chunks.chunks[i];
            if (!chunk.valid) {
                error = true;
                chunkError = `CRC mismatch in chunk ${i + 1} ${chunk.type}`;
                break;
            }
        }

        if (error) {
            console.log(`== ${file}`);
            console.log(`error: ${chunkError}`);
            continue;
        }

        const idat = chunks.idat;
        const blockTypes = countBlockTypes(idat);

        const zlibResult = decompressZlib(idat, 0);
        if (!zlibResult.valid) {
            console.log(`== ${file}`);
            console.log(`error: Adler-32 mismatch`);
            continue;
        }

        const decompressed = zlibResult.decompressed;

        const filters = countFilters(decompressed);

        const rgbaBuffer = Buffer.alloc(0);
        let sumR = 0;
        let sumG = 0;
        let sumB = 0;
        let sumA = 0;

        const { width, height, bitDepth, colorType } = chunks.ihdr;
        const stride = width * 4;

        for (let row = 0; row < height; row++) {
            for (let col = 0; col < width; col++) {
                const offset = row * stride + col * 4;
                const pixel = decompressed.readUInt8(offset);
                const r = decodePixelToRGBA(pixel, colorType, bitDepth, chunks.trns, chunks.plte, width, height);
                rgbaBuffer = Buffer.concat([rgbaBuffer, Buffer.from(r)]);
                sumR += r[0];
                sumG += r[1];
                sumB += r[2];
                sumA += r[3];
            }
        }

        const crc = crc32(rgbaBuffer);

        const chunkTypes = chunks.chunks.map(c => {
            const count = chunks.chunks.filter(x => x.type === c.type).length;
            return count > 1 ? `${c.type}*${count}` : c.type;
        }).join(' ');

        console.log(`== ${file}`);
        console.log(`IHDR ${width}x${height} depth=${bitDepth} color=${colorType}`);
        console.log(`chunks ${chunkTypes}`);
        console.log(`deflate stored=${blockTypes.stored} fixed=${blockTypes.fixed} dynamic=${blockTypes.dynamic}`);
        console.log(`filters none=${filters.none} sub=${filters.sub} up=${filters.up} average=${filters.average} paeth=${filters.paeth}`);
        console.log(`rgba sum=${sumR},${sumG},${sumB},${sumA} crc32=${crc.toString(16).padStart(8, '0').toLowerCase()}`);
    }
}

main();

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/stat.h>

// CRC-32 table initialization
static uint32_t crc32_table[256];
static void crc32_init(void) {
    for (int i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++) {
            c = (c << 1) ^ ((c >> 7) & 0xFF) * 0xEDB88320;
        }
        crc32_table[i] = c;
    }
}

// CRC-32 calculation
static uint32_t crc32(const unsigned char *data, size_t len) {
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++) {
        crc = (crc >> 8) ^ crc32_table[(crc ^ data[i]) & 0xFF];
    }
    return crc ^ 0xFFFFFFFF;
}

// Line structure
typedef struct {
    unsigned char *bytes;
    size_t len;
    int has_newline;
} Line;

// File content
typedef struct {
    Line *lines;
    size_t line_count;
} FileContent;

// Hunk info
typedef struct {
    int applied;
    int line;          // applied line number (1-based)
    int offset;        // line offset from expected position
    int old_count;     // b from hunk header
    int new_count;     // d from hunk header
    char *old_lines;   // old lines content
    char *new_lines;   // new lines content
    int is_malformed;
} Hunk;

// Section info
typedef struct {
    char *path;
    int kind;          // 0=create, 1=modify, 2=delete
    Hunk *hunks;
    int hunk_count;
    char *old_path;
    char *new_path;
    int is_empty_file;
} Section;

// Section file info
typedef struct {
    char *path;
    Section *section;
} SectionFile;

// Global state
static unsigned char *diff_content = NULL;
static size_t diff_len = 0;
static FileContent *file_contents = NULL;
static size_t file_count = 0;
static Section *sections = NULL;
static size_t section_count = 0;
static SectionFile *section_files = NULL;
static size_t section_file_count = 0;
static SectionFile *files_to_report = NULL;
static size_t files_to_report_count = 0;
static int error_occurred = 0;

// Helper functions
static char *trim_leading_spaces(char *str) {
    while (*str == ' ') str++;
    return str;
}

static char *trim_trailing_spaces(char *str) {
    char *end = str + strlen(str) - 1;
    while (end >= str && *end == ' ') end--;
    *end = '\0';
    return str;
}

static void free_lines(Line *lines, size_t count) {
    for (size_t i = 0; i < count; i++) {
        free(lines[i].bytes);
    }
    free(lines);
}

static void free_file_content(FileContent *fc) {
    free_lines(fc->lines, fc->line_count);
    free(fc->lines);
}

static void free_section(Section *s) {
    for (int i = 0; i < s->hunk_count; i++) {
        free(s->hunks[i].old_lines);
        free(s->hunks[i].new_lines);
    }
    free(s->hunks);
    free(s->path);
    free(s->old_path);
    free(s->new_path);
}

static void free_sections(void) {
    for (size_t i = 0; i < section_count; i++) {
        free_section(&sections[i]);
    }
    free(sections);
}

static void free_section_files(void) {
    for (size_t i = 0; i < section_file_count; i++) {
        free(section_files[i].path);
    }
    free(section_files);
}

static void free_diff_content(void) {
    free(diff_content);
}

static void free_file_contents(void) {
    for (size_t i = 0; i < file_count; i++) {
        free_file_content(&file_contents[i]);
    }
    free(file_contents);
}

static void free_files_to_report(void) {
    for (size_t i = 0; i < files_to_report_count; i++) {
        free(files_to_report[i].path);
    }
    free(files_to_report);
}

static void load_directory(const char *dir, SectionFile **files) {
    DIR *dp = opendir(dir);
    if (!dp) return;
    struct dirent *entry;
    while ((entry = readdir(dp)) != NULL) {
        if (entry->d_type == DT_REG || entry->d_type == DT_UNKNOWN) {
            char *path = strdup(entry->d_name);
            char *last_slash = strrchr(path, '/');
            if (last_slash) {
                *last_slash = '\0';
                // Remove leading './' if present
                if (strlen(path) == 1) {
                    path = strdup("./");
                    strcat(path, entry->d_name);
                }
            } else {
                path = strdup(dir);
                strcat(path, entry->d_name);
            }
            (*files)[file_count].path = path;
            (*files)[file_count].section = NULL;
            file_count++;
        }
    }
    closedir(dp);
}

static void add_to_files_to_report(SectionFile *sf, Section *s) {
    size_t new_count = files_to_report_count + 1;
    SectionFile *new_arr = realloc(files_to_report, new_count * sizeof(SectionFile));
    if (!new_arr) return;
    files_to_report = new_arr;
    files_to_report[files_to_report_count].path = sf->path;
    files_to_report[files_to_report_count].section = s;
    files_to_report_count++;
}

static SectionFile *find_file_by_path(const char *path) {
    for (size_t i = 0; i < file_count; i++) {
        if (strcmp(section_files[i].path, path) == 0) {
            return &section_files[i];
        }
    }
    return NULL;
}

static int strcmp_path(char *a, char *b) {
    return strcmp(a, b);
}

static int compare_paths(const void *a, const void *b) {
    return strcmp_path(*(char**)a, *(char**)b);
}

// Parse a line to extract marker and content
static int parse_line_marker(char *line, char **marker, char **content) {
    *marker = NULL;
    *content = NULL;
    int marker_pos = 0;
    for (int i = 0; line[i] != '\0'; i++) {
        if (line[i] == ' ') {
            *marker = malloc(1);
            if (*marker) (*marker)[0] = line[i];
            *content = line + i + 1;
            return 1;
        }
    }
    return 0;
}

// Check if line is empty (just \n)
static int is_empty_line(const unsigned char *line, size_t len) {
    return len == 1 && line[0] == '\n';
}

// Check if line is "No newline at end of file"
static int is_no_newline_marker(const unsigned char *line, size_t len) {
    return len >= 23 && memcmp(line, "\ No newline at end of file", 23) == 0;
}

// Check if line starts with marker
static int line_starts_with_marker(const unsigned char *line, size_t len, char marker) {
    return len >= 1 && line[0] == marker;
}

// Compare two lines for equality
static int lines_equal(const Line *l1, const Line *l2) {
    if (l1->len != l2->len) return 0;
    if (l1->len == 0) return l1->has_newline == l2->has_newline;
    if (l1->has_newline != l2->has_newline) return 0;
    for (size_t i = 0; i < l1->len; i++) {
        if (l1->bytes[i] != l2->bytes[i]) return 0;
    }
    return 1;
}

// Parse a hunk header
static void parse_hunk_header(const char *line, int *a, int *b, int *c, int *d) {
    char *end = line + strlen(line);
    int pos = 0;
    *a = 0; *b = 0; *c = 0; *d = 0;
    while (pos < end - 2) {
        if (line[pos] == '@' && line[pos + 1] == '@') {
            break;
        }
        pos++;
    }
    if (pos < 0) return;
    char *p = line + pos + 2;
    while (*p == ' ') p++;
    *a = 0;
    int comma = 0;
    while (*p && *p != ',' && *p != '+' && *p != '-' && *p != '\\' && *p != ' ') {
        *a = *a * 10 + (*p - '0');
        p++;
    }
    if (*p == ',') {
        comma = 1;
        p++;
        while (*p && *p != ',' && *p != '+' && *p != '-' && *p != '\\' && *p != ' ') {
            *b = *b * 10 + (*p - '0');
            p++;
        }
    } else {
        *b = 1;
    }
    if (*p == '+') {
        p++;
        while (*p && *p != ',' && *p != '-' && *p != '\\' && *p != ' ') {
            *c = *c * 10 + (*p - '0');
            p++;
        }
        if (*p == ',') {
            p++;
            while (*p && *p != '+' && *p != '-' && *p != '\\' && *p != ' ') {
                *d = *d * 10 + (*p - '0');
                p++;
            }
        } else {
            *d = 1;
        }
    } else if (*p == '-') {
        p++;
        while (*p && *p != ',' && *p != '+' && *p != '\\' && *p != ' ') {
            *c = *c * 10 + (*p - '0');
            p++;
        }
        if (*p == ',') {
            p++;
            while (*p && *p != '+' && *p != '-' && *p != '\\' && *p != ' ') {
                *d = *d * 10 + (*p - '0');
                p++;
            }
        } else {
            *d = 1;
        }
    }
}

// Find matching position for hunk
static int find_hunk_position(FileContent *content, Hunk *hunk, int delta) {
    int old_count = hunk->old_count;
    int new_count = hunk->new_count;
    int expected_pos = hunk->old_count + delta;

    // Try positions from expected_pos outward
    for (int dist = 0; ; dist++) {
        int p = expected_pos + (dist % 2 == 0 ? dist : -dist);
        if (p < 1 || p + old_count - 1 >= content->line_count) continue;

        int match = 1;
        for (int i = 0; i < old_count; i++) {
            Line *old_line = &content->lines[p + i - 1];
            Line *hunk_old_line = &hunk->old_lines[i];
            if (!lines_equal(old_line, hunk_old_line)) {
                match = 0;
                break;
            }
        }
        if (match) {
            return p;
        }
    }
    return -1;
}

// Apply a hunk to content
static void apply_hunk(FileContent *content, Hunk *hunk) {
    int p = find_hunk_position(content, hunk, 0);
    if (p < 0) {
        hunk->applied = 0;
        hunk->line = 0;
        hunk->offset = 0;
        return;
    }

    // Build new content
    Line *new_lines = malloc(content->line_count * sizeof(Line));
    size_t new_count = 0;

    // Copy lines before p
    for (int i = 0; i < p - 1; i++) {
        new_lines[i] = content->lines[i];
        new_count++;
    }

    // Add new lines
    for (int i = 0; i < hunk->new_count; i++) {
        new_lines[new_count + i] = hunk->new_lines[i];
        new_count += hunk->new_count;
    }

    // Copy lines after p
    for (int i = p + hunk->old_count - 1; i < content->line_count; i++) {
        new_lines[new_count + hunk->old_count - 1 + (i - p)] = content->lines[i];
    }

    free(content->lines);
    content->lines = new_lines;
    content->line_count = new_count;

    hunk->applied = 1;
    hunk->line = p;
    hunk->offset = p - hunk->old_count;
}

// Parse a diff section
static int parse_section(const unsigned char *data, size_t len, Section *section) {
    int path_start = 0;
    int path_end = 0;
    int kind = 1; // default modify
    int empty_file = 0;
    int has_diff_git = 0;
    int has_new_file_mode = 0;
    int has_deleted_file_mode = 0;
    int has_index = 0;
    int has_hunk_header = 0;
    int has_dev_null = 0;

    while (path_end < len) {
        if (data[path_end] == '\n') {
            break;
        }
        path_end++;
    }

    char path_str[1024];
    if (path_end < len) {
        strncpy(path_str, (char*)data + path_start, path_end - path_start);
        path_str[path_end - path_start] = '\0';
    } else {
        path_str[0] = '\0';
    }

    if (strlen(path_str) == 0) return 0;

    int is_create = 0;
    int is_delete = 0;
    int is_modify = 1;

    // Check for new file mode
    if (strstr(path_str, "new file mode")) {
        is_create = 1;
        is_modify = 0;
    }
    // Check for deleted file mode
    if (strstr(path_str, "deleted file mode")) {
        is_delete = 1;
        is_modify = 0;
    }

    // Check for /dev/null
    if (strstr(path_str, "/dev/null")) {
        has_dev_null = 1;
    }

    section->kind = is_create ? 0 : is_delete ? 2 : 1;
    section->is_empty_file = empty_file;

    // Parse old_path and new_path
    if (is_create || is_delete) {
        section->old_path = strdup(path_str);
        section->new_path = strdup(path_str);
    } else {
        section->old_path = strdup(path_str);
        section->new_path = strdup(path_str);
    }

    // Parse hunks
    section->hunks = NULL;
    section->hunk_count = 0;
    section->path = strdup(path_str);
    path_end = path_start + strlen(path_str) + 1; // skip newline

    while (path_end < len) {
        if (data[path_end] == '\n') {
            path_end++;
            continue;
        }
        int hunk_end = path_end;
        while (hunk_end < len && data[hunk_end] != '\n') {
            hunk_end++;
        }
        if (hunk_end >= len) {
            hunk_end = len;
        }

        char *hunk_line = (char*)data + path_start + hunk_end;
        if (hunk_line[0] == '@' && hunk_line[1] == '@') {
            // Hunk header
            int a, b, c, d;
            parse_hunk_header(hunk_line, &a, &b, &c, &d);

            // Parse hunk body
            int hunk_count = 0;
            int old_lines = 0;
            int new_lines = 0;
            int has_old = 0;
            int has_new = 0;

            char *body_start = hunk_line + strlen(hunk_line) + 1;
            char *body_end = data + len;
            char *body = body_start;

            while (body < body_end) {
                if (body[0] == '@' && body[1] == '@') {
                    break;
                }
                if (body[0] == ' ') {
                    has_old = 1;
                    has_new = 1;
                    old_lines++;
                    new_lines++;
                } else if (body[0] == '-') {
                    has_old = 1;
                    old_lines++;
                } else if (body[0] == '+') {
                    has_new = 1;
                    new_lines++;
                } else if (body[0] == '\\') {
                    // No newline marker
                    // Check if it's actually a marker
                    if (body[1] == ' ' && body[2] == 'N') {
                        // It's a marker, skip it
                    } else {
                        // Regular line
                        has_old = 1;
                        old_lines++;
                        has_new = 1;
                        new_lines++;
                    }
                }
                body++;
            }

            if (has_old && has_new) {
                // Build old and new lines
                char **old_lines_arr = malloc(old_lines * sizeof(char*));
                char **new_lines_arr = malloc(new_lines * sizeof(char*));

                int old_pos = 0;
                int new_pos = 0;
                char *old_line = body_start;
                char *old_body = body_start;

                while (body < body_end) {
                    if (body[0] == '@' && body[1] == '@') break;
                    if (body[0] == ' ') {
                        old_lines_arr[old_pos] = strdup(old_body);
                        new_lines_arr[new_pos] = strdup(old_body);
                        old_pos++;
                        new_pos++;
                    } else if (body[0] == '-') {
                        old_lines_arr[old_pos] = strdup(old_body);
                        old_pos++;
                    } else if (body[0] == '+') {
                        new_lines_arr[new_pos] = strdup(old_body);
                        new_pos++;
                    }
                    body++;
                }

                // Create hunk
                Hunk *hunk = malloc(sizeof(Hunk));
                hunk->applied = 0;
                hunk->line = 0;
                hunk->offset = 0;
                hunk->old_count = old_lines;
                hunk->new_count = new_lines;
                hunk->old_lines = old_lines_arr;
                hunk->new_lines = new_lines_arr;
                hunk->is_malformed = 0;

                if (section->hunk_count == 0) {
                    section->hunks = malloc(sizeof(Hunk));
                } else {
                    section->hunks = realloc(section->hunks, (section->hunk_count + 1) * sizeof(Hunk));
                }
                section->hunks[section->hunk_count] = *hunk;
                free(hunk);
                section->hunk_count++;
            }
        }
        path_end = hunk_end;
    }

    return 1;
}

// Main
int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <diff_file> <tree_dir>\n", argv[0]);
        return 1;
    }

    const char *diff_file = argv[1];
    const char *tree_dir = argv[2];

    // Read diff file
    FILE *fp = fopen(diff_file, "rb");
    if (!fp) {
        fprintf(stderr, "Cannot open %s\n", diff_file);
        return 1;
    }
    fseek(fp, 0, SEEK_END);
    long diff_size = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    diff_content = malloc(diff_size);
    if (!diff_content) {
        fprintf(stderr, "Cannot allocate memory\n");
        fclose(fp);
        return 1;
    }
    size_t read_size = fread(diff_content, 1, diff_size, fp);
    fclose(fp);
    diff_len = read_size;

    // Load directory
    SectionFile *files = malloc(1024 * sizeof(SectionFile));
    load_directory(tree_dir, &files);

    // Parse diff sections
    Section *sections_arr = malloc(1024 * sizeof(Section));
    size_t section_count_arr = 0;
    size_t section_pos = 0;

    while (section_pos < diff_len) {
        Section *section = malloc(sizeof(Section));
        memset(section, 0, sizeof(Section));

        int section_end = diff_len;
        while (section_end < diff_len && diff_content[section_end] != '\n') {
            section_end++;
        }
        if (section_end == diff_len) break;
        section_end++;

        if (parse_section(diff_content, diff_len, section) == 0) {
            free(section);
            continue;
        }

        // Find matching file
        SectionFile *sf = find_file_by_path(section->path);
        if (sf) {
            sf->section = section;
        } else {
            // File doesn't exist - create a section file entry
            SectionFile *new_sf = malloc(sizeof(SectionFile));
            new_sf->path = strdup(section->path);
            new_sf->section = section;
            section_count_arr++;
            sections_arr[section_count_arr] = section;
            section_count_arr++;
        }

        section_count_arr++;
        section_pos = section_end;
    }

    // Sort sections by path
    qsort(sections_arr, section_count_arr, sizeof(Section), compare_paths);

    // Apply sections
    for (size_t i = 0; i < section_count_arr; i++) {
        Section *s = &sections_arr[i];

        // Check for errors
        if (s->kind == 0) { // create
            SectionFile *sf = find_file_by_path(s->path);
            if (sf) {
                fprintf(stderr, "%s: already exists\n", s->path);
                error_occurred = 1;
                continue;
            }
        } else if (s->kind == 2) { // delete
            SectionFile *sf = find_file_by_path(s->path);
            if (!sf) {
                fprintf(stderr, "%s: not found\n", s->path);
                error_occurred = 1;
                continue;
            }
        } else { // modify
            SectionFile *sf = find_file_by_path(s->path);
            if (!sf) {
                fprintf(stderr, "%s: not found\n", s->path);
                error_occurred = 1;
                continue;
            }
        }

        // Initialize file content
        FileContent *fc = &file_contents[file_count];
        memset(fc, 0, sizeof(FileContent));
        fc->lines = malloc(1024 * sizeof(Line));
        fc->line_count = 0;

        // Get old content
        if (s->kind != 0) { // not create
            SectionFile *sf = find_file_by_path(s->path);
            if (sf) {
                FileContent *old_fc = &file_contents[sf->section->old_path_index];
                if (old_fc->line_count > 0) {
                    fc->lines = malloc(old_fc->line_count * sizeof(Line));
                    for (size_t i = 0; i < old_fc->line_count; i++) {
                        fc->lines[i] = old_fc->lines[i];
                    }
                    fc->line_count = old_fc->line_count;
                }
            }
        }

        // Apply hunks
        int delta = 0;
        for (int h = 0; h < s->hunk_count; h++) {
            Hunk *hunk = &s->hunks[h];

            if (hunk->old_count == 0) {
                // No old lines - insert at position
