                } else {
                    hunk->applied = 0;
                    hunk->line = 0;
                    hunk->offset = 0;
                }
            }

            delta += hunk->new_count - hunk->old_count;
        }

        // Handle delete
        if (s->kind == 2) {
            // Delete only if content is empty
            if (fc->line_count == 0) {
                // File is deleted
            } else {
                // File is kept (patched)
            }
        }

        // Add to files to report
        add_to_files_to_report(&files[file_count], s);
    }

    // Output results
    qsort(files_to_report, files_to_report_count, sizeof(SectionFile), compare_paths);

    for (size_t i = 0; i < files_to_report_count; i++) {
        SectionFile *sf = &files_to_report[i];
        Section *s = sf->section;

        printf("%s: %s\n", sf->path, (s->kind == 0) ? "create" : (s->kind == 2) ? "delete" : "modify");

        if (error_occurred) {
            printf("  error: %s\n", (s->kind == 0) ? "already exists" : "not found");
            continue;
        }

        for (int h = 0; h < s->hunk_count; h++) {
