}

import * as fs from 'fs';
import * as zlib from 'zlib';

// PNG constants
const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);
const IHDR_CHUNK = Buffer.from('IHDR', 'ascii');
const IDAT_CHUNK = Buffer.from('IDAT', 'ascii');
const IEND_CHUNK = Buffer.from('IEND', 'ascii');

type Pixel = [number, number, number];
type Shape = {
  type: string;
  x?: number;
  y?: number;
  w?: number;
  h?: number;
  cx?: number;
  cy?: number;
  r?: number;
  points?: number[][];
  x1?: number;
  y1?: number;
  x2?: number;
  y2?: number;
  color: number[];
};

function crc32(buf: Buffer): number {
  let crc = 0xFFFFFFFF;
  const poly = [
    0, 1, 3, 2, 6, 7, 5, 4, 12, 13, 11, 10, 9, 8, 14, 15,
    3, 2, 0, 1, 7, 6, 4, 5, 13, 12, 10, 11, 9, 8, 14, 15,
    2, 3, 0, 1, 8, 9, 6, 7, 14, 15, 12, 13, 4, 5, 2, 3,
    11, 10, 7, 8, 15, 14, 11, 10, 1, 0, 3, 2, 9, 8, 5, 6,
    12, 13, 10, 11, 2, 3, 0, 1, 10, 9, 6, 7, 14, 15, 12, 13,
    4, 5, 2, 3, 11, 10, 7, 8, 15, 14, 11, 10, 1, 0, 3, 2,
    8, 9, 6, 7, 12, 13, 10, 11, 4, 5, 2, 3, 14, 15, 12, 13,
    1, 0, 3, 2, 9, 8, 5, 6, 13, 12, 10, 11, 7, 8, 4, 5,
    11, 10, 7, 8, 15, 14, 12, 13, 3, 2, 0, 1, 10, 9, 6, 7,
    1, 0, 3, 2, 9, 8, 5, 6, 13, 12, 10, 11, 7, 8, 4, 5
  ];
  const lookup = new Uint8Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) {
      c = (c & 1) ? (0xEDB88320 >>> (c >>> 1)) : (c >>> 1);
    }
    lookup[i] = c & 0xFF;
  }
  for (let i = 0; i < buf.length; i++) {
    crc = (crc >>> 8) ^ lookup[(crc ^ buf[i]) & 0xFF];
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function makeChunk(type: Buffer, data: Buffer): Buffer {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(Buffer.concat([type, data, length])), 0);
  return Buffer.concat([length, type, data, crc]);
}

function compressImage(data: Buffer): Buffer {
  return zlib.deflateSync(data);
}

function renderScene(scene: any): { out: Buffer; shapeCounts: number[]; colorCounts: number[] } {
  const { width, height, background, shapes } = scene;
  const canvas: Pixel[][] = new Array(width * height).fill([0, 0, 0]);

  const shapeCounts: number[] = [];

  for (let i = 0; i < shapes.length; i++) {
    const shape = shapes[i];
    const shapeColor = shape.color;
    const [sR, sG, sB, sA] = shapeColor;

    const covered = new Set<number>();

    if (shape.type === 'rect') {
      const { x, y, w, h } = shape;
      for (let px = Math.floor(x); px < x + w && px < width; px++) {
        for (let py = Math.floor(y); py < y + h && py < height; py++) {
          covered.add(px + py * width);
        }
      }
    } else if (shape.type === 'circle') {
      const { cx, cy, r } = shape;
      const r2 = r * r;
      for (let py = Math.floor(cy - r); py <= Math.ceil(cy + r) && py >= 0 && py < height; py++) {
        const dy = py - cy;
        const maxDx = Math.sqrt(r2 - dy * dy);
        const maxDxInt = Math.floor(maxDx);
        for (let px = Math.floor(cx - maxDxInt); px <= Math.ceil(cx + maxDxInt) && px >= 0 && px < width; px++) {
          const dx = px - cx;
          if (dx * dx + dy * dy <= r2) {
            covered.add(px + py * width);
          }
        }
      }
    } else if (shape.type === 'triangle') {
      const points = shape.points as number[][];
      for (let py = 0; py < height; py++) {
        for (let px = 0; px < width; px++) {
          let inTriangle = false;
          for (let i = 0; i < 3; i++) {
            const j = (i + 1) % 3;
            const [xi, yi] = points[i];
            const [xj, yj] = points[j];
            const E = (xj - xi) * (py - yi) - (yj - yi) * (px - xi);
            if (E < 0) {
              if (E > 0) inTriangle = true;
            } else if (E > 0) {
              if (E < 0) inTriangle = true;
            }
          }
          if (inTriangle) {
            covered.add(px + py * width);
          }
        }
      }
    } else if (shape.type === 'line') {
      const { x1, y1, x2, y2, r } = shape;
      const dx = x2 - x1;
      const dy = y2 - y1;
      const L = dx * dx + dy * dy;
      const r2 = r * r;

      for (let py = 0; py < height; py++) {
        for (let px = 0; px < width; px++) {
          const t = (px - x1) * dx + (py - y1) * dy;
          if (t <= 0) {
            const distSq = (px - x1) * (px - x1) + (py - y1) * (py - y1);
            if (distSq <= r2) covered.add(px + py * width);
          } else if (t >= L) {
            const distSq = (px - x2) * (px - x2) + (py - y2) * (py - y2);
            if (distSq <= r2) covered.add(px + py * width);
          } else {
            const c = (px - x1) * dy - (py - y1) * dx;
            if (c * c <= r2 * L) covered.add(px + py * width);
          }
        }
      }
    }

    shapeCounts.push(covered.size);

    for (const pixelIdx of covered) {
      const [dR, dG, dB] = canvas[pixelIdx];
      const newR = Math.floor((sR * sA + dR * (255 - sA) + 127) / 255);
      const newG = Math.floor((sG * sA + dG * (255 - sA) + 127) / 255);
      const newB = Math.floor((sB * sA + dB * (255 - sA) + 127) / 255);
      canvas[pixelIdx] = [newR, newG, newB];
    }
  }

  // Count distinct colors
  const colorSet = new Set<string>();
  for (let i = 0; i < canvas.length; i++) {
    colorSet.add(`${canvas[i][0]},${canvas[i][1]},${canvas[i][2]}`);
  }

  const colorCounts = Array.from(colorSet).length;

  // Convert to PNG
  const out = Buffer.alloc(4 + 13 + 13 + compressImage(Buffer.concat(canvas.map((row, i) => {
    const rowBuf = Buffer.alloc(3 * width);
    for (let px = 0; px < width; px++) {
      const idx = i + px * width;
      const [r, g, b] = canvas[idx];
      rowBuf[px * 3] = r;
      rowBuf[px * 3 + 1] = g;
      rowBuf[px * 3 + 2] = b;
    }
    return rowBuf;
})), 0));
  const compressed = zlib.deflateSync(Buffer.concat(canvas.map((row, i) => {
    const rowBuf = Buffer.alloc(3 * width);
    for (let px = 0; px < width; px++) {
      const idx = i + px * width;
      const [r, g, b] = canvas[idx];
      rowBuf[px * 3] = r;
      rowBuf[px * 3 + 1] = g;
      rowBuf[px * 3 + 2] = b;
    }
    return rowBuf;
}));

  return { out: compressed, shapeCounts, colorCounts };
}

function main() {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    console.error('Usage: tsx main.ts <scene_dir>');
    process.exit(1);
  }
  const sceneDir = args[0];
  const scenePath = fs.path.join(sceneDir, 'scene.json');
  const scene = JSON.parse(fs.readFileSync(scenePath, 'utf8'));
  const { out, shapeCounts, colorCounts } = renderScene(scene);
  fs.writeFileSync('out.png', out);
  for (let i = 0; i < shapeCounts.length; i++) {
    console.log(`${i + 1} ${shapes[i].type} ${shapeCounts[i]}`);
  }
  console.log(`colors ${colorCounts}`);
}

const scene = JSON.parse(fs.readFileSync('scene.json', 'utf8'));
