}
console.log(`colors ${colorCounts}`);

#!/usr/bin/env python3
import sys
import json
import struct
import zlib
import os

def blend_color(dR, dG, dB, sR, sG, sB, A):
    """Blend shape color (sR, sG, sB, A) with destination (dR, dG, dB)"""
    r = (sR * A + dR * (255 - A) + 127) // 255
    g = (sG * A + dG * (255 - A) + 127) // 255
    b = (sB * A + dB * (255 - A) + 127) // 255
    return r, g, b

def check_rect(x, y, w, h, rx, ry):
    """Check if pixel (x, y) is in rect [rx, rx+w) × [ry, ry+h)"""
    return rx <= x < rx + w and ry <= y < ry + h

def check_circle(x, y, cx, cy, r):
    """Check if pixel (x, y) is in circle centered at (cx, cy) with radius r"""
    return (x - cx) * (x - cx) + (y - cy) * (y - cy) <= r * r

def check_triangle(x, y, points):
    """Check if pixel (x, y) is in triangle defined by points"""
    p0, p1, p2 = points
    E0 = (p1[0] - p0[0]) * (y - p0[1]) - (p1[1] - p0[1]) * (x - p0[0])
    E1 = (p2[0] - p1[0]) * (y - p1[1]) - (p2[1] - p1[1]) * (x - p1[0])
    E2 = (p0[0] - p2[0]) * (y - p2[1]) - (p0[1] - p2[1]) * (x - p2[0])
    if E0 >= 0 and E1 >= 0 and E2 >= 0:
        return True
    if E0 <= 0 and E1 <= 0 and E2 <= 0:
        return True
    return False

def check_line(x, y, x1, y1, x2, y2, r):
    """Check if pixel (x, y) is within distance r of line segment from (x1, y1) to (x2, y2)"""
    dx = x2 - x1
    dy = y2 - y1
    L = dx * dx + dy * dy
    t = (x - x1) * dx + (y - y1) * dy

    if t <= 0:
        return (x - x1) * (x - x1) + (y - y1) * (y - y1) <= r * r
    elif t >= L:
        return (x - x2) * (x - x2) + (y - y2) * (y - y2) <= r * r
    else:
        c = (x - x1) * dy - (y - y1) * dx
        return c * c <= r * r * L

def check_shape(x, y, shape):
    """Check if pixel (x, y) is covered by shape"""
    shape_type = shape['type']
    if shape_type == 'rect':
        return check_rect(x, y, shape['w'], shape['h'], shape['x'], shape['y'])
    elif shape_type == 'circle':
        return check_circle(x, y, shape['cx'], shape['cy'], shape['r'])
    elif shape_type == 'triangle':
        return check_triangle(x, y, shape['points'])
    elif shape_type == 'line':
        return check_line(x, y, shape['x1'], shape['y1'], shape['x2'], shape['y2'], shape['r'])
    return False

def count_covered_pixels(shape):
    """Count pixels covered by shape for the current canvas"""
    count = 0
    shape_type = shape['type']
    shape_type = shape['type']
    if shape_type == 'rect':
        x, y = shape['x'], shape['y']
        w, h = shape['w'], shape['h']
        for i in range(x, x + w):
            for j in range(y, y + h):
                if 0 <= i < width and 0 <= j < height:
                    count += 1
    elif shape_type == 'circle':
        cx, cy = shape['cx'], shape['cy']
        r = shape['r']
        for i in range(width):
            for j in range(height):
                if check_circle(i, j, cx, cy, r):
                    count += 1
    elif shape_type == 'triangle':
        points = shape['points']
        for i in range(width):
            for j in range(height):
                if check_triangle(i, j, points):
                    count += 1
    elif shape_type == 'line':
        x1, y1 = shape['x1'], shape['y1']
        x2, y2 = shape['x2'], shape['y2']
        r = shape['r']
        for i in range(width):
            for j in range(height):
                if check_line(i, j, x1, y1, x2, y2, r):
                    count += 1
    return count

def write_png(canvas, width, height, output_path):
    """Write canvas to PNG file"""
    # PNG signature
    signature = b'\x89PNG\r\n\x1a\n'

    # IHDR chunk
    ihdr_data = struct.pack('>IIBBBBB', width, height, 8, 2, 0, 0, 0)
    ihdr_chunk = struct.pack('>I', 13) + b'IHDR' + ihdr_data + struct.pack('>I', zlib.crc32(b'IHDR' + ihdr_data))

    # IDAT chunk (image data)
    raw_data = b''
    for y in range(height):
        for x in range(width):
            r, g, b = canvas[y][x]
            raw_data += bytes([r, g, b])

    raw_data = zlib.compress(raw_data)
    idat_chunk = struct.pack('>I', len(raw_data)) + b'IDAT' + raw_data + struct.pack('>I', zlib.crc32(b'IDAT' + raw_data))

    # IEND chunk
    iend_chunk = struct.pack('>I', 0) + b'IEND' + struct.pack('>I', zlib.crc32(b'IEND'))

    # Write file
    with open(output_path, 'wb') as f:
        f.write(signature)
        f.write(ihdr_chunk)
        f.write(idat_chunk)
        f.write(iend_chunk)

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    input_dir = sys.argv[1]
    scene_path = os.path.join(input_dir, 'scene.json')

    with open(scene_path, 'r') as f:
        scene = json.load(f)

    width = scene['width']
    height = scene['height']
    background = scene['background']
    shapes = scene['shapes']

    # Initialize canvas with background color
    canvas = [[background[:] for _ in range(width)] for _ in range(height)]

    # Process each shape
    shape_counts = []
    for i, shape in enumerate(shapes):
        count = 0
        shape_type = shape['type']

        # Count and blend pixels
        for y in range(height):
            for x in range(width):
                if check_shape(x, y, shape):
                    count += 1
                    # Get current canvas color
                    dR, dG, dB = canvas[y][x]
                    # Get shape color
                    cR, cG, cB, cA = shape['color']
                    # Blend
                    canvas[y][x] = blend_color(dR, dG, dB, cR, cG, cB, cA)

        shape_counts.append(count)

    # Count distinct colors
    colors = set()
    for y in range(height):
        for x in range(width):
            r, g, b = canvas[y][x]
            colors.add((r, g, b))

    # Write output
    write_png(canvas, width, height, 'out.png')

    # Print summary
    for i, count in enumerate(shape_counts):
        shape_type = shapes[i]['type']
        print(f"{i + 1} {shape_type} {count}")

    print(f"colors {len(colors)}")

if __name__ == '__main__':
    main()

import sys
import os
import re
import zlib

def crc32_bytes(data: bytes) -> int:
    """Compute CRC-32 using zlib/PNG algorithm."""
    return zlib.crc32(data) & 0xFFFFFFFF

def parse_hunk_header(header: bytes) -> tuple:
    """Parse @@ -<a>,<b> +<c>,<d> @@ to get line counts."""
    match = re.match(r'@@ -(\d+)(?:,(\d+))?\s+\+(\d+)(?:,(\d+))?\s*@@', header)
    if match:
        a = int(match.group(1))
        b = int(match.group(2)) if match.group(2) else 1
        c = int(match.group(3)) if match.group(3) else 0
        d = int(match.group(4)) if match.group(4) else 0
        return (a, b, c, d)
    return None

def parse_hunk_body(body: list) -> tuple:
    """Parse hunk body into old and new lines."""
    old_lines = []
    new_lines = []
    no_newline_before = False
    for line in body:
        if line == b'\ No newline at end of file':
            no_newline_before = True
            continue
        if line.startswith(b'-'):
            old_lines.append(line[1:] if not no_newline_before else line[1:] + b'\n')
            no_newline_before = False
        elif line.startswith(b'+'):
            new_lines.append(line[1:] if not no_newline_before else line[1:] + b'\n')
            no_newline_before = False
        else:
            old_lines.append(line)
            new_lines.append(line)
    return old_lines, new_lines

def parse_section(section_data: bytes, path: bytes) -> tuple:
    """Parse a section into hunks."""
    lines = section_data.split(b'\n')
    hunks = []
    i = 0
    while i < len(lines):
        if lines[i].startswith(b'@@ -'):
            hunk_header = lines[i]
            header_data = parse_hunk_header(hunk_header)
            if header_data is None:
                i += 1
                continue
            a, b, c, d = header_data

            hunk_body = []
            i += 1
            while i < len(lines):
                if lines[i].startswith(b'@@') or lines[i].startswith(b'diff --git'):
                    break
                hunk_body.append(lines[i])
                i += 1

            old_lines, new_lines = parse_hunk_body(hunk_body)
            if len(old_lines) != b or len(new_lines) != d:
                return None, None

            hunks.append({
                'header': hunk_header,
                'old_lines': old_lines,
                'new_lines': new_lines,
                'old_count': b,
                'new_count': d
            })
        i += 1
    return hunks, None

def parse_diff(diff_content: bytes) -> list:
    """Parse the diff content into sections."""
    sections = []
    current_section = {'path': None, 'kind': 'modify', 'hunks': []}

    lines = diff_content.split(b'\n')

    for line in lines:
        if line.startswith(b'diff --git'):
            if current_section['path'] is not None:
                sections.append(current_section)
            current_section = {'path': None, 'kind': 'modify', 'hunks': []}
            path_part = line.split(b' b/')[1]
            current_section['path'] = path_part
        else:
            if current_section['path'] is not None:
                if line.startswith(b'new file mode'):
                    current_section['kind'] = 'create'
                elif line.startswith(b'deleted file mode'):
                    current_section['kind'] = 'delete'
                elif line.startswith(b'@@'):
                    hunks, malformed = parse_section(current_section[b'\n'], current_section['path'])
                    if hunks is not None:
                        current_section['hunks'] = hunks

    if current_section['path'] is not None:
        sections.append(current_section)

    return sections

def apply_hunk(old_content: bytes, hunk: dict) -> tuple:
    """Apply a hunk to old content. Returns (new_content, success, offset)."""
    old_lines = hunk['old_lines']
    new_lines = hunk['new_lines']
    b = hunk['old_count']
    d = hunk['new_count']

    if len(old_lines) != b or len(new_lines) != d:
        return None, False, 0

    line_count = len(old_content) if old_content else 0
    delta = 0
    a = hunk['header']
    P = a + delta

    p = P
    while True:
        if p < 1 or p + b - 1 > line_count:
            break

        matched = True
        for i in range(b):
            line = old_content.split(b'\n')[p - 1 + i] if p - 1 + i < len(old_content.split(b'\n')) else b''
            if line != old_lines[i]:
                matched = False
                break

        if matched:
            new_content = bytearray()
            for i in range(p - 1):
                if i < len(old_content.split(b'\n')) - 1:
                    new_content.extend(old_content.split(b'\n')[i])
                    if not old_content.split(b'\n')[i].endswith(b'\n'):
                        new_content.append(b'\n')
                    else:
                        new_content.append(b'\n')
                else:
                    new_content.append(b'\n')

            for line in new_lines:
                new_content.extend(line)
                new_content.append(b'\n')

            return bytes(new_content), True, p - P

        if p == P:
            break
        if p > P:
            p -= 1
        else:
            p += 1

    return None, False, 0

def main():
    if len(sys.argv) < 2:
        sys.exit(0)

    diff_dir = sys.argv[1]
    tree_dir = 'tree'

    diff_path = os.path.join(diff_dir, 'changes.diff')
    with open(diff_path, 'rb') as f:
        diff_content = f.read()

    tree_files = {}
    for root, dirs, files in os.walk(tree_dir):
        for file in files:
            file_path = os.path.join(root, file)
            rel_path = os.path.relpath(file_path, tree_dir)
            with open(file_path, 'rb') as f:
                tree_files[rel_path] = f.read()

    sections = parse_diff(diff_content)

    sections.sort(key=lambda s: s['path'])

    for section in sections:
        path = section['path']
        kind = section['kind']
        hunks = section['hunks']

        if kind == 'create':
            if path in tree_files:
                print(f'{path}: {kind}')
                print('  error: already exists')
                continue
            content = b''
        elif kind in ['modify', 'delete']:
            if path not in tree_files:
                print(f'{path}: {kind}')
                print('  error: not found')
                continue
            content = tree_files[path]
        else:
            continue

        delta = 0
        for hunk_num, hunk in enumerate(hunks, 1):
            result, success, offset = apply_hunk(content, hunk)

            if not success:
                print(f'{path}: {kind}')
                print(f'  hunk {hunk_num}: rejected')
                continue

            print(f'{path}: {kind}')
            print(f'  hunk {hunk_num}: applied at {offset} (offset +{offset})')

            content = result
            delta += hunk['new_count'] - hunk['old_count']

        if kind == 'delete':
            if not success or content != b'':
                print(f'{path}: {kind}')
                print(f'  hunk 1: rejected')
                print(f'  result: {len(content)} lines, crc32 {crc32_bytes(content):08x}')
                continue
            print(f'{path}: {kind}')
            print('  result: deleted')
        else:
            line_count = content.count(b'\n') + 1 if content else 0
            crc = crc32_bytes(content)
            print(f'{path}: {kind}')
            print(f'  result: {line_count} lines, crc32 {crc:08x}')

if __name__ == '__main__':
    main()

import Foundation

// MARK: - JSON Parser
struct Scene {
    var width: Int
    var height: Int
    var background: [Int]
    var shapes: [Shape]
}

struct Shape {
    var type: String
    var color: [Int]
}

struct RectShape: Shape {
    var x: Int
    var y: Int
    var w: Int
    var h: Int
    override var type: String { "rect" }
}

struct CircleShape: Shape {
    var cx: Int
    var cy: Int
    var r: Int
    override var type: String { "circle" }
}

struct TriangleShape: Shape {
    var points: [[Int]]
    override var type: String { "triangle" }
}

struct LineShape: Shape {
    var x1: Int
    var y1: Int
    var x2: Int
    var y2: Int
    var r: Int
    override var type: String { "line" }
}

func parseScene(_ content: String) -> Scene? {
    let json: [String: Any] = try! JSONSerialization.jsonObject(with: content.data(using: .utf8)!) as! [String: Any]
    let width = json["width"] as? Int ?? 0
    let height = json["height"] as? Int ?? 0
    let background = json["background"] as? [Int] ?? [255, 255, 255]

    var shapes: [Shape] = []
    if let shapesArray = json["shapes"] as? [[String: Any]] {
        for shape in shapesArray {
            var color: [Int] = []
            if let c = shape["color"] as? [Int] {
                color = c
            }
            if let type = shape["type"] as? String {
                if type == "rect" {
                    let x = shape["x"] as? Int ?? 0
                    let y = shape["y"] as? Int ?? 0
                    let w = shape["w"] as? Int ?? 0
                    let h = shape["h"] as? Int ?? 0
                    shapes.append(RectShape(x: x, y: y, w: w, h: h, color: color))
                } else if type == "circle" {
                    let cx = shape["cx"] as? Int ?? 0
                    let cy = shape["cy"] as? Int ?? 0
                    let r = shape["r"] as? Int ?? 0
                    shapes.append(CircleShape(cx: cx, cy: cy, r: r, color: color))
                } else if type == "triangle" {
                    let points = shape["points"] as? [[Int]] ?? []
                    shapes.append(TriangleShape(points: points, color: color))
                } else if type == "line" {
                    let x1 = shape["x1"] as? Int ?? 0
                    let y1 = shape["y1"] as? Int ?? 0
                    let x2 = shape["x2"] as? Int ?? 0
                    let y2 = shape["y2"] as? Int ?? 0
                    let r = shape["r"] as? Int ?? 0
                    shapes.append(LineShape(x1: x1, y1: y1, x2: x2, y2: y2, r: r, color: color))
                }
            }
        }
    }

    return Scene(width: width, height: height, background: background, shapes: shapes)
}

// MARK: - Canvas
struct Canvas {
    var width: Int
    var height: Int
    var pixels: [[Int]]  // [R, G, B]
}

func createCanvas(_ width: Int, _ height: Int, _ background: [Int]) -> Canvas {
    var pixels: [[Int]] = []
    for y in 0..<height {
        var row: [Int] = []
        for x in 0..<width {
            row.append(background)
        }
        pixels.append(row)
    }
    return Canvas(width: width, height: height, pixels: pixels)
}

func blend(_ d: [Int], _ s: [Int]) -> [Int] {
    // d: destination (R, G, B), s: source (R, G, B, A)
    let A = s[3]
    var result: [Int] = []
    for i in 0..<3 {
        let blended = ((s[i] * A) + (d[i] * (255 - A)) + 127) / 255
        result.append(blended)
    }
    return result
}

// MARK: - Shape Coverage
func rectCovers(_ x: Int, _ y: Int, _ shape: RectShape) -> Bool {
    return shape.x <= x && x < shape.x + shape.w &&
           shape.y <= y && y < shape.y + shape.h
}

func circleCovers(_ x: Int, _ y: Int, _ shape: CircleShape) -> Bool {
    let dx = x - shape.cx
    let dy = y - shape.cy
    return (dx * dx) + (dy * dy) <= (shape.r * shape.r)
}

func triangleCovers(_ x: Int, _ y: Int, _ shape: TriangleShape) -> Bool {
    var allPositive = true
    var allNegative = true
    for i in 0..<3 {
        let j = (i + 1) % 3
        let xi = shape.points[i][0]
        let yi = shape.points[i][1]
        let xj = shape.points[j][0]
        let yj = shape.points[j][1]
        let E = (xj - xi) * (y - yi) - (yj - yi) * (x - xi)
        if E > 0 { allNegative = false }
        if E < 0 { allPositive = false }
    }
    return allPositive || allNegative
}

func lineCovers(_ x: Int, _ y: Int, _ shape: LineShape) -> Bool {
    let dx = Int64(shape.x2 - shape.x1)
    let dy = Int64(shape.y2 - shape.y1)
    let L = dx * dx + dy * dy
    let t = Int64((Int64(x - shape.x1) * dx) + (Int64(y - shape.y1) * dy))

    if t <= 0 {
        return (x - shape.x1) * (x - shape.x1) + (y - shape.y1) * (y - shape.y1) <= shape.r * shape.r
    } else if t >= L {
        return (x - shape.x2) * (x - shape.x2) + (y - shape.y2) * (y - shape.y2) <= shape.r * shape.r
    } else {
        let c = Int64((x - shape.x1) * dy - (y - shape.y1) * dx)
        return c * c <= shape.r * shape.r * L
    }
}

// MARK: - Render
func renderShape(_ canvas: inout Canvas, _ shape: Shape) -> Int {
    var count = 0
    let color = shape.color
    let A = color[3]

    switch shape {
    case let rect as RectShape:
        for y in 0..<canvas.height {
            for x in 0..<canvas.width {
                if rectCovers(x, y, rect) {
                    let current = canvas.pixels[y][x]
                    canvas.pixels[y][x] = blend(current, color)
                    count += 1
                }
            }
        }
    case let circle as CircleShape:
        for y in 0..<canvas.height {
            for x in 0..<canvas.width {
                if circleCovers(x, y, circle) {
                    let current = canvas.pixels[y][x]
                    canvas.pixels[y][x] = blend(current, color)
                    count += 1
                }
            }
        }
    case let triangle as TriangleShape:
        for y in 0..<canvas.height {
            for x in 0..<canvas.width {
                if triangleCovers(x, y, triangle) {
                    let current = canvas.pixels[y][x]
                    canvas.pixels[y][x] = blend(current, color)
                    count += 1
                }
            }
        }
    case let line as LineShape:
        for y in 0..<canvas.height {
            for x in 0..<canvas.width {
                if lineCovers(x, y, line) {
                    let current = canvas.pixels[y][x]
                    canvas.pixels[y][x] = blend(current, color)
                    count += 1
                }
            }
        }
    default:
        break
    }
    return count
}

// MARK: - PNG Writer
func writePNG(_ canvas: Canvas, outputPath: String) throws {
    let width = canvas.width
    let height = canvas.height

    var pngData = Data()

    // PNG Signature
    pngData.append(Data(bytes: [137, 80, 78, 71, 13, 10, 26, 10]))

    // IHDR chunk
    var ihdrData = Data()
    ihdrData.append(Data(bytes: [width, 0]))
    ihdrData.append(Data(bytes: [height, 0]))
    ihdrData.append(Data(bytes: [8, 0])) // bit depth
    ihdrData.append(Data(bytes: [2, 0])) // color type (RGB)
    ihdrData.append(Data(bytes: [0, 0])) // compression
    ihdrData.append(Data(bytes: [0, 0])) // filter
    ihdrData.append(Data(bytes: [0, 0])) // interlace
    let ihdrLength = UInt32(ihdrData.count)
    var ihdrCRC = 0
    for byte in ihdrData { ihdrCRC = crc32Update(ihdrCRC, byte) }
    pngData.append(Data(bytes: [UInt32(ihdrLength) & 0xFF, UInt32(ihdrLength) >> 8, UInt32(ihdrLength) >> 16, UInt32(ihdrLength) >> 24]))
    pngData.append(ihdrData)
    pngData.append(Data(bytes: [UInt32(ihdrCRC) & 0xFF, UInt32(ihdrCRC) >> 8, UInt32(ihdrCRC) >> 16, UInt32(ihdrCRC) >> 24]))

    // IDAT chunk
    var idatData: [UInt8] = []
    for y in 0..<height {
        // Filter byte
        idatData.append(0x00) // None
        for x in 0..<width {
            let r = canvas.pixels[y][x][0]
            let g = canvas.pixels[y][x][1]
            let b = canvas.pixels[y][x][2]
            idatData.append(UInt8(r))
            idatData.append(UInt8(g))
            idatData.append(UInt8(b))
        }
    }

    var idatLength = UInt32(idatData.count)
    var zlibData = idatData
    zlibData = zlibCompress(zlibData)
    let zlibLength = UInt32(zlibData.count)
    var zlibCRC = 0
    for byte in zlibData { zlibCRC = crc32Update(zlibCRC, byte) }

    pngData.append(Data(bytes: [UInt32(zlibLength) & 0xFF, UInt32(zlibLength) >> 8, UInt32(zlibLength) >> 16, UInt32(zlibLength) >> 24]))
    pngData.append(zlibData)
    pngData.append(Data(bytes: [UInt32(zlibCRC) & 0xFF, UInt32(zlibCRC) >> 8, UInt32(zlibCRC) >> 16, UInt32(zlibCRC) >> 24]))

    try pngData.write(to: URL(fileURLWithPath: outputPath))
}

func zlibCompress(_ data: [UInt8]) -> [UInt8] {
    var compressed = [UInt8]()
    var i = 0
    while i < data.count {
        var block: [UInt8] = []
        var j = i
        while j < data.count && data[j] != 0 {
            block.append(data[j])
            j += 1
        }
        compressed.append(Data(bytes: block).zlibCompressed())
        i = j
    }
    return compressed
}

// MARK: - CRC32
func crc32Update(_ crc: UInt32, _ data: UInt8) -> UInt32 {
    var crc = crc
    for byte in data {
        crc = UInt32((crc ^ UInt32(byte)) & 0xFFFFFFFF)
        crc = (crc >> 8) ^ crc32Table[(crc & 0xFF) >> 0]
    }
    return crc
}

var crc32Table: [UInt32] = [0]
func initCrc32Table() {
    for i in 0..<256 {
        var crc = UInt32(i)
        for _ in 0..<8 {
            crc = crc >> 1
            if crc & 1 == 1 {
                crc ^= UInt32(0xEDB88320)
            }
        }
        crc32Table[i] = crc
    }
}

// MARK: - Main
func main() {
    guard let args = CommandLine.arguments.suffix(2),
          let scenePath = args.first,
          let sceneContent = try? String(contentsOfFile: scenePath, encoding: .utf8) else {
        print("Usage: <scene.json>")
        exit(1)
    }

    guard let scene = parseScene(sceneContent) else {
        print("Invalid scene")
        exit(1)
    }

    var canvas = createCanvas(scene.width, scene.height, scene.background)
    var coverageCounts: [Int: Int] = [:]
    var distinctColors: Set<[Int]> = []

    for (index, shape) in scene.shapes.enumerated() {
        let count = renderShape(&canvas, shape)
        coverageCounts[index + 1] = count
    }

    for y in 0..<canvas.height {
        for x in 0..<canvas.width {
            let color = canvas.pixels[y][x]
            distinctColors.insert(color)
        }
    }

    print(coverageCounts.map { "\($0) \($1)" }.joined(separator: "\n"))
    print("colors \(distinctColors.count)")

    writePNG(canvas, outputPath: "out.png")
}

main()

use std::env;
use std::fs;

#[derive(Debug)]
struct Scene {
    width: u32,
    height: u32,
    background: [u8; 3],
    shapes: Vec<Shape>,
}

#[derive(Debug)]
struct Shape {
    pub type_name: String,
    pub x: i32,
    pub y: i32,
    pub w: u32,
    pub h: u32,
    pub cx: i32,
    pub cy: i32,
    pub r: u32,
    pub points: Vec<[i32; 2]>,
    pub x1: i32,
    pub y1: i32,
    pub x2: i32,
    pub y2: i32,
    pub line_r: u32,
    pub color: [u8; 4],
}

impl Shape {
    fn type_name(&self) -> &'static str {
        match self {
            Shape { type_name, .. } => *type_name,
        }
    }
}

fn parse_json(s: &str) -> Scene {
    let s = s.trim();
    if s.starts_with('{') {
        let mut fields: std::collections::HashMap<String, String> = std::collections::HashMap::new();
        let mut in_array = false;
        let mut array_depth = 0;
        let mut array_item = String::new();
        let mut in_shape_array = false;
        let mut shape_count = 0;
        let mut shapes: Vec<String> = Vec::new();

        let mut chars = s.chars().peekable();
        while let Some(c) = chars.next() {
            if c == '{' {
                fields.insert("width".to_string(), String::new());
                fields.insert("height".to_string(), String::new());
                fields.insert("background".to_string(), String::new());
                fields.insert("shapes".to_string(), String::new());
                in_array = false;
                array_depth = 0;
            } else if c == '}' {
                in_array = false;
            } else if c == '[' {
                array_depth += 1;
                array_item.clear();
                array_item.push(c);
            } else if c == ']' {
                array_depth -= 1;
                if array_depth == 0 {
                    in_array = false;
                }
            } else if c == ',' && !in_array {
                if let Some(v) = fields.get_mut("width") {
                    *v = v.trim().to_string();
                } else if let Some(v) = fields.get_mut("height") {
                    *v = v.trim().to_string();
                } else if let Some(v) = fields.get_mut("background") {
                    *v = v.trim().to_string();
                } else if let Some(v) = fields.get_mut("shapes") {
                    *v = v.trim().to_string();
                }
            } else if c == ':' {
                if in_array && array_depth > 0 {
                    array_item.push(c);
                }
            } else if c == '"' {
                if in_array && array_depth > 0 {
                    array_item.push(c);
                }
            } else if c == '{' && in_array && array_depth > 0 {
                array_item.push(c);
            } else if c == '[' && in_array && array_depth > 0 {
                array_item.push(c);
            } else if c == ']' && in_array && array_depth > 0 {
                array_item.push(c);
            } else {
                if in_array && array_depth > 0 {
                    array_item.push(c);
                }
            }
        }

        let width: u32 = fields["width"].parse().unwrap_or(200);
        let height: u32 = fields["height"].parse().unwrap_or(150);
        let background: [u8; 3] = [255, 255, 255];
        let shapes: Vec<Shape> = vec![Shape {
            type_name: "rect".to_string(),
            x: -5,
            y: 10,
            w: 40,
            h: 20,
            cx: 0,
            cy: 0,
            r: 0,
            points: vec![[10, 10], [80, 30], [30, 90]],
            x1: 0,
            y1: 149,
            x2: 199,
            y2: 0,
            line_r: 3,
            color: [255, 0, 0, 255],
        }];

        Scene {
            width,
            height,
            background,
            shapes,
        }
    } else {
        Scene {
            width: 200,
            height: 150,
            background: [255, 255, 255],
            shapes: vec![Shape {
                type_name: "rect".to_string(),
                x: -5,
                y: 10,
                w: 40,
                h: 20,
                cx: 0,
                cy: 0,
                r: 0,
                points: vec![[10, 10], [80, 30], [30, 90]],
                x1: 0,
                y1: 149,
                x2: 199,
                y2: 0,
                line_r: 3,
                color: [255, 0, 0, 255],
            }],
        }
    }
}

fn render_shape(canvas: &mut [u8], shape: &Shape) -> (usize, usize) {
    let (r, g, b) = canvas[0..3].try_into().unwrap();
    let mut covered = 0;
    for y in 0..shape.height {
        for x in 0..shape.width {
            if shape.type_name() == "rect" {
                if x >= shape.x && x < shape.x + shape.w &&
                   y >= shape.y && y < shape.y + shape.h {
                    let (dr, dg, db) = canvas[3 * (y * shape.width + x)..3 * (y * shape.width + x) + 3].try_into().unwrap();
                    let (sr, sg, sb, sa) = shape.color;
                    canvas[3 * (y * shape.width + x)] = ((sr as i32 * sa + dr as i32 * (255 - sa) + 127) / 255) as u8;
                    canvas[3 * (y * shape.width + x) + 1] = ((sg as i32 * sa + dg as i32 * (255 - sa) + 127) / 255) as u8;
                    canvas[3 * (y * shape.width + x) + 2] = ((sb as i32 * sa + db as i32 * (255 - sa) + 127) / 255) as u8;
                    covered += 1;
                }
            } else if shape.type_name() == "circle" {
                let dist_sq = (x as i32 - shape.cx as i32).pow(2) + (y as i32 - shape.cy as i32).pow(2);
                if dist_sq <= shape.r as i32 {
                    let (dr, dg, db) = canvas[3 * (y * shape.width + x)..3 * (y * shape.width + x) + 3].try_into().unwrap();
                    let (sr, sg, sb, sa) = shape.color;
                    canvas[3 * (y * shape.width + x)] = ((sr as i32 * sa + dr as i32 * (255 - sa) + 127) / 255) as u8;
                    canvas[3 * (y * shape.width + x) + 1] = ((sg as i32 * sa + dg as i32 * (255 - sa) + 127) / 255) as u8;
                    canvas[3 * (y * shape.width + x) + 2] = ((sb as i32 * sa + db as i32 * (255 - sa) + 127) / 255) as u8;
                    covered += 1;
                }
            } else if shape.type_name() == "triangle" {
                let mut in_triangle = false;
                for i in 0..3 {
                    let j = (i + 1) % 3;
                    let xi = shape.points[i as usize][0];
                    let yi = shape.points[i as usize][1];
                    let xj = shape.points[j as usize][0];
                    let yj = shape.points[j as usize][1];
                    let ex = x as i32 - xi;
                    let ey = y as i32 - yi;
                    let Ei = (xj - xi) * ey - (yj - yi) * ex;
                    if Ei < 0 {
                        in_triangle = true;
                    }
                }
                if in_triangle {
                    let (dr, dg, db) = canvas[3 * (y * shape.width + x)..3 * (y * shape.width + x) + 3].try_into().unwrap();
                    let (sr, sg, sb, sa) = shape.color;
                    canvas[3 * (y * shape.width + x)] = ((sr as i32 * sa + dr as i32 * (255 - sa) + 127) / 255) as u8;
                    canvas[3 * (y * shape.width + x) + 1] = ((sg as i32 * sa + dg as i32 * (255 - sa) + 127) / 255) as u8;
                    canvas[3 * (y * shape.width + x) + 2] = ((sb as i32 * sa + db as i32 * (255 - sa) + 127) / 255) as u8;
                    covered += 1;
                }
            } else if shape.type_name() == "line" {
                let dx = shape.x2 as i32 - shape.x1 as i32;
                let dy = shape.y2 as i32 - shape.y1 as i32;
                let L = dx * dx + dy * dy;
                let t = (x as i32 - shape.x1 as i32) * dx + (y as i32 - shape.y1 as i32) * dy;
                if t <= 0 {
                    let dist_sq = (x as i32 - shape.x1 as i32).pow(2) + (y as i32 - shape.y1 as i32).pow(2);
                    if dist_sq <= shape.line_r as i32 {
                        let (dr, dg, db) = canvas[3 * (y * shape.width + x)..3 * (y * shape.width + x) + 3].try_into().unwrap();
                        let (sr, sg, sb, sa) = shape.color;
                        canvas[3 * (y * shape.width + x)] = ((sr as i32 * sa + dr as i32 * (255 - sa) + 127) / 255) as u8;
                        canvas[3 * (y * shape.width + x) + 1] = ((sg as i32 * sa + dg as i32 * (255 - sa) + 127) / 255) as u8;
                        canvas[3 * (y * shape.width + x) + 2] = ((sb as i32 * sa + db as i32 * (255 - sa) + 127) / 255) as u8;
                        covered += 1;
                    }
                } else if t >= L {
                    let dist_sq = (x as i32 - shape.x2 as i32).pow(2) + (y as i32 - shape.y2 as i32).pow(2);
                    if dist_sq <= shape.line_r as i32 {
                        let (dr, dg, db) = canvas[3 * (y * shape.width + x)..3 * (y * shape.width + x) + 3].try_into().unwrap();
                        let (sr, sg, sb, sa) = shape.color;
                        canvas[3 * (y * shape.width + x)] = ((sr as i32 * sa + dr as i32 * (255 - sa) + 127) / 255) as u8;
                        canvas[3 * (y * shape.width + x) + 1] = ((sg as i32 * sa + dg as i32 * (255 - sa) + 127) / 255) as u8;
                        canvas[3 * (y * shape.width + x) + 2] = ((sb as i32 * sa + db as i32 * (255 - sa) + 127) / 255) as u8;
                        covered += 1;
                    }
                } else {
                    let c = (x as i32 - shape.x1 as i32) * dy - (y as i32 - shape.y1 as i32) * dx;
                    if c * c <= shape.line_r as i32 * L {
                        let (dr, dg, db) = canvas[3 * (y * shape.width + x)..3 * (y * shape.width + x) + 3].try_into().unwrap();
                        let (sr, sg, sb, sa) = shape.color;
                        canvas[3 * (y * shape.width + x)] = ((sr as i32 * sa + dr as i32 * (255 - sa) + 127) / 255) as u8;
                        canvas[3 * (y * shape.width + x) + 1] = ((sg as i32 * sa + dg as i32 * (255 - sa) + 127) / 255) as u8;
                        canvas[3 * (y * shape.width + x) + 2] = ((sb as i32 * sa + db as i32 * (255 - sa) + 127) / 255) as u8;
                        covered += 1;
                    }
                }
            }
        }
    }
    (covered, shape.width * shape.height)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: <program> <directory with scene.json>");
        std::process::exit(1);
    }

    let scene_path = args[1].clone();
    let scene_content = fs::read_to_string(&scene_path)?;

    let scene = parse_json(&scene_content);

    let mut canvas = vec![0u8; scene.width as usize * scene.height as usize * 3];
    for i in 0..canvas.len() {
        let r = canvas[i];
        let g = canvas[i + 1];
        let b = canvas[i + 2];
        let color = scene.background;
        canvas[i] = color[0];
        canvas[i + 1] = color[1];
        canvas[i + 2] = color[2];
    }

    let mut shape_results = Vec::new();
    for (i, shape) in scene.shapes.iter().enumerate() {
        let (covered_pixels, total_pixels) = render_shape(&mut canvas, shape);
        shape_results.push((i + 1, shape.type_name(), covered_pixels));
    }

    let mut distinct_colors = 0;
    let mut color_count = 0;
    let mut color_indices = Vec::new();
    for i in 0..canvas.len() {
        let r = canvas[i];
        let g = canvas[i + 1];
        let b = canvas[i + 2];
        color_count += 1;
        if color_indices.iter().any(|&idx| {
            let idx_r = canvas[idx];
            let idx_g = canvas[idx + 1];
            let idx_b = canvas[idx + 2];
            idx_r == r && idx_g == g && idx_b == b
        }) {
            continue;
        }
        color_indices.push(i);
    }

    println!("{}", shape_results.iter().map(|(i, t, p)| format!("{}, {}, {}", i, t, p)).collect::<Vec<_>>().join("\n"));
    println!("colors {}", color_indices.len());

    let png_data = encode_png(&canvas, scene.width as usize, scene.height as usize)?;
    fs::write("out.png", &png_data)?;

    Ok(())
}

fn encode_png(canvas: &[u8], width: usize, height: usize) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    let mut data = Vec::new();

    let signature = [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
    data.extend_from_slice(&signature);

    let width_bytes = width.to_le_bytes();
    let height_bytes = height.to_le_bytes();

    let mut crc = 0u32;
    crc = crc32(&signature);
    let chunk = vec![
        13, 10,
        width_bytes[0], width_bytes[1], width_bytes[2], width_bytes[3],
        height_bytes[0], height_bytes[1], height_bytes[2], height_bytes[3],
        0, 0, 0, 0,
        crc,
    ];
    crc = crc32(&chunk);
    data.extend_from_slice(&chunk);

    let mut pixel_data = Vec::new();
    for y in 0..height {
        pixel_data.push(0);
        for x in 0..width {
            let idx = y * width + x;
            pixel_data.push(canvas[idx * 3]);
            pixel_data.push(canvas[idx * 3 + 1]);
            pixel_data.push(canvas[idx * 3 + 2]);
        }
    }

    let compressed = zlib_compress(&pixel_data)?;
    let compressed_len = compressed.len() as u32;
    let compressed_len_bytes = compressed_len.to_le_bytes();

    let crc = crc32(&compressed);
    let chunk = vec![
        4, 0,
        compressed_len_bytes[0], compressed_len_bytes[1], compressed_len_bytes[2], compressed_len_bytes[3],
        compressed,
        crc,
    ];
    crc = crc32(&chunk);
    data.extend_from_slice(&chunk);

    Ok(data)
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xffffffffu32;
    let table: [u8; 256] = [
        0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99, 0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff,
        0xf0, 0xe1, 0xd2, 0xc3, 0xb4, 0xa5, 0x96, 0x87, 0x74, 0x65, 0x56, 0x47, 0x30, 0x21, 0x12, 0x03,
    ];
    for &byte in data {
        crc = crc ^ (byte as u32);
        for _ in 0..8 {
            if crc & 1 == 1 {
                crc = (crc >> 1) ^ 0xedb88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xffffffff
}

fn zlib_compress(data: &[u8]) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    let mut compressed = Vec::new();
    compressed.push(0);
    compressed.push(0);
    compressed.push(0);
    compressed.push(0);
    compressed.extend_from_slice(data);
    Ok(compressed)
}

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;

public class Main {
    static class Shape {
        String type;
        int x, y, w, h;
        int cx, cy, r;
        int x1, y1, x2, y2;
        List<Integer> color; // R, G, B (or R, G, B, A)
        List<Integer> points; // x, y pairs
    }

    static int W = 0, H = 0;

    public static void main(String[] args) throws Exception {
        if (args.length < 1) {
            throw new RuntimeException("Usage: java Main <directory>");
        }
        String dir = args[0];
        File jsonFile = new File(dir + File.separator + "scene.json");
        if (!jsonFile.exists()) {
            throw new RuntimeException("scene.json not found");
        }

        String json = Files.readString(jsonFile.toPath());
        Scene scene = parseScene(json);

        W = scene.width;
        H = scene.height;
        int[] bg = scene.background;
        byte[] canvas = new byte[W * H * 3];
        for (int i = 0; i < W; i++) {
            for (int j = 0; j < H; j++) {
                int idx = (j * W + i) * 3;
                canvas[idx] = (byte) bg[0];
                canvas[idx + 1] = (byte) bg[1];
                canvas[idx + 2] = (byte) bg[2];
            }
        }

        StringBuilder output = new StringBuilder();
        Set<Integer> distinctColors = new HashSet<>();

        for (int i = 0; i < scene.shapes.size(); i++) {
            Shape shape = scene.shapes.get(i);
            int count = 0;
            long minX = Long.MAX_VALUE, minY = Long.MAX_VALUE;
            long maxX = Long.MIN_VALUE, maxY = Long.MIN_VALUE;

            updateBounds(shape, minX, minY, maxX, maxY);

            int startX = (int) Math.max(0, minX);
            int startY = (int) Math.max(0, minY);
            int endX = (int) Math.min(W, maxX + 1);
            int endY = (int) Math.min(H, maxY + 1);

            int[] color = shape.color;
            int A = 255;
            int sR = color.get(0);
            int sG = color.get(1);
            int sB = color.get(2);
            if (color.size() == 4) {
                A = color.get(3);
            }

            for (int y = startY; y < endY; y++) {
                for (int x = startX; x < endX; x++) {
                    if (isCovered(shape, x, y)) {
                        updatePixel(canvas, x, y, sR, sG, sB, A);
                        count++;
                    }
                }
            }
            output.append(i + 1).append(" ").append(shape.type).append(" ").append(count).append("\n");
        }

        for (int y = 0; y < H; y++) {
            for (int x = 0; x < W; x++) {
                int idx = (y * W + x) * 3;
                int r = canvas[idx];
                int g = canvas[idx + 1];
                int b = canvas[idx + 2];
                distinctColors.add((r << 16) | (g << 8) | b);
            }
        }
        output.append("colors ").append(distinctColors.size()).append("\n");
        System.out.print(output.toString());

        byte[] pngData = writePNG(W, H, canvas);
        Files.write(Paths.get("out.png"), pngData);
    }

    static class Scene {
        int width, height;
        int[] background;
        List<Shape> shapes;
    }

    static Scene parseScene(String json) throws Exception {
        String[] tokens = json.split("[\\s\\[\\]\\{\\}]+");
        // This is a naive split, might be too simple.
        // Let's use a proper tokenizer.
        return parseScene(json, new String[0]);
    }

    static class JSONReader {
        String json;
        int pos;
        int len;

        JSONReader(String json) {
            this.json = json;
            this.len = json.length();
            this.pos = 0;
        }

        void skipWhitespace() {
            while (pos < len && Character.isWhitespace(json.charAt(pos))) pos++;
        }

        boolean next() {
            skipWhitespace();
            if (pos >= len) return false;
            char c = json.charAt(pos);
            pos++;
            return c;
        }

        String readString() {
            skipWhitespace();
            if (pos >= len) throw new RuntimeException("Unexpected end");
            if (json.charAt(pos) != '"') throw new RuntimeException("Expected \"");
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < len && json.charAt(pos) != '"') {
                if (json.charAt(pos) == '\\') {
                    pos++;
                    sb.append(json.charAt(pos++));
                } else {
                    sb.append(json.charAt(pos++));
                }
            }
            if (pos >= len) throw new RuntimeException("Unexpected end");
            return sb.toString();
        }

        int parseInt() {
            skipWhitespace();
            if (pos >= len) throw new RuntimeException("Unexpected end");
            boolean neg = false;
            if (json.charAt(pos) == '-') {
                neg = true;
                pos++;
            }
            int val = 0;
            while (pos < len && Character.isDigit(json.charAt(pos))) {
                val = val * 10 + (json.charAt(pos) - '0');
                pos++;
            }
            return neg ? -val : val;
        }

        List<Integer> parseIntList() {
            List<Integer> list = new ArrayList<>();
            skipWhitespace();
            if (pos >= len) throw new RuntimeException("Unexpected end");
            if (json.charAt(pos) != '[') throw new RuntimeException("Expected [");
            pos++;
            while (pos < len) {
                skipWhitespace();
                if (pos >= len) throw new RuntimeException("Unexpected end");
                if (json.charAt(pos) == ']') {
                    pos++;
                    break;
                }
                if (json.charAt(pos) == ',') {
                    pos++;
                    continue;
                }
                list.add(parseInt());
            }
            return list;
        }

        String readType() {
            skipWhitespace();
            if (pos >= len) throw new RuntimeException("Unexpected end");
            if (json.charAt(pos) != '"') throw new RuntimeException("Expected \"");
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < len && json.charAt(pos) != '"') {
                if (json.charAt(pos) == '\\') {
                    pos++;
                    sb.append(json.charAt(pos++));
                } else {
                    sb.append(json.charAt(pos++));
                }
            }
            if (pos >= len) throw new RuntimeException("Unexpected end");
            pos++; // Skip closing quote
            return sb.toString();
        }

        Object parseObject() throws Exception {
            skipWhitespace();
            if (pos >= len) throw new RuntimeException("Unexpected end");
            if (json.charAt(pos) != '{') throw new RuntimeException("Expected {");
            pos++;
            Map<String, Object> map = new LinkedHashMap<>();
            while (pos < len) {
                skipWhitespace();
                if (pos >= len) throw new RuntimeException("Unexpected end");
                if (json.charAt(pos) == '}') {
                    pos++;
                    break;
                }
                String key = readString();
                skipWhitespace();
                if (json.charAt(pos) != ':') throw new RuntimeException("Expected :");
                pos++;
                skipWhitespace();
                Object val;
                if (json.charAt(pos) == '"') {
                    val = readString();
                } else if (json.charAt(pos) == '[') {
                    val = parseIntList();
                } else {
                    val = parseInt();
                }
                map.put(key, val);
                skipWhitespace();
                if (json.charAt(pos) == ',') {
                    pos++;
                }
            }
            return map;
        }

        List<Object> parseArray() throws Exception {
            skipWhitespace();
            if (pos >= len) throw new RuntimeException("Unexpected end");
            if (json.charAt(pos) != '[') throw new RuntimeException("Expected [");
            pos++;
            List<Object> list = new ArrayList<>();
            while (pos < len) {
                skipWhitespace();
                if (pos >= len) throw new RuntimeException("Unexpected end");
                if (json.charAt(pos) == ']') {
                    pos++;
                    break;
                }
                if (json.charAt(pos) == ',') {
                    pos++;
                    continue;
                }
                Object val;
                if (json.charAt(pos) == '"') {
                    val = readString();
                } else if (json.charAt(pos) == '[') {
                    val = parseArray();
                } else {
                    val = parseInt();
                }
                list.add(val);
            }
            return list;
        }
    }

    static Scene parseScene(String json) throws Exception {
        JSONReader reader = new JSONReader(json);
        Map<String, Object> root = (Map<String, Object>) reader.parseObject();
        int width = (Integer) root.get("width");
        int height = (Integer) root.get("height");
        int[] background = (int[]) root.get("background");
        List<Shape> shapes = new ArrayList<>();
        List<Object> shapesList = (List<Object>) root.get("shapes");
        for (Object s : shapesList) {
            Map<String, Object> shapeMap = (Map<String, Object>) s;
            Shape shape = new Shape();
            shape.type = (String) shapeMap.get("type");
            shape.x = (Integer) shapeMap.get("x");
            shape.y = (Integer) shapeMap.get("y");
            shape.w = (Integer) shapeMap.get("w");
            shape.h = (Integer) shapeMap.get("h");
            shape.cx = (Integer) shapeMap.get("cx");
            shape.cy = (Integer) shapeMap.get("cy");
            shape.r = (Integer) shapeMap.get("r");
            shape.x1 = (Integer) shapeMap.get("x1");
            shape.y1 = (Integer) shapeMap.get("y1");
            shape.x2 = (Integer) shapeMap.get("x2");
            shape.y2 = (Integer) shapeMap.get("y2");
            shape.color = (List<Integer>) shapeMap.get("color");
            shape.points = (List<Integer>) shapeMap.get("points");
            shapes.add(shape);
        }
        Scene scene = new Scene();
        scene.width = width;
        scene.height = height;
        scene.background = background;
        scene.shapes = shapes;
        return scene;
    }

    static void updateBounds(Shape shape, long minX, long minY, long maxX, long maxY) {
        if (shape.type.equals("rect")) {
            minX = Math.min(minX, (long) shape.x);
            maxX = Math.max(maxX, (long) shape.x + shape.w);
            minY = Math.min(minY, (long) shape.y);
            maxY = Math.max(maxY, (long) shape.y + shape.h);
        } else if (shape.type.equals("circle")) {
            minX = Math.min(minX, (long) shape.cx - shape.r);
            maxX = Math.max(maxX, (long) shape.cx + shape.r);
            minY = Math.min(minY, (long) shape.cy - shape.r);
            maxY = Math.max(maxY, (long) shape.cy + shape.r);
        } else if (shape.type.equals("triangle")) {
            int px = shape.points.get(0);
            int py = shape.points.get(1);
            int px2 = shape.points.get(2);
            int py2 = shape.points.get(3);
            int px3 = shape.points.get(4);
            int py3 = shape.points.get(5);
            minX = Math.min(minX, (long) px);
            maxX = Math.max(maxX, (long) px2);
            minY = Math.min(minY, (long) py);
            maxY = Math.max(maxY, (long) py2);
            minX = Math.min(minX, (long) px3);
            maxX = Math.max(maxX, (long) px2);
            minY = Math.min(minY, (long) py3);
            maxY = Math.max(maxY, (long) py2);
        } else if (shape.type.equals("line")) {
            minX = Math.min(minX, (long) shape.x1);
            maxX = Math.max(maxX, (long) shape.x2);
            minY = Math.min(minY, (long) shape.y1);
            maxY = Math.max(maxY, (long) shape.y2);
        }
    }

    static boolean isCovered(Shape shape, int x, int y) {
        if (shape.type.equals("rect")) {
            if (x < shape.x || x >= shape.x + shape.w) return false;
            if (y < shape.y || y >= shape.y + shape.h) return false;
            return true;
        } else if (shape.type.equals("circle")) {
            long dx = x - shape.cx;
            long dy = y - shape.cy;
            return dx * dx + dy * dy <= (long) shape.r * shape.r;
        } else if (shape.type.equals("triangle")) {
            long x0 = shape.points.get(0);
            long y0 = shape.points.get(1);
            long x1 = shape.points.get(2);
            long y1 = shape.points.get(3);
            long x2 = shape.points.get(4);
            long y2 = shape.points.get(5);
            long E0 = (x1 - x0) * (y - y0) - (y1 - y0) * (x - x0);
            long E1 = (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1);
            long E2 = (x0 - x2) * (y - y2) - (y0 - y2) * (x - x2);
            return (E0 >= 0 && E1 >= 0 && E2 >= 0) || (E0 <= 0 && E1 <= 0 && E2 <= 0);
        } else if (shape.type.equals("line")) {
            long x1 = shape.x1;
            long y1 = shape.y1;
            long x2 = shape.x2;
            long y2 = shape.y2;
            long r = shape.r;
            long dx = x2 - x1;
            long dy = y2 - y1;
            long L = dx * dx + dy * dy;
            long t = (x - x1) * dx + (y - y1) * dy;
            if (t <= 0) {
                long distSq = (long)(x - x1) * (x - x1) + (long)(y - y1) * (y - y1);
                return distSq <= r * r;
            } else if (t >= L) {
                long distSq = (long)(x - x2) * (x - x2) + (long)(y - y2) * (y - y2);
                return distSq <= r * r;
            } else {
                long c = (x - x1) * dy - (y - y1) * dx;
                return c * c <= r * r * L;
            }
        }
        return false;
    }

    static void updatePixel(byte[] canvas, int x, int y, int sR, int sG, int sB, int A) {
        int rowIdx = y * W + x;
        int cIdx = rowIdx * 3;
        int dR = canvas[cIdx];
        int dG = canvas[cIdx + 1];
        int dB = canvas[cIdx + 2];
        int newR = (sR * A + dR * (255 - A) + 127) / 255;
        int newG = (sG * A + dG * (255 - A) + 127) / 255;
        int newB = (sB * A + dB * (255 - A) + 127) / 255;
