fn parse_png(data: &[u8]) -> Result<(PngData, Vec<String>), String> {
    let signature = b"\x89PNG\r\n\x1a\n";
    if &data[..8] != signature {
        return Err("Invalid PNG signature".to_string());
    }

    let mut pos = 8;
    let mut chunks = Vec::new();
    let mut chunk_types: Vec<String> = Vec::new();

    while pos + 8 <= data.len() {
        let length = u32::from_le_bytes([
            data[pos] as u32,
            data[pos + 1] as u32,
            data[pos + 2] as u32,
            data[pos + 3] as u32,
        ]);

        let chunk_type = &data[pos + 4..pos + 8];
        let chunk_data = &data[pos + 8..pos + 8 + length as usize];

        let expected_crc = crc32(chunk_type) ^ crc32(chunk_data);
        let actual_crc = crc32(chunk_type) ^ crc32(chunk_data);

        if expected_crc != actual_crc {
            return Err(format!("CRC mismatch in chunk {} {:?}", length, chunk_type));
        }

        chunks.push((chunk_type, chunk_data));
        pos += 8 + length as usize;
    }

    let mut ihdr = None;
    let mut plte = None;
    let mut trns = None;
    let mut idat_chunks: Vec<Vec<u8>> = Vec::new();

    for (chunk_type, chunk_data) in &chunks {
        match chunk_type {
            b"IHDR" => {
                let width = u32::from_le_bytes([
                    chunk_data[0],
                    chunk_data[1],
                    chunk_data[2],
                    chunk_data[3],
                ]);
                let height = u32::from_le_bytes([
                    chunk_data[4],
                    chunk_data[5],
                    chunk_data[6],
                    chunk_data[7],
                ]);
                let bit_depth = chunk_data[8];
                let color_type = chunk_data[9];

                Ok((PngData {
                    width,
                    height,
                    bit_depth,
                    color_type,
                    has_trns: chunk_type == b"tRNS",
                    trns_data: chunk_data.to_vec(),
                    idat_chunks,
                    plte_data: chunk_data.to_vec(),
                }, chunk_types))
            }
            _ => {
                Ok((PngData {
                    width: 0,
                    height: 0,
                    bit_depth: 0,
                    color_type: 0,
                    has_trns: false,
                    trns_data: vec![],
                    idat_chunks,
                    plte_data: vec![],
                }, chunk_types))
            }
        }
    }
}

