                        acc | ((b as u32) << (7 - (b as u32) & 7))
                    });
                }
                6 => {
                    sample = data[scanline_idx + 1..scanline_idx + 5].iter().fold(0u32, |acc, b| acc | ((b as u32) << (7 - (b as u32) & 7)));
                }
                _ => return Err("Unsupported color type".to_string()),
            }

