import * as fs from 'fs';

type Position = number;

interface Quantifier {
  type: '*' | '+' | '?' | '{m}' | '{m,}' | '{m,n}';
  lazy?: boolean;
}

interface PatternNode {
  type: 'literal' | '.' | '^' | '$' | 'class' | 'escape' | 'anchor' | 'group' | 'alt';
  value?: string;
  children?: PatternNode[];
  quantifier?: Quantifier;
  groupNum?: number;
}

interface CaptureGroup {
  start: Position;
  end: Position;
  set: boolean;
}

interface MatchResult {
  start: Position;
  end: Position;
  groups: CaptureGroup[];
}

function parseQuantifier(s: string): Quantifier {
  if (s === '*') return { type: '*' };
  if (s === '+') return { type: '+' };
  if (s === '?') return { type: '?' };
  if (s === '{') {
    const parts = s.substring(1).split(',');
    const m = parseInt(parts[0], 10);
    let n: number | undefined;
    if (parts.length === 1) {
      n = m;
    } else if (parts.length === 2 && parts[1] === '}') {
      n = undefined;
    } else {
      n = parseInt(parts[1], 10);
    }
    return { type: `{${m}${n != null ? n : ''}}`, lazy: false };
  }
  return { type: '?' };
}

function parsePattern(s: string): PatternNode[] {
  const nodes: PatternNode[] = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '(') {
      const groupStart = i;
      i++;
      const groupContent: PatternNode[] = [];
      while (i < s.length && s[i] !== ')') {
        groupContent.push(...parsePattern(s.substring(i)));
        i += 1;
      }
      const groupNode: PatternNode = { type: 'group', children: groupContent };
      nodes.push(groupNode);
      i++;
    } else if (s[i] === '|') {
      const alt: PatternNode[] = [];
      while (i < s.length && s[i] !== '|') {
        alt.push(...parsePattern(s.substring(i)));
        i += 1;
      }
      const altNode: PatternNode = { type: 'alt', children: alt };
      nodes.push(altNode);
      i += 1;
    } else {
      const atom: PatternNode = { type: 'atom' };
      let atomStr = '';
      let j = i;
      while (j < s.length && s[j] !== ')') {
        atomStr += s[j];
        j++;
      }
      const quantifier = parseQuantifier(atomStr.substring(j).trim());
      const atomNode: PatternNode = { type: 'literal', value: atomStr.substring(0, j), quantifier };
      nodes.push(atomNode);
      i = j;
    }
  }
  return nodes;
}

function escapeChar(c: string): string {
  switch (c) {
    case '\\': return '\\\\';
    case '[': return '\\[';
    case ']': return '\\]';
    case '(': return '\\(';
    case ')': return '\\)';
    case '{': return '\\{';
    case '}': return '\\}';
    case '*': return '\\*';
    case '+': return '\\+';
    case '?': return '\\?';
    case '|': return '\\|';
    case '^': return '\\^';
    case '$': return '\\$';
    default: return c;
  }
}

function isClassEscape(c: string): boolean {
  return c === '\\d' || c === '\\w' || c === '\\s' || c === '\\D' || c === '\\W' || c === '\\S';
}

function parseClass(s: string): string[] {
  const items: string[] = [];
  let i = 1;
  while (i < s.length) {
    if (s[i] === '\\') {
      const escaped = s.substring(i, i + 2);
      items.push(escaped);
      i += 2;
    } else if (s[i] === '-' && i + 1 < s.length) {
      const range = s.substring(i, i + 2);
      const a = parseInt(range[0], 10);
      const b = parseInt(range[1], 10);
      for (let c = a; c <= b; c++) {
        items.push(String.fromCharCode(c));
      }
      i += 2;
    } else {
      items.push(s[i]);
      i++;
    }
  }
  return items;
}

function matchesChar(c: string, charSet: string[]): boolean {
  if (charSet.length === 0) return false;
  for (const cs of charSet) {
    if (cs === c) return true;
  }
  return false;
}

function matchesClass(c: string, items: string[]): boolean {
  for (const item of items) {
    if (item === c) return true;
  }
  return false;
}

function matchesAtom(atom: PatternNode, subject: string, start: Position, end: Position): boolean {
  if (atom.type === 'literal') {
    if (atom.quantifier) {
      const count = atom.quantifier.type === '*' ? 0 : atom.quantifier.type === '+' ? 1 : 1;
      for (let i = end; i < subject.length; i++) {
        if (i - end < count) {
          if (subject[i] !== atom.value) return false;
          end++;
        }
      }
      return true;
    }
    return subject[start] === atom.value;
  }
  return false;
}

function matchesGroup(group: PatternNode, subject: string, start: Position, end: Position, groups: CaptureGroup[]): boolean {
  if (group.type === 'alt') {
    for (const child of group.children) {
      if (matchesGroup(child, subject, start, end, groups)) return true;
    }
    return false;
  }
  if (group.type === 'group') {
    return matchesGroup(group, subject, start, end, groups);
  }
  return false;
}

function matchPattern(pattern: PatternNode[], subject: string, start: Position, groups: CaptureGroup[]): boolean {
  if (pattern.length === 0) return true;
  const first = pattern[0];
  const rest = pattern.slice(1);
  if (first.type === 'group') {
    return matchGroup(first, subject, start, end, groups);
  }
  return false;
}

function match(subject: string, pattern: PatternNode[]): MatchResult | null {
  const results: MatchResult[] = [];
  for (let i = 0; i < subject.length; i++) {
    const group: CaptureGroup[] = [];
    const matchResult = matchAt(subject, pattern, i, group);
    if (matchResult) {
      results.push(matchResult);
    }
  }
  return results.length > 0 ? results[0] : null;
}

function matchAt(subject: string, pattern: PatternNode[], start: Position, groups: CaptureGroup[]): MatchResult | null {
  if (pattern.length === 0) {
    return { start, end: start, groups };
  }
  const first = pattern[0];
  const rest = pattern.slice(1);
  if (first.type === 'alt') {
    for (const child of first.children) {
      const result = matchAt(subject, child, start, groups);
      if (result) return result;
    }
    return null;
  }
  if (first.type === 'group') {
    const groupResult = matchAt(subject, first.children, start, groups);
    if (groupResult) {
      return { start, end: groupResult.end, groups: [...groups, ...groupResult.groups] };
    }
    return null;
  }
  if (first.type === 'literal' || first.type === '.' || first.type === 'class' || first.type === 'escape' || first.type === 'anchor') {
    const char = subject[start];
    if (char === undefined) return null;
    if (first.type === 'literal' && first.value !== char) return null;
    if (first.type === '.' && char === '\n') return null;
    if (first.type === 'class') {
      const items = parseClass(first.value);
      if (!matchesChar(char, items)) return null;
    }
    if (first.type === 'escape') {
      if (char === '\\') return null;
    }
    if (first.type === 'anchor') {
      if (first.value === '^' && start !== 0) return null;
      if (first.value === '$' && start !== subject.length) return null;
    }
    const quantifier = first.quantifier;
    if (quantifier) {
      let count = 0;
      if (quantifier.type === '*') count = 0;
      else if (quantifier.type === '+') count = 1;
      else if (quantifier.type === '?') count = 0;
      else if (quantifier.type === '{m}') count = parseInt(quantifier.type.substring(2), 10);
      else if (quantifier.type === '{m,}') count = parseInt(quantifier.type.substring(2), 10);
      else if (quantifier.type === '{m,n}') count = parseInt(quantifier.type.substring(2, quantifier.type.length - 1), 10);
      else count = 0;
      for (let i = start; i < subject.length && count < quantifier.type === '*' ? 0 : quantifier.type === '+' ? 1 : 1; i++) {
        const char = subject[i];
        if (first.type === 'literal' && char !== first.value) break;
        if (first.type === '.' && char === '\n') break;
        if (first.type === 'class') {
          const items = parseClass(first.value);
          if (!matchesChar(char, items)) break;
        }
        if (first.type === 'escape') {
          if (char === '\\') break;
        }
        if (first.type === 'anchor') {
          if (first.value === '^' && i !== 0) break;
          if (first.value === '$' && i !== subject.length) break;
        }
        count++;
      }
      const result = matchAt(subject, rest, i, groups);
      if (result) return result;
    }
    return null;
  }
  return null;
}

