                    p->items[p->item_count].type = 'a';
                    p->items[p->item_count].data.char_code = 's';
                    p->item_count++;
                } else if (next == 'D') {
                    p->items[p->item_count].type = 'a';
                    p->items[p->item_count].data.char_code = 'D';
                    p->item_count++;
                } else if (next == 'W') {
                    p->items[p->item_count].type = 'a';
                    p->items[p->item_count].data.char_code = 'W';
                    p->item_count++;
                } else if (next == 'S') {
                    p->items[p->item_count].type = 'a';
                    p->items[p->item_count].data.char_code = 'S';
                    p->item_count++;
                } else {
                    p->items[p->item_count].type = 'l';
                    p->items[p->item_count].data.char_code = next;
                    p->item_count++;
                }
            }
        } else {
            // Literal character
            p->items[p->item_count].type = 'l';
            p->items[p->item_count].data.char_code = c;
            p->item_count++;
        }
        i++;
    }

    return 0;
}

bool match_literal(SearchContext *ctx, int pos, int end, int start, int end2) {
    for (int i = start; i < end; i++) {
        if (i >= ctx->subject_len) return false;
        char c = ctx->subject[i];
        char p = ctx->pattern.items[0].data.char_code;
        if (p != 0 && p != c) return false;
    }
    return true;
}

bool match_dot(SearchContext *ctx, int pos, int end, int start, int end2) {
    for (int i = start; i < end; i++) {
        if (i >= ctx->subject_len) return false;
        // . matches any character
        return true;
    }
    return true;
}

bool match_class(SearchContext *ctx, int pos, int end, int start, int end2) {
    for (int i = start; i < end; i++) {
        if (i >= ctx->subject_len) return false;
        char c = ctx->subject[i];
        char p = ctx->pattern.items[0].data.char_code;
        if (p != 0 && p != c) return false;
    }
    return true;
}

bool match_group(SearchContext *ctx, int pos, int end, int start, int end2) {
    for (int i = start; i < end; i++) {
        if (i >= ctx->subject_len) return false;
        char c = ctx->subject[i];
        char p = ctx->pattern.items[0].data.char_code;
        if (p != 0 && p != c) return false;
    }
    return true;
}

bool match_quantifier(SearchContext *ctx, int pos, int end, int start, int end2, int min, int max, bool lazy, int *current_count, int *last_match) {
    if (lazy) {
        // Try minimal first
        if (min == 0) {
            if (match_group(ctx, pos, end, start, end2)) {
                *current_count = 1;
                *last_match = end2;
                return true;
            }
        }
        // Try more
        while (*current_count < max && *current_count < end2 - start) {
            if (match_group(ctx, pos, end, start, end2)) {
                (*current_count)++;
                *last_match = end2;
                return true;
            }
        }
        return false;
    } else {
        // Greedy: try maximal first
        while (*current_count < max && *current_count < end2 - start) {
            if (match_group(ctx, pos, end, start, end2)) {
                (*current_count)++;
                *last_match = end2;
                return true;
            }
        }
        // Backtrack
        if (*current_count < min) {
            return false;
        }
        return match_group(ctx, pos, end, start, end2);
    }
}

bool match_branch(SearchContext *ctx, int pos, int end, int start, int end2) {
    if (start >= end) return true;
    char c = ctx->pattern.items[start].type;
    if (c == 'a') {
        int j = start + 1;
        while (j < end) {
            if (ctx->pattern.items[j].type == '|' || ctx->pattern.items[j].type == '(') {
                j++;
                break;
            }
            j++;
        }
        if (j >= end) {
            int j2 = j;
            while (j2 < end && ctx->pattern.items[j2].type != '|') {
                j2++;
            }
            if (j2 < end) {
                j = j2 + 1;
            }
            // Try this branch
            if (match_branch(ctx, j, end, start + 1, end2)) {
                return true;
            }
        }
        return false;
    } else if (c == 'q') {
        int j = start + 1;
        while (j < end) {
            if (ctx->pattern.items[j].type == '|' || ctx->pattern.items[j].type == '(') {
                j++;
                break;
            }
            j++;
        }
        if (j >= end) {
            int j2 = j;
            while (j2 < end && ctx->pattern.items[j2].type != '|') {
                j2++;
            }
            if (j2 < end) {
                j = j2 + 1;
            }
            // Try this branch
            if (match_branch(ctx, j, end, start + 1, end2)) {
                return true;
            }
        }
        return false;
    } else if (c == 'b') {
        // Branch
        int j = start + 1;
        while (j < end) {
            if (ctx->pattern.items[j].type == '|' || ctx->pattern.items[j].type == '(') {
                j++;
                break;
            }
            j++;
        }
        if (j >= end) {
            int j2 = j;
            while (j2 < end && ctx->pattern.items[j2].type != '|') {
                j2++;
            }
            if (j2 < end) {
                j = j2 + 1;
            }
            // Try this branch
            if (match_branch(ctx, j, end, start + 1, end2)) {
                return true;
            }
        }
        return false;
    } else if (c == 'l') {
        // Literal
        if (ctx->subject_len <= pos) return false;
        char c = ctx->pattern.items[start].data.char_code;
        if (c != 0 && ctx->subject[pos] != c) return false;
        return true;
    } else if (c == '.') {
        // Dot
        if (ctx->subject_len <= pos) return false;
        return true;
    } else if (c == '^') {
        // Anchor at start
        if (pos == 0) return true;
        return false;
    } else if (c == '$') {
        // Anchor at end
        if (pos == ctx->subject_len) return true;
        return false;
    } else if (c == '[') {
        // Class
        if (ctx->subject_len <= pos) return false;
        char c = ctx->subject[pos];
        char p = ctx->pattern.items[start].data.char_code;
        if (p != 0 && p != c) return false;
        return true;
    } else if (c == '?') {
        // Optional
        if (pos < ctx->subject_len) {
            char c = ctx->subject[pos];
            char p = ctx->pattern.items[start].data.char_code;
            if (p != 0 && p != c) return false;
            return true;
        }
        return true;
    } else if (c == '*') {
        // Star
        while (pos < ctx->subject_len) {
            char c = ctx->subject[pos];
            char p = ctx->pattern.items[start].data.char_code;
            if (p != 0 && p != c) break;
            pos++;
        }
        return true;
    } else if (c == '+') {
        // Plus
        if (pos < ctx->subject_len) {
            char c = ctx->subject[pos];
            char p = ctx->pattern.items[start].data.char_code;
            if (p != 0 && p != c) return false;
            pos++;
        }
        return true;
    } else if (c == '{') {
        // Quantifier
        int j = start + 1;
        while (j < end) {
            if (ctx->pattern.items[j].type == '|' || ctx->pattern.items[j].type == '(') {
                j++;
                break;
            }
            j++;
        }
        if (j >= end) {
            int j2 = j;
            while (j2 < end && ctx->pattern.items[j2].type != '|') {
                j2++;
            }
            if (j2 < end) {
                j = j2 + 1;
            }
            // Try this branch
            if (match_branch(ctx, j, end, start + 1, end2)) {
                return true;
            }
        }
        return false;
    }
    return false;
}

bool match(SearchContext *ctx, int pos, int end, int start, int end2) {
    if (pos >= ctx->subject_len) {
        if (start >= end) return true;
        return false;
    }

    // Memoization
    if (ctx->memoized[start][pos]) {
        return ctx->memo_result[start][pos] == 1;
    }

    char c = ctx->pattern.items[start].type;
    bool result = false;

    if (c == 'a') {
        int j = start + 1;
        while (j < end) {
            if (ctx->pattern.items[j].type == '|' || ctx->pattern.items[j].type == '(') {
                j++;
                break;
            }
            j++;
        }
        if (j >= end) {
            int j2 = j;
            while (j2 < end && ctx->pattern.items[j2].type != '|') {
                j2++;
            }
            if (j2 < end) {
                j = j2 + 1;
            }
            // Try this branch
            if (match(ctx, j, end, start + 1, end2)) {
                result = true;
            }
        }
    } else if (c == 'q') {
        int j = start + 1;
        while (j < end) {
            if (ctx->pattern.items[j].type == '|' || ctx->pattern.items[j].type == '(') {
                j++;
                break;
            }
            j++;
        }
        if (j >= end) {
            int j2 = j;
            while (j2 < end && ctx->pattern.items[j2].type != '|') {
                j2++;
            }
            if (j2 < end) {
                j = j2 + 1;
            }
            // Try this branch
            if (match(ctx, j, end, start + 1, end2)) {
                result = true;
            }
        }
    } else if (c == 'b') {
        int j = start + 1;
        while (j < end) {
            if (ctx->pattern.items[j].type == '|' || ctx->pattern.items[j].type == '(') {
                j++;
                break;
            }
            j++;
        }
        if (j >= end) {
            int j2 = j;
            while (j2 < end && ctx->pattern.items[j2].type != '|') {
                j2++;
            }
            if (j2 < end) {
                j = j2 + 1;
            }
            // Try this branch
            if (match(ctx, j, end, start + 1, end2)) {
                result = true;
            }
        }
    } else if (c == 'l') {
        if (ctx->subject_len <= pos) {
            result = false;
        } else {
            char c = ctx->pattern.items[start].data.char_code;
            if (c == 0 || ctx->subject[pos] == c) {
                result = match(ctx, pos + 1, end, start + 1, end2);
            } else {
                result = false;
            }
        }
    } else if (c == '.') {
        if (ctx->subject_len <= pos) {
            result = false;
        } else {
            result = match(ctx, pos + 1, end, start + 1, end2);
        }
    } else if (c == '^') {
        if (pos == 0) {
            result = match(ctx, pos + 1, end, start + 1, end2);
        } else {
            result = false;
        }
    } else if (c == '$') {
        if (pos == ctx->subject_len) {
            result = match(ctx, pos + 1, end, start + 1, end2);
        } else {
            result = false;
        }
    } else if (c == '[') {
        if (ctx->subject_len <= pos) {
            result = false;
        } else {
            char c = ctx->subject[pos];
            char p = ctx->pattern.items[start].data.char_code;
            if (p == 0 || p == c) {
                result = match(ctx, pos + 1, end, start + 1, end2);
            } else {
                result = false;
            }
        }
    } else if (c == '?') {
        if (ctx->subject_len <= pos) {
            result = match(ctx, pos, end, start + 1, end2);
        } else {
            char c = ctx->subject[pos];
            char p = ctx->pattern.items[start].data.char_code;
            if (p == 0 || p == c) {
                result = match(ctx, pos + 1, end, start + 1, end2);
            } else {
                result = false;
            }
        }
    } else if (c == '*') {
        while (pos < ctx->subject_len) {
            char c = ctx->subject[pos];
            char p = ctx->pattern.items[start].data.char_code;
            if (p == 0 || p == c) {
                result = match(ctx, pos + 1, end, start + 1, end2);
            } else {
                break;
            }
            pos++;
        }
        if (result) {
            ctx->memoized[start][pos] = true;
            ctx->memo_result[start][pos] = 1;
        }
        return result;
    } else if (c == '+') {
        if (ctx->subject_len <= pos) {
            result = false;
        } else {
            char c = ctx->subject[pos];
            char p = ctx->pattern.items[start].data.char_code;
            if (p == 0 || p == c) {
                result = match(ctx, pos + 1, end, start + 1, end2);
            } else {
                result = false;
            }
        }
    } else if (c == '{') {
        int j = start + 1;
        while (j < end) {
            if (ctx->pattern.items[j].type == '|' || ctx->pattern.items[j].type == '(') {
                j++;
                break;
            }
            j++;
        }
        if (j >= end) {
            int j2 = j;
            while (j2 < end && ctx->pattern.items[j2].type != '|') {
                j2++;
            }
            if (j2 < end) {
                j = j2 + 1;
            }
            // Try this branch
            if (match(ctx, j, end, start + 1, end2)) {
                result = true;
            }
        }
    }

    ctx->memoized[start][pos] = true;
    ctx->memo_result[start][pos] = result ? 1 : 0;
    return result;
}

bool match_pattern(SearchContext *ctx) {
    ctx->current_pos = 0;
    ctx->match_start = -1;
    ctx->captures[0].unset = true;
    for (int i = 1; i < ctx->pattern.group_count; i++) {
        ctx->captures[i].unset = true;
    }

    if (match(ctx, 0, ctx->pattern.item_count, 0, ctx->pattern.item_count)) {
        ctx->match_start = 0;
        return true;
    }
    return false;
}

void print_matches(SearchContext *ctx, int test_num) {
    if (!ctx->match_start) {
        printf("%d: no match\n", test_num);
        return;
    }

    printf("%d: %d-%d", test_num, ctx->match_start, ctx->match_start + ctx->pattern.items[0].data.char_code);
    for (int i = 1; i < ctx->pattern.group_count; i++) {
        if (!ctx->captures[i].unset) {
            printf(" %d-%d", ctx->captures[i].start_pos, ctx->captures[i].end_pos);
        } else {
            printf(" -");
        }
    }
    printf("\n");
}

void print_captures(SearchContext *ctx, int test_num) {
    if (!ctx->match_start) {
        printf("%d: no match\n", test_num);
        return;
    }

    printf("%d: %d-%d", test_num, ctx->match_start, ctx->match_start + ctx->pattern.items[0].data.char_code);
    for (int i = 1; i < ctx->pattern.group_count; i++) {
        if (!ctx->captures[i].unset) {
            printf(" %d-%d", ctx->captures[i].start_pos, ctx->captures[i].end_pos);
        } else {
            printf(" -");
        }
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return 1;
    }

    char filename[MAX_PATH];
    snprintf(filename, sizeof(filename), "%s/cases.txt", argv[1]);

    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s\n", filename);
        return 1;
    }

    char line[1024];
    int test_num = 1;

    while (fgets(line, sizeof(line), fp)) {
        if (strlen(line) <= 1) continue;

        SearchContext ctx;
        reset_context(&ctx);

        char *p = line;
        char *tab = strchr(p, '\t');
        if (!tab) continue;

        *tab = '\0';
        char *subject = tab + 1;

        int len = strlen(p);
        if (len == 0) continue;

        RegexPattern pattern;
        memset(&pattern, 0, sizeof(pattern));

        int result = parse_pattern(p, &pattern);
        if (result != 0) {
            fprintf(stderr, "Error parsing pattern: %s\n", p);
            continue;
        }

        ctx.subject_len = strlen(subject);
        ctx.subject_len = 0;
        ctx.subject[ctx.subject_len] = '\0';
        ctx.subject_len = ctx.subject_len;

        match_pattern(&ctx);

        print_captures(&ctx, test_num);
        test_num++;
    }

    fclose(fp);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>
#include <limits.h>

#define MAX_PATH 256
#define MAX_PATTERN 60
#define MAX_SUBJECT 80
#define MAX_MEMO 1000000

typedef struct {
    int id;
    int start_pos;
    int end_pos;
    bool unset;
} CaptureGroup;

typedef enum {
    TYPE_LIT = 0,
    TYPE_DOT,
    TYPE_CLASS,
    TYPE_ESC,
    TYPE_ANCHOR,
    TYPE_GROUP,
    TYPE_NONCAP,
    TYPE_QUANT,
    TYPE_BRANCH
} ItemType;

typedef struct {
    ItemType type;
    int min;
    int max;
    bool lazy;
    char code;
    struct PatternItem *next; // for |
    struct PatternItem *child; // for nested
} PatternItem;

typedef struct {
    PatternItem *items;
    int item_count;
    int group_count;
} Pattern;

typedef struct {
    Pattern pattern;
    char subject[MAX_SUBJECT];
    int subject_len;
    int current_pos;
    int match_start;
    CaptureGroup captures[60];
    bool memoized[MAX_SUBJECT][MAX_PATTERN];
    int memo_result[MAX_SUBJECT][MAX_PATTERN];
    int memo_depth[MAX_SUBJECT][MAX_PATTERN];
} SearchContext;

int pattern_len(Pattern *p) {
    int len = 0;
    for (int i = 0; i < p->item_count; i++) {
        if (p->items[i].type == TYPE_GROUP || p->items[i].type == TYPE_NONCAP || p->items[i].type == TYPE_BRANCH) {
            len++;
        }
    }
    return len;
}

void reset_context(SearchContext *ctx) {
    ctx->current_pos = 0;
    ctx->match_start = -1;
    ctx->pattern.item_count = 0;
    ctx->pattern.group_count = 0;
    ctx->pattern.items = NULL;
    ctx->subject_len = 0;
    memset(ctx->memoized, 0, sizeof(ctx->memoized));
    memset(ctx->memo_result, 0, sizeof(ctx->memo_result));
    memset(ctx->memo_depth, 0, sizeof(ctx->memo_depth));
    memset(ctx->captures, 0, sizeof(ctx->captures));
    for (int i = 0; i < 60; i++) {
        ctx->captures[i].start_pos = -1;
        ctx->captures[i].end_pos = -1;
    }
}

PatternItem *alloc_pattern_item(PatternItem *p) {
    PatternItem *new = malloc(sizeof(PatternItem));
    if (!new) return NULL;
    *new = *p;
    return new;
}

PatternItem *parse_pattern(Pattern *p, const char *pattern) {
    p->items = NULL;
    p->item_count = 0;
    p->group_count = 0;

    char *pos = (char *)pattern;
    int len = strlen(pattern);

    while (*pos) {
        char c = *pos++;
        if (c == '(') {
            pos++;
            if (*pos == '?') pos++;
            PatternItem *child = NULL;
            // Parse child
            PatternItem *item = parse_pattern(p, pos);
            if (!item) return NULL;
            child = item;
            pos = (char *)item->child;
            // Skip to end of child
            while (*pos == ')') pos++;
            if (*pos == ')') pos++;
            // Check if non-capturing
            if (*pos == '?') {
                pos++;
                // Skip to end of group
                while (*pos != ')') pos++;
                if (*pos == ')') pos++;
                // Add as non-capturing
                PatternItem *nc = malloc(sizeof(PatternItem));
                if (!nc) return NULL;
                nc->type = TYPE_NONCAP;
                nc->child = child;
                nc->next = NULL;
                p->items = alloc_pattern_item(p->items);
                p->items->type = TYPE_GROUP;
                p->items->child = nc;
                p->items->child->next = child;
                p->items->child->next->type = TYPE_NONCAP;
                p->items->child->next->next = NULL;
                p->items->child->next->next->child = child;
                p->items->child->next->next->next = NULL;
                p->item_count++;
            } else {
                // Capturing
                PatternItem *cap = malloc(sizeof(PatternItem));
                if (!cap) return NULL;
                cap->type = TYPE_GROUP;
                cap->child = child;
                cap->next = NULL;
                p->items = alloc_pattern_item(p->items);
                p->items->type = TYPE_GROUP;
                p->items->child = cap;
                p->item_count++;
            }
        } else if (c == '|') {
            pos++;
            PatternItem *next = NULL;
            while (*pos != '\0' && *pos != '\n') {
                PatternItem *item = malloc(sizeof(PatternItem));
                if (!item) return NULL;
                item->type = TYPE_BRANCH;
                item->child = parse_pattern(p, pos);
                if (!item->child) return NULL;
                item->next = next;
                next = item;
                pos += strlen((char *)item->child->next ? item->child->next->next : "");
            }
            p->items = alloc_pattern_item(p->items);
            p->items->type = TYPE_BRANCH;
            p->items->next = next;
            p->item_count++;
        } else if (c == '[') {
            pos++;
            int j = 0;
            while (*pos != ']') pos++;
            pos++;
            PatternItem *cls = malloc(sizeof(PatternItem));
            if (!cls) return NULL;
            cls->type = TYPE_CLASS;
            cls->child = parse_pattern(p, pos);
            if (!cls->child) return NULL;
            pos += strlen((char *)cls->child->next ? cls->child->next->next : "");
        } else if (c == '.' || c == '^' || c == '$') {
            pos++;
            PatternItem *lit = malloc(sizeof(PatternItem));
            if (!lit) return NULL;
            lit->type = c == '.' ? TYPE_DOT : TYPE_ANCHOR;
            lit->child = NULL;
            lit->next = NULL;
            p->items = alloc_pattern_item(p->items);
            p->items->type = lit->type;
            p->items->child = lit;
            p->item_count++;
        } else if (c == '\\') {
            pos++;
            char next = *pos;
            pos++;
            PatternItem *lit = malloc(sizeof(PatternItem));
            if (!lit) return NULL;
            lit->type = TYPE_ESC;
            lit->child = NULL;
            lit->next = NULL;
            p->items = alloc_pattern_item(p->items);
            p->items->type = TYPE_ESC;
            p->items->child = lit;
            p->item_count++;
        } else {
            PatternItem *lit = malloc(sizeof(PatternItem));
            if (!lit) return NULL;
            lit->type = TYPE_LIT;
            lit->child = NULL;
            lit->next = NULL;
            p->items = alloc_pattern_item(p->items);
            p->items->type = TYPE_LIT;
            p->items->child = lit;
            p->item_count++;
        }
    }
    return NULL;
}

bool can_match(SearchContext *ctx, int pos, int index) {
    if (index >= ctx->pattern.item_count) {
        return true;
    }
    if (ctx->memoized[pos][index]) {
        return ctx->memo_result[pos][index] == 1;
    }
    PatternItem *item = ctx->pattern.items[index];
    bool result = false;

    if (item->type == TYPE_LIT || item->type == TYPE_DOT || item->type == TYPE_CLASS || item->type == TYPE_ESC) {
        if (pos >= ctx->subject_len) {
            ctx->memoized[pos][index] = true;
            ctx->memo_result[pos][index] = 0;
            return false;
        }
        char c = ctx->subject[pos];
        if (item->type == TYPE_DOT) {
            result = true;
        } else {
            if (item->type == TYPE_LIT) {
                if (c == item->child->code) result = true;
            } else if (item->type == TYPE_CLASS) {
                if (ctx->subject[pos] == item->child->code) result = true;
            } else if (item->type == TYPE_ESC) {
                if (c == item->child->code) result = true;
            }
        }
        ctx->memoized[pos][index] = true;
        ctx->memo_result[pos][index] = result ? 1 : 0;
        return result;
