    page_size = struct.unpack('>H', header[16:18])[0]
    reserved = struct.unpack('>H', header[18:20])[0]
    return page_size, reserved

def read_varint(data, offset):
    result = 0
    shift = 0
    while offset + 8 <= len(data):
        byte = data[offset]
        if byte & 0x80:
            result |= (byte & 0x7f) << shift
            offset += 1
            shift += 7
            if shift == 63:
                break
        else:
            result |= byte << shift
            break
        offset += 1
    return result, offset

def read_varint_int(data, offset):
    result = 0
    shift = 0
    while True:
        byte = data[offset]
        if byte & 0x80:
            result |= (byte & 0x7f) << shift
            offset += 1
            shift += 7
            if shift == 63:
                break
        else:
            result |= byte << shift
            break
        offset += 1
