def parse_create_sql(sql):
    """Parse CREATE TABLE statement and extract column definitions"""
    # Remove CREATE TABLE keyword and table name
    match = re.match(r'CREATE\s+TABLE\s+"?(\w+)"?\s*\((.+)\)', sql, re.IGNORECASE)
    if not match:
        return None, []
    table_name = match.group(1)
    defs_str = match.group(2)

    columns = []
    current_def = ""
    paren_depth = 0
    i = 0
    while i < len(defs_str):
        c = defs_str[i]
        if c == '(':
            paren_depth += 1
            current_def += c
        elif c == ')':
            paren_depth -= 1
            current_def += c
        elif c == ',' and paren_depth == 0:
            if current_def.strip():
                columns.append(current_def.strip())
            current_def = ""
        else:
            current_def += c
        i += 1
    if current_def.strip():
        columns.append(current_def.strip())
    return table_name, columns

def extract_column_name_and_type(col_def):
    """Extract column name and type from column definition"""
    col_name = None
    col_type = None
    is_alias = False

    # Remove trailing parts after type
    match = re.match(r'(\w+|"[^"]*")\s*(.+)', col_def)
    if match:
        name_part = match.group(1)
        rest = match.group(2)

        if name_part.startswith('"'):
            col_name = name_part[1:-1]
        else:
            col_name = name_part

        # Check if it's an alias (INTEGER PRIMARY KEY)
        if col_name and rest.upper().strip() == 'PRIMARY KEY':
            is_alias = True
            col_type = 'INTEGER'
        else:
            # Extract type
            type_match = re.match(r'^\s*(\w+)', rest.upper().strip())
            if type_match:
                col_type = type_match.group(1)

    return col_name, col_type, is_alias

def format_value(value, is_text_or_blob=True, max_bytes=100):
    """Format a value according to SQLite serialization rules"""
    if value is None:
        return 'NULL'

    if isinstance(value, bool):
        return '1' if value else '0'

    if isinstance(value, int):
        return str(value)

    if isinstance(value, float):
        # Format as exact decimal
        if value == int(value):
            return str(int(value)) + '.0'
        else:
            # Use string formatting to get exact representation
            formatted = format(value, '.17g')
            # Remove trailing zeros after decimal point, but keep at least one
            if '.' in formatted:
                formatted = formatted.rstrip('0').rstrip('.')
                if '.' not in formatted:
                    formatted += '.0'
            return formatted

    if is_text_or_blob:
        if isinstance(value, bytes):
            if len(value) <= max_bytes:
                # Escape special characters
                result = []
                for b in value:
                    if b == ord('\\'):
                        result.append('\\\\')
                    elif b == ord('"'):
                        result.append('\\"')
                    elif b == ord('\n'):
                        result.append('\n')
                    elif b == ord('\r'):
                        result.append('\r')
                    elif b == ord('\t'):
                        result.append('\t')
                    elif b < 0x20 or b == 0x7F:
                        result.append(f'\\x{b:02X}')
                    else:
                        result.append(chr(b))
                return '"' + ''.join(result) + '"'
            else:
                crc = zlib.crc32(value) & 0xFFFFFFFF
                return f'<BLOB len={len(value)} crc32={crc:08x}>'
        elif isinstance(value, str):
            if len(value) <= max_bytes:
                # Escape special characters
                result = []
                for c in value:
                    if c == '\\':
                        result.append('\\\\')
                    elif c == '"':
                        result.append('\\"')
                    elif c == '\n':
                        result.append('\n')
                    elif c == '\r':
                        result.append('\r')
                    elif c == '\t':
                        result.append('\t')
                    elif ord(c) < 0x20 or ord(c) == 0x7F:
                        result.append(f'\\x{ord(c):02X}')
                    else:
                        result.append(c)
                return '"' + ''.join(result) + '"'
            else:
                crc = zlib.crc32(value.encode('utf-8')) & 0xFFFFFFFF
                return f'<TEXT len={len(value)} crc32={crc:08x}>'
    else:
        return str(value)

def read_page(data, page_num, page_size, reserved):
    """Read a page from the database file"""
    offset = (page_num - 1) * page_size
    return data[offset:offset + page_size], page_num

def get_db_pages(filepath, page_size):
    """Read all pages from the database file"""
    with open(filepath, 'rb') as f:
        return f.read(), page_size

def walk_btree_page(page_data, page_num, page_size, reserved, is_leaf=False):
    """Walk a B-tree page and return list of (rowid, cell_offset, cell_size) tuples"""
    cells = []
    page_type = page_data[0]

    if page_type == 0x0D:  # Interior
        for i in range(1, 32):
            cell_offset = page_size - reserved
            if i < 8:
                cell_size = page_data[1]
            else:
                cell_size = page_data[1] | (page_data[2] << 8)

            if cell_size == 0:
                continue

            child_offset = page_data[cell_offset]
            if child_offset < page_size:
                child_page = read_page(page_data, page_num + child_offset, page_size, reserved)[0]
                cells.extend(walk_btree_page(child_page, page_num + child_offset, page_size, reserved, is_leaf=True))
    elif page_type == 0x02:  # Leaf
        for i in range(1, 32):
            cell_offset = page_size - reserved
            if i < 8:
                cell_size = page_data[1]
            else:
                cell_size = page_data[1] | (page_data[2] << 8)

            if cell_size == 0:
                continue

            cell_offset = page_data[cell_offset]
            if cell_offset < page_size:
                # Read cell content
                cells.append((cell_offset, cell_size))
    elif page_type == 0x07:  # Freelist
        pass  # Skip freelist pages
    else:
        pass  # Skip other page types

    return cells

def read_cell(cell_data, cell_size, page_size, reserved):
    """Read a cell from the database file"""
    if cell_size == 0:
        return None, None

    offset = 0
    serial_type, offset = read_varint_int(cell_data, offset)

    if serial_type == 0:  # NULL
        return None, None
    elif serial_type == 1:  # INTEGER
        value, offset = read_varint_int64(cell_data, offset)
        return value, offset
    elif serial_type == 2:  # REAL
        value, offset = struct.unpack('>d', cell_data[offset:offset+8])[0]
        return value, offset
    elif serial_type == 3:  # TEXT
        text_length, offset = read_varint_uint(cell_data, offset)
        if offset + text_length <= len(cell_data):
            value = cell_data[offset:offset + text_length].decode('utf-8')
            return value, offset + text_length
        return None, None
    elif serial_type == 4:  # BLOB
        blob_length, offset = read_varint_uint(cell_data, offset)
        if offset + blob_length <= len(cell_data):
            value = cell_data[offset:offset + blob_length]
            return value, offset + blob_length
        return None, None
    else:
        return None, None

def get_table_schema(sql_text):
    """Parse the SQL text and extract column names and types"""
    columns = []
    # Remove CREATE TABLE keyword
    match = re.match(r'CREATE\s+TABLE\s+"?(\w+)"?\s*\((.+)\)', sql_text, re.IGNORECASE)
    if not match:
        return [], []

    table_name = match.group(1)
    defs_str = match.group(2)

    # Find column definitions
    current_def = ""
    paren_depth = 0
    i = 0
    while i < len(defs_str):
        c = defs_str[i]
        if c == '(':
            paren_depth += 1
            current_def += c
        elif c == ')':
            paren_depth -= 1
            current_def += c
        elif c == ',' and paren_depth == 0:
            if current_def.strip():
                columns.append(current_def.strip())
            current_def = ""
        else:
            current_def += c
        i += 1
    if current_def.strip():
        columns.append(current_def.strip())

    # Parse each column definition
    parsed_columns = []
    for col_def in columns:
        col_name, col_type, is_alias = extract_column_name_and_type(col_def)
        parsed_columns.append((col_name, col_type, is_alias))

    return parsed_columns

def read_schema_table(filepath, page_size, reserved):
    """Read the sqlite_schema table from the database"""
    schema_rows = []
    page_num = 1
    page_data, _ = read_page(get_db_pages(filepath, page_size)[0], page_num, page_size, reserved)

    while True:
        cells = walk_btree_page(page_data, page_num, page_size, reserved)
        if not cells:
            break

        for cell_offset, cell_size in cells:
            cell_data = page_data[cell_offset:cell_offset + cell_size]
            if len(cell_data) == 0:
                continue

            serial_type, offset = read_varint_int(cell_data, 0)

            if serial_type == 3:  # TEXT
                text_length, offset = read_varint_uint(cell_data, offset)
                if offset + text_length <= len(cell_data):
                    text = cell_data[offset:offset + text_length].decode('utf-8')
                    schema_rows.append(text)
        page_num += 1
        page_data, _ = read_page(get_db_pages(filepath, page_size)[0], page_num, page_size, reserved)

    return schema_rows

def main():
