static int parse_varint(const unsigned char **bytes) {
    int32_t result = 0;
    int shift = 0;
    while (*bytes && **bytes & 0x80) {
        result |= (**bytes & 0x7F) << shift;
        shift += 7;
        (*bytes)++;
        if (shift > 63) return -1;
    }
    if (shift < 0) return -1;
    if (shift < 32) {
        return result;
    }
    if (shift < 64) {
        result |= (**bytes & 0xFF) << shift;
        (*bytes)++;
        return result;
    }
    return -1;
}

static int32_t decode_signed_varint(const unsigned char *bytes, size_t len) {
    int32_t result = 0;
    int shift = 0;
    while (len > 0 && bytes[len-1] & 0x80) {
        result |= (bytes[--len] & 0x7F) << shift;
        shift += 7;
        if (shift >= 63) return -1;
    }
    if (shift < 32) {
        return result;
    }
    if (shift < 64) {
        result |= (bytes[--len] & 0xFF) << shift;
        if (shift < 63) result |= (bytes[--len] & 0xFF) << shift;
    }
    return result;
}

static int decode_sint32(const unsigned char *bytes, size_t len) {
    int32_t zigzag = decode_signed_varint(bytes, len);
    return ((zigzag << 1) ^ (zigzag >> 31));
