static void print_json_value(ProtoType type, const void *value, size_t len, int64_t int64_val, bool bool_val,
                             const char *enum_name, int enum_idx, int64_t enum_val, const char *map_key,
                             FILE *out) {
    if (type == TYPE_INT32 || type == TYPE_INT64 || type == TYPE_UINT32 || type == TYPE_UINT64 ||
        type == TYPE_SINT32 || type == TYPE_SINT64 || type == TYPE_FIXED32 || type == TYPE_FIXED64 ||
