            if (type == TYPE_INT32 || type == TYPE_INT64 || type == TYPE_SINT32 || type == TYPE_SINT64 ||
                type == TYPE_FIXED32 || type == TYPE_SFIXED32) {
                if (len > 0 || int64_val != 0) {
                    fprintf(out, "%lld", (long long)int64_val);
                } else {
                    fprintf(out, "0");
