static void base64_encode(const void *data, size_t len, char *out) {
    const unsigned char *d = (const unsigned char *)data;
    int i = 0;
    while (i < len) {
        unsigned char a = d[i];
        unsigned char b = (i + 1 < len) ? d[i + 1] : 0;
        unsigned char c = (i + 2 < len) ? d[i + 2] : 0;
        out[i * 4] = (a >> 2) & 0x3F;
        out[i * 4 + 1] = ((a << 4) | (b >> 4)) & 0x3F;
        out[i * 4 + 2] = ((b << 2) | (c >> 6)) & 0x3F;
        out[i * 4 + 3] = c & 0x3F;
        i++;
        if (i < len) i++;
        if (i < len) i++;
    }
    while (len % 3) {
        if (len % 3 == 2) {
            out[i * 4] = 64;
        } else {
            out[i * 4] = 64;
            out[i * 4 + 1] = 64;
        }
        out[i * 4 + 2] = 64;
        i++;
    }
    out[i * 4] = 0;
}

