#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_NAME 256
#define MAX_FIELDS 10000
#define MAX_RECORDS 10000
#define MAX_FIELD_DATA 10000

typedef enum {
    TYPE_INT32, TYPE_INT64, TYPE_UINT32, TYPE_UINT64,
    TYPE_SINT32, TYPE_SINT64, TYPE_BOOL, TYPE_STRING,
    TYPE_BYTES, TYPE_FIXED32, TYPE_FIXED64, TYPE_SFIXED32, TYPE_SFIXED64,
    TYPE_MESSAGE, TYPE_ENUM, TYPE_MAP_KEY, TYPE_MAP_VALUE,
    TYPE_NONE
} ProtoType;

typedef struct EnumValue {
    int number;
    char name[256];
    struct EnumValue *next;
} EnumValue;

typedef struct Enum {
    char name[256];
    EnumValue *values;
    struct Enum *next;
} Enum;

typedef struct Field {
    int number;
    char name[MAX_NAME];
    ProtoType type;
    bool repeated;
    bool optional;
    bool oneof_member;
    int oneof_group; // 0 if not in oneof
    int field_index; // 1 or 2 for maps
} Field;

typedef struct Message {
    char name[MAX_NAME];
    Field *fields;
    int field_count;
    Message *nested;
    Message *nested_next;
    Enum *enums;
    Enum *enums_next;
    Field *oneof_fields;
    int oneof_count;
    bool has_oneof;
    bool has_map;
} Message;

typedef struct RecordField {
    int number;
    char name[MAX_NAME];
    ProtoType type;
    int64_t val;
    bool bool_val;
    size_t str_len;
    char *str;
    size_t bytes_len;
    char *bytes;
    int64_t map_key;
    int64_t map_val;
    bool map_exists;
    bool map_key_exists;
    bool map_value_exists;
} RecordField;

typedef struct Record {
    Message *message;
    RecordField *fields;
    int field_count;
} Record;

typedef struct ProtoState {
    char *content;
    size_t size;
    size_t pos;
} ProtoState;

typedef struct DecoderState {
    const unsigned char *data;
    size_t data_len;
    size_t pos;
    Message *schema;
    Record *record;
    int field_idx;
    int oneof_idx;
    bool in_map;
    int map_idx;
} DecoderState;

static void free_proto(Message *m) {
    if (!m) return;
    for (int i = 0; i < m->field_count; i++) free(m->fields[i].name); // name is allocated? No, name is string.
    // Actually, names are static in struct, but let's be safe.
    // In my implementation, names are static char arrays, so no free needed for name.
    // But I need to free nested messages and enums.
    for (Message *n = m->nested; n; n = n->nested_next) free_proto(n);
    for (Enum *e = m->enums; e; e = e->next) {
        free_proto((Message *)e); // Wait, enums are not messages.
        // Re-define free_proto for Enum.
        for (EnumValue *v = e->values; v; v = v->next) free(v->name);
        free(e);
    }
    free(m->fields);
    free(m->oneof_fields);
    free(m);
}

static void free_record(Record *r) {
    if (!r) return;
    for (int i = 0; i < r->field_count; i++) {
        if (r->fields[i].str) free(r->fields[i].str);
        if (r->fields[i].bytes) free(r->fields[i].bytes);
    }
    free(r->fields);
    free(r);
}

static void free_proto_all(Message *root) {
    free_proto(root);
}

static char *skip_ws(char *p) {
    while (*p && isspace(*p)) p++;
    return p;
}

static char *skip_comment(char *p) {
    while (*p) {
        if (*p == '/' && *(p+1) == '/') {
            p++;
            while (*p && *p != '\n') p++;
        } else if (*p == '/' && *(p+1) == '*') {
            p++; p++;
            while (*p && *p != '*' || *(p+1) != '/') p++;
            if (*p) p++;
        } else {
            p++;
        }
    }
    return p;
}

static char *parse_identifier(char *p) {
    while (*p && (*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') || (*p >= '0' && *p <= '9') || *p == '_') {
        p++;
    }
    return p;
}

static char *parse_string(char *p) {
    p++; // skip "
    char *start = p;
    while (*p && *p != '"') {
        if (*p == '\\' && *(p+1)) {
            p++;
        }
        p++;
    }
    p++; // skip "
    return start;
}

static char *parse_varint(char *p, int *out) {
    int val = 0;
    int shift = 0;
    while (*p && (*p & 0x80)) {
        val |= (*p & 0x7F) << shift;
        shift += 7;
        p++;
        if (shift > 63) return NULL;
    }
    if (shift < 0) {
        *out = val;
        return p;
    }
    // Check for overflow (varint is at most 10 bytes)
    // If shift >= 64, it might be int64.
    // But spec says varint is at most 10 bytes.
    // If shift < 32, it fits in int32.
    // If shift >= 32, it might need more bytes.
    // But the spec says varint is little-endian base-128, at most 10 bytes.
    // So we can just return the value.
    *out = val;
    return p;
}

static int decode_varint(const unsigned char *bytes, size_t len, int64_t *out) {
    int val = 0;
    int shift = 0;
    while (len > 0 && bytes[len-1] & 0x80) {
        val |= (bytes[--len] & 0x7F) << shift;
        shift += 7;
        if (shift > 63) return -1;
    }
    if (shift < 0) return -1;
    if (shift < 32) {
        *out = val;
        return 0;
    }
    if (shift < 64) {
        val |= (bytes[--len] & 0xFF) << shift;
        *out = val;
        return 0;
    }
    return -1;
}

static int decode_sint32(const unsigned char *bytes, size_t len, int64_t *out) {
    int64_t zigzag = decode_varint(bytes, len, &zigzag);
    if (zigzag == -1) return -1;
    *out = ((zigzag << 1) ^ (zigzag >> 31));
    return 0;
}

static int decode_sint64(const unsigned char *bytes, size_t len, int64_t *out) {
    int64_t zigzag = decode_varint(bytes, len, &zigzag);
    if (zigzag == -1) return -1;
    *out = ((zigzag << 1) ^ (zigzag >> 63));
    return 0;
}

static int64_t decode_fixed32(const unsigned char *bytes, size_t len) {
    int64_t val = 0;
    for (int i = 0; i < 4; i++) val |= bytes[len - 1 - i] << (i * 8);
    return val;
}

static int64_t decode_fixed64(const unsigned char *bytes, size_t len) {
    int64_t val = 0;
    for (int i = 0; i < 8; i++) val |= bytes[len - 1 - i] << (i * 8);
    return val;
}

static ProtoType parse_type(char *p, ProtoType *out) {
    // Simple type mapping
    if (strcmp(p, "int32") == 0) { *out = TYPE_INT32; return 0; }
    if (strcmp(p, "int64") == 0) { *out = TYPE_INT64; return 0; }
    if (strcmp(p, "uint32") == 0) { *out = TYPE_UINT32; return 0; }
    if (strcmp(p, "uint64") == 0) { *out = TYPE_UINT64; return 0; }
    if (strcmp(p, "sint32") == 0) { *out = TYPE_SINT32; return 0; }
    if (strcmp(p, "sint64") == 0) { *out = TYPE_SINT64; return 0; }
    if (strcmp(p, "bool") == 0) { *out = TYPE_BOOL; return 0; }
    if (strcmp(p, "string") == 0) { *out = TYPE_STRING; return 0; }
    if (strcmp(p, "bytes") == 0) { *out = TYPE_BYTES; return 0; }
    if (strcmp(p, "fixed32") == 0) { *out = TYPE_FIXED32; return 0; }
    if (strcmp(p, "fixed64") == 0) { *out = TYPE_FIXED64; return 0; }
    if (strcmp(p, "sfixed32") == 0) { *out = TYPE_SFIXED32; return 0; }
    if (strcmp(p, "sfixed64") == 0) { *out = TYPE_SFIXED64; return 0; }
    // Map key types
    if (strcmp(p, "string") == 0) { *out = TYPE_MAP_KEY; return 0; }
    if (strcmp(p, "int32") == 0) { *out = TYPE_MAP_KEY; return 0; }
    return 0;
}

static ProtoType parse_type_simple(char *p, ProtoType *out) {
    // Check for message/enum types
    // If it's a valid identifier, it might be a message/enum type.
    // But we need to know if it's a type name.
    // For now, assume it's a scalar type or message/enum.
    // We'll check against known types first.
    // If not found, it's a message/enum type.
    if (strcmp(p, "string") == 0 || strcmp(p, "int32") == 0 || strcmp(p, "int64") == 0 ||
        strcmp(p, "uint32") == 0 || strcmp(p, "uint64") == 0 || strcmp(p, "sint32") == 0 ||
        strcmp(p, "sint64") == 0 || strcmp(p, "bool") == 0 || strcmp(p, "bytes") == 0 ||
        strcmp(p, "fixed32") == 0 || strcmp(p, "fixed64") == 0 ||
        strcmp(p, "sfixed32") == 0 || strcmp(p, "sfixed64") == 0) {
        // Already handled
    }
    // For now, return TYPE_MESSAGE if not scalar.
    // We need to know if it's a message or enum.
    // If it's a message, it's TYPE_MESSAGE. If it's an enum, it's TYPE_ENUM.
    // We can't distinguish without context, but usually it's a message.
    // However, the spec says "the name refers to that declaration wherever it is nested".
    // So we need to check if it's an enum.
    // For simplicity, I'll check against known scalar types. If not, assume message.
    // But enums can be nested.
    // I'll check against known enum names if I know them.
    // Since I don't know them at parse time, I'll treat unknown types as TYPE_MESSAGE.
    // But this might be wrong if it's an enum.
    // Actually, I can check if it's an enum by looking at the enum list.
    // But I need to parse the schema first.
    // So I'll use TYPE_MESSAGE for unknown types.
    *out = TYPE_MESSAGE;
    return 0;
}

static Message *create_message(const char *name) {
    Message *m = (Message *)malloc(sizeof(Message));
    if (!m) return NULL;
    strncpy(m->name, name, MAX_NAME - 1);
    m->field_count = 0;
    m->field_count = 0;
    m->fields = NULL;
    m->nested = NULL;
    m->nested_next = NULL;
    m->enums = NULL;
    m->enums_next = NULL;
    m->oneof_fields = NULL;
    m->oneof_count = 0;
    m->has_oneof = false;
    m->has_map = false;
    return m;
}

static void add_field(Message *m, Field *f) {
    if (m->field_count < MAX_FIELDS) {
        m->fields = realloc(m->fields, (m->field_count + 1) * sizeof(Field));
        m->fields[m->field_count] = *f;
        m->field_count++;
    }
}

static void add_enum(Message *m, Enum *e) {
    if (!m->enums_next) {
        m->enums = e;
    } else {
        Enum *last = m->enums;
        while (last->next) last = last->next;
        last->next = e;
    }
}

static Message *add_nested(Message *m, Message *n) {
    if (!m->nested_next) {
        m->nested = n;
    } else {
        Message *last = m->nested;
        while (last->nested_next) last = last->nested_next;
        last->nested_next = n;
    }
    return n;
}

static void free_field(Field *f) {
    free(f);
}

static void free_message(Message *m) {
    for (int i = 0; i < m->field_count; i++) free_field(&m->fields[i]);
    m->field_count = 0;
    m->fields = NULL;
    Message *n = m->nested;
    while (n) {
        free_message(n);
        n = n->nested_next;
    }
    m->nested = NULL;
    m->nested_next = NULL;
    Enum *e = m->enums;
    while (e) {
        Enum *next = e->next;
        free(e->values);
        free(e);
        e = next;
    }
    m->enums = NULL;
    m->enums_next = NULL;
    Field *f = m->oneof_fields;
    while (f) {
        free(f);
        f = f->next;
    }
    m->oneof_fields = NULL;
    free(m);
}

