#define SQLITE_MAGIC "SQLite format 3\0"
#define SQLITE_MAGIC_LEN 16
#define SQLITE_HEADER_SIZE 100
#define MAX_PAGE_SIZE 65536
#define MAX_ROWID 128
#define MAX_COLS 100
#define MAX_CELL_SIZE 1024
