typedef enum {
    SQLITE_NULL = 0,
    SQLITE_INTEGER = 1,
    SQLITE_FLOAT = 2,
    SQLITE_TEXT = 3,
    SQLITE_BLOB = 4,
    SQLITE_32BIT_INTEGER = 5
} sqlite_serial_type;

typedef struct {
    int type;
    int payload_len;
    int num_bytes;
