static int read_uint32(FILE *f) {
    uint32_t v = 0;
    if (fread(&v, 4, 1, f) != 1) return -1;
    return v;
}

static int read_int32(FILE *f) {
    int32_t v = 0;
    if (fread(&v, 4, 1, f) != 1) return -1;
    return v;
}

static int read_int64(FILE *f) {
    int64_t v = 0;
    if (fread(&v, 8, 1, f) != 1) return -1;
    return v;
}

static int calc_crc32(const char *data, int len) {
    unsigned long crc = 0xFFFFFFFF;
    unsigned char *c = (unsigned char *)data;
    for (int i = 0; i < len; i++) {
        crc ^= (unsigned int)c[i] << 24;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80000000) {
                crc = (crc << 1) ^ 0xEDB88320;
            } else {
                crc = crc << 1;
            }
        }
        crc = (crc >> 8) ^ 0xFF;
    }
    crc ^= 0xFFFFFFFF;
    return (int)crc;
}

static void print_value(sqlite_serial_type type, int payload_len, int num_bytes, const char *data, FILE *out) {
    if (type == SQLITE_NULL) {
        fprintf(out, "NULL");
    } else if (type == SQLITE_INTEGER) {
        if (payload_len == 1) {
            int v = (int)data[0];
            fprintf(out, "%d", v);
        } else if (payload_len == 2) {
            int v = (int)((unsigned int)data[0] | ((unsigned int)data[1] << 8));
            fprintf(out, "%d", v);
        } else if (payload_len == 4) {
            int32_t v = (int32_t)data[0] | ((int32_t)data[1] << 8) | ((int32_t)data[2] << 16) | ((int32_t)data[3] << 24);
            fprintf(out, "%d", v);
        } else {
            int64_t v = (int64_t)data[0] | ((int64_t)data[1] << 8) | ((int64_t)data[2] << 16) | ((int64_t)data[3] << 24) | ((int64_t)data[4] << 32) | ((int64_t)data[5] << 40) | ((int64_t)data[6] << 48) | ((int64_t)data[7] << 56);
            fprintf(out, "%" PRId64, v);
        }
    } else if (type == SQLITE_FLOAT) {
        double v = *(double *)data;
        fprintf(out, "%.8f", v);
    } else if (type == SQLITE_TEXT) {
        if (payload_len > 100) {
            int crc = calc_crc32(data, payload_len);
            fprintf(out, "<TEXT len=%d crc32=%08x>", payload_len, crc);
        } else {
            int i = 0;
            while (i < payload_len) {
                int c = data[i];
                if (c == '\\') {
                    fprintf(out, "\\\\");
                } else if (c == '"') {
                    fprintf(out, "\\\"");
                } else if (c == '\n') {
                    fprintf(out, "\\n");
                } else if (c == '\r') {
                    fprintf(out, "\\r");
                } else if (c == '\t') {
                    fprintf(out, "\\t");
                } else if (c < 0x20 || c > 0x7F) {
                    fprintf(out, "\\x%02X", c);
                } else {
                    fprintf(out, "%c", c);
                }
                i++;
            }
            fprintf(out, "\"");
        }
    } else if (type == SQLITE_BLOB) {
        if (payload_len > 100) {
            int crc = calc_crc32(data, payload_len);
            fprintf(out, "<BLOB len=%d crc32=%08x>", payload_len, crc);
        } else {
            fprintf(out, "X'");
            for (int i = 0; i < payload_len; i++) {
                fprintf(out, "%02X", data[i]);
            }
            fprintf(out, "'");
        }
    }
}

