import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';
import * as https from 'https';
import * as zlib from 'zlib';

interface ClientSettings {
  client_id: string;
  client_secret: string;
  scope: string;
  page_size: number;
}

interface Order {
  [key: string]: any;
}

interface PageResponse {
  data: Order[];
  next_cursor: string | null;
  [key: string]: any;
}

interface TokenResponse {
  access_token: string;
  token_type: string;
  expires_in: number;
  scope: string;
  [key: string]: any;
}

interface Stats {
  orders: number;
  pages: number;
  retries: number;
  reauth: number;
}

function readClientSettings(dataDir: string): ClientSettings {
  const clientPath = path.join(dataDir, 'client.json');
  const content = fs.readFileSync(clientPath, 'utf-8');
  return JSON.parse(content);
}

function formEncode(value: string): string {
  const encoder = new TextEncoder();
  const bytes = encoder.encode(value);

  let encoded = '';
  for (let i = 0; i < bytes.length; i++) {
    const byte = bytes[i];
    if (byte >= 65 && byte <= 90) {
      encoded += String.fromCharCode(byte);
    } else if (byte >= 97 && byte <= 122) {
      encoded += String.fromCharCode(byte);
    } else if (byte >= 48 && byte <= 57) {
      encoded += String.fromCharCode(byte);
    } else if (byte === 45 || byte === 95 || byte === 46 || byte === 42) {
      encoded += String.fromCharCode(byte);
    } else if (byte === 32) {
      encoded += '+';
    } else {
      encoded += '%' + (byte & 0xFF).toString(16).toUpperCase();
    }
  }

  return encoded;
}

function base64Encode(data: string): string {
  const encoder = new TextEncoder();
  const bytes = encoder.encode(data);
  const base64 = Buffer.from(bytes).toString('base64');
  return base64;
}

function makeBasicAuthHeader(client_id: string, client_secret: string): string {
  const encoded = formEncode(client_id) + ':' + formEncode(client_secret);
  return `Basic ${base64Encode(encoded)}`;
}

function makeAuthorizationHeader(token: string): string {
  return `Bearer ${token}`;
}

function makeRequest(baseUrl: string, method: string, path: string, headers: Record<string, string>, body?: string): Promise<{ status: number; headers: Record<string, string>; body: string }> {
  return new Promise((resolve) => {
    const url = new URL(path, baseUrl);
    const host = url.hostname + ':' + url.port;

    const options: http.ClientRequestOptions = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname + url.search,
      method: method,
      headers: {
        ...headers,
        'Host': host
      }
    };

    if (body) {
      options.headers['Content-Length'] = Buffer.byteLength(body, 'utf-8');
    }

    const req = http.request(options, (res) => {
      let body = '';

      res.on('data', (chunk) => {
        body += chunk.toString('utf-8');
      });

      res.on('end', () => {
        resolve({
          status: res.statusCode,
          headers: res.headers,
          body: body
        });
      });
    });

    req.on('error', (e) => {
      resolve({
        status: 0,
        headers: {},
        body: `Error: ${e.message}`
      });
    });

    req.write(body);
    req.end();
  });
}

function parseResponse(res: http.IncomingMessage): Promise<{ status: number; body: string }> {
  return new Promise((resolve) => {
    let body = '';

    res.on('data', (chunk) => {
      body += chunk.toString('utf-8');
    });

    res.on('end', () => {
      resolve({
        status: res.statusCode,
        body: body
      });
    });
  });
}

function parseJsonBody(body: string): any {
  try {
    return JSON.parse(body);
  } catch (e) {
    return null;
  }
}

function acquireToken(baseUrl: string, clientSettings: ClientSettings): Promise<{ token: string }> {
  return new Promise((resolve, reject) => {
    const tokenUrl = new URL('/oauth/token', baseUrl);

    const body = 'grant_type=client_credentials&scope=' + formEncode(clientSettings.scope);
    const headers: Record<string, string> = {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Authorization': makeBasicAuthHeader(clientSettings.client_id, clientSettings.client_secret),
      'Host': tokenUrl.hostname + ':' + tokenUrl.port
    };

    makeRequest(baseUrl, 'POST', tokenUrl.pathname + tokenUrl.search, headers, body)
      .then(response => {
        const json = parseJsonBody(response.body);
        if (json && json.access_token) {
          resolve({ token: json.access_token });
        } else {
          reject(new Error(`Failed to acquire token: ${response.body}`));
        }
      })
      .catch(error => {
        reject(error);
      });
  });
}

function fetchOrders(baseUrl: string, token: string, page_size: number, cursor: string | null = null): Promise<{ orders: Order[]; page: number; next_cursor: string | null }> {
  return new Promise((resolve, reject) => {
    const ordersUrl = new URL('/orders', baseUrl);
    const params = new URLSearchParams();
    params.set('limit', page_size.toString());

    if (cursor) {
      params.set('cursor', cursor);
    }

    ordersUrl.search = params.toString();

    const headers: Record<string, string> = {
      'Authorization': makeAuthorizationHeader(token),
      'Host': ordersUrl.hostname + ':' + ordersUrl.port
    };

    makeRequest(baseUrl, 'GET', ordersUrl.pathname + ordersUrl.search, headers)
      .then(response => {
        const json = parseJsonBody(response.body);
        if (json && json.data) {
          resolve({
            orders: json.data,
            page: page_size,
            next_cursor: json.next_cursor
          });
        } else {
          reject(new Error(`Failed to fetch orders: ${response.body}`));
        }
      })
      .catch(error => {
        reject(error);
      });
  });
}

function parseAmount(amount: string): number | null {
  if (!amount) return null;

  const match = amount.match(/^(-?)(\d+)(?:\.(\d{1,2}))?$/);
  if (!match) return null;

  let total = parseInt(match[2], 10);
  if (match[3]) {
    total = total * 100 + parseInt(match[3], 10);
  }

  return total;
}

function formatAmount(cents: number): string {
  if (cents === 0) return '0.00';

  const sign = cents < 0 ? '-' : '';
  const absCents = Math.abs(cents);
  const dollars = Math.floor(absCents / 100);
  const remaining = absCents % 100;

  return `${sign}${dollars}.${remaining.toString().padStart(2, '0')}`;
}

function sortNames(names: string[]): string[] {
  return names.sort((a, b) => {
    const aBytes = new TextEncoder().encode(a);
    const bBytes = new TextEncoder().encode(b);
    for (let i = 0; i < Math.max(aBytes.length, bBytes.length); i++) {
      const aByte = i < aBytes.length ? aBytes[i] : 0;
      const bByte = i < bBytes.length ? bBytes[i] : 0;
      if (aByte !== bByte) return aByte - bByte;
    }
    return 0;
  });
}

async function main(): Promise<void> {
  const [dataDir, baseUrl] = process.argv.slice(2);
  if (!dataDir || !baseUrl) {
    console.error('Usage: node main.ts <data_dir> <base_url>');
    process.exit(1);
  }

  const clientSettings = readClientSettings(dataDir);
  const page_size = clientSettings.page_size;
  const scope = clientSettings.scope;

  const tokenResponse = await acquireToken(baseUrl, clientSettings);
  if (tokenResponse.token === null) {
    console.error(`Failed to acquire token: ${tokenResponse.error}`);
    process.exit(1);
  }

  const orders: Order[] = [];
  let pages: number = 0;
  let retries: number = 0;
  let reauth: number = 0;

  let token = tokenResponse.token;
  let cursor: string | null = null;

  do {
    pages++;
    const response = await fetchOrders(baseUrl, token, page_size, cursor);

    if (response.orders.length > 0) {
      orders.push(...response.orders);
    }

    cursor = response.next_cursor;
  } while (cursor !== null);

  console.log(`Total orders: ${orders.length}`);
  console.log(`Total pages: ${pages}`);
  console.log(`Retries: ${retries}`);
  console.log(`Reauthentications: ${reauth}`);
}

main().catch(error => {
  console.error(error);
  process.exit(1);
});

