        long ordersReceived = 0;

        while (true) {
            String ordersUrl = baseUrl + "/orders";
            if (cursor != null) {
                ordersUrl += "?cursor=" + encodeCursor(cursor);
            }
            ordersUrl += "?limit=" + pageSize;

            try {
                int status = makeRequest(ordersUrl, "GET", accessToken, baseUrl);

                if (status == 200) {
                    JSONObject resp = parseJson(readResponseBody(ordersUrl));
                    pages++;

                    JSONObject body = resp;
                    List<JSONObject> data = body.getJSONArray("data");

                    for (JSONObject order : data) {
                        ordersReceived++;
                        String status = order.getString("status");
                        statusCounts.put(status, statusCounts.getOrDefault(status, 0) + 1);
                        allStatuses.add(status);

                        if (!"cancelled".equals(status)) {
                            String name = order.getString("customer_name");
                            String currency = order.getString("currency");
                            BigDecimal amount = order.getBigDecimal("amount");
                            totals.merge(name + currency, amount, BigDecimal::add);
