                    }
                } else if (status == 429) {
                    retries++;
                    int retryAfter = Integer.parseInt(resp.getHeader("Retry-After"));
                    Thread.sleep(retryAfter * 1000);
                } else if (status == 503) {
                    retries++;
                    Thread.sleep(Math.min(1000, Math.max(100, 1)));
                } else if (status == 401) {
                    reauth++;
                    accessToken = getAccessToken(clientId, clientSecret, scope, baseUrl);
