                    continue;
                } else {
                    String body = readResponseBody(ordersUrl);
                    System.out.println("ERROR " + status + " " + body);
                    System.exit(0);
                }
            } catch (Exception e) {
                String body = readResponseBody(ordersUrl);
                System.out.println("ERROR " + status + " " + body);
                System.exit(0);
            }
        }
    }

