    static String readResponseBody(String url) throws IOException {
        HttpURLConnection conn = (HttpURLConnection) new URL(url).openConnection();
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);

        try {
            String body;
            int status = conn.getResponseCode();
            String contentLength = conn.getHeaderField("Content-Length");

            if (contentLength != null) {
                body = readFully(conn.getInputStream(), Integer.parseInt(contentLength));
            } else {
                byte[] data = new byte[4096];
                int total = 0;
                while (conn.getInputStream().read(data) != -1) {
                    total += data.length;
                }
                body = new String(readFully(conn.getInputStream(), total), StandardCharsets.UTF_8);
            }
            return body;
        } finally {
            conn.disconnect();
        }
    }

    static int makeRequest(String url, String method, String token, String baseUrl) throws Exception {
        HttpURLConnection conn = (HttpURLConnection) new URL(url).openConnection();
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);
        conn.setRequestMethod(method);
        conn.setRequestProperty("Host", new URL(url).getHost());
        conn.setRequestProperty("Connection", "close");

        String tokenHeader = "Bearer " + token;
        conn.setRequestProperty("Authorization", tokenHeader);

        int status = conn.getResponseCode();
        return status;
