    static String getAccessToken(String clientId, String clientSecret, String scope, String baseUrl) throws Exception {
        String url = baseUrl + "/oauth/token";
        String body = "grant_type=client_credentials&scope=" + scope;
        String basicAuth = base64Encode(clientId + ":" + clientSecret);

        HttpURLConnection conn = (HttpURLConnection) new URL(url).openConnection();
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Host", new URL(url).getHost());
        conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
        conn.setRequestProperty("Authorization", "Basic " + basicAuth);
        conn.setDoOutput(true);
        conn.setDoInput(true);

        try (OutputStream os = conn.getOutputStream()) {
            os.write(body.getBytes(StandardCharsets.UTF_8));
        }

        int status = conn.getResponseCode();
        if (status != 200) {
            throw new Exception("Token request failed: " + status);
        }

        String body = readFully(conn.getInputStream(), conn.getHeaderField("Content-Length"));
        JSONObject resp = parseJson(body);
        return resp.getString("access_token");
    }

