        let sku = parseCSVField(row[0])
        let name = parseCSVField(row[1])
        let priceCents = Int(parseCSVField(row[2]))!
        let currency = parseCSVField(row[3])
        let stock = Int(parseCSVField(row[4]))!

        inventory.append(InventoryItem(
