    public static void main(String[] args) throws Exception {
        if (args.length < 1) {
            System.err.println("Usage: java Main <directory>");
            System.exit(1);
        }

        File dir = new File(args[0]);
        File dbFile = new File(dir, "db.sqlite");

        if (!dbFile.exists()) {
            System.err.println("Database file not found");
            System.exit(1);
        }

        byte[] fileData = Files.readAllBytes(dbFile.toPath());
        printTables(fileData);
    }

    private static void printTables(byte[] fileData) throws Exception {
        int pageSize = readPageSize(fileData);
        int freeBytesPerPage = readFreeBytesPerPage(fileData);

        byte[] schemaPage = readPage(fileData, 1, pageSize);
        int schemaRoot = readBTreeRoot(schemaPage);

        List<TableSchema> tables = new ArrayList<>();
        parseSchemaTable(fileData, pageSize, 1, schemaRoot, tables);

        tables.sort(Comparator.comparing(t -> t.name));

        for (int i = 0; i < tables.size(); i++) {
            if (i > 0) {
                System.out.println();
            }
            TableSchema table = tables.get(i);
            System.out.println("TABLE " + table.name + " rows=" + table.rowCount);
            System.out.println("COLUMNS " + String.join(", ", table.columns));
            for (Record record : table.records) {
                System.out.print(record.rowid + ": ");
                for (int j = 0; j < table.columns.length; j++) {
                    if (j > 0) System.out.print(", ");
                    System.out.print(formatValue(record.values[j]));
                }
                System.out.println();
            }
        }
    }

    private static int readPageSize(byte[] fileData) {
        return (fileData[16] & 0xFF) | ((fileData[17] & 0xFF) << 8);
    }

    private static int readFreeBytesPerPage(byte[] fileData) {
        return (fileData[28] & 0xFF) | ((fileData[29] & 0xFF) << 8);
    }

    private static byte[] readPage(byte[] fileData, int page, int pageSize) throws IOException {
        int offset = (page - 1) * pageSize;
        return Arrays.copyOfRange(fileData, offset, Math.min(offset + pageSize, fileData.length));
    }

    private static byte[] readPageWithHeader(byte[] fileData, int page, int pageSize) throws IOException {
        int offset = (page - 1) * pageSize;
        return Arrays.copyOfRange(fileData, offset, Math.min(offset + pageSize, fileData.length));
    }

    private static int readBTreeRoot(byte[] page) {
        if (page.length < 8) return 0;
        byte type = page[0];
        if (type == 0 || (type & 0x80) != 0) return 0;
        return (page[2] & 0xFF) | ((page[3] & 0xFF) << 8) | ((page[4] & 0xFF) << 16) | ((page[5] & 0xFF) << 24) & 0xFFFFFFFF;
    }

    private static void parseSchemaTable(byte[] fileData, int pageSize, int rootPage, List<TableSchema> tables) throws Exception {
        byte[] schemaPage = readPage(fileData, rootPage, pageSize);
        int schemaRoot = readBTreeRoot(schemaPage);
        parseSchemaTableRecursive(fileData, pageSize, schemaRoot, tables);
    }

