    static String sendStreamingRequest(String baseUrl, String requestBody) throws IOException {
        StringBuilder response = new StringBuilder();
        HttpClient client = new HttpClient(StandardCharsets.UTF_8);
        try {
            HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/v1/messages"))
                .header("Host", baseUrl)
                .header("Content-Length", String.valueOf(requestBody.length()))
                .header("x-api-key", "sk-ant-...")
                .header("anthropic-version", "2023-06-01")
                .header("content-type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(requestBody))
                .build();
            HttpResponse<String> httpResponse = client.send(request, HttpResponse.BodyHandlers.ofString());
            response.append(httpResponse.body());
        } catch (Exception e) {
            e.printStackTrace();
        }
        return response.toString();
    }

    static List<Block> parseBlocks(String responseBody) {
        List<Block> blocks = new ArrayList<>();
        String[] lines = responseBody.split("\n");
        for (String line : lines) {
            if (line.trim().startsWith("event:")) {
                if (line.trim().equals("event: content_block_start")) {
                    blocks.add(new Block("content_block_start"));
                } else if (line.trim().equals("event: content_block_delta")) {
                    blocks.add(new Block("content_block_delta"));
                } else if (line.trim().equals("event: content_block_stop")) {
                    blocks.add(new Block("content_block_stop"));
                }
            } else if (line.trim().startsWith("data:")) {
                String data = line.substring(line.indexOf("data:") + 5);
                try {
                    JsonObject json = parseJson(data);
                    if (json.has("type") && json.get("type").getAsString().equals("thinking")) {
                        blocks.add(new Block("thinking", json.get("thinking").getAsString(), json.get("signature").getAsString(), ""));
                    } else if (json.get("type").getAsString().equals("text")) {
                        blocks.add(new Block("text", "", "", json.get("text").getAsString()));
                    } else if (json.get("type").getAsString().equals("tool_use")) {
                        blocks.add(new Block("tool_use", json.get("id").getAsString(), json.get("name").getAsString(), json.get("input").getAsString()));
                    }
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
        return blocks;
    }

    static String callTool(String toolUseId, String toolName, String input) {
        if (toolName.equals("measure")) {
            JsonObject params = parseJson(input);
            String text = params.get("text").getAsString();
            String unit = params.get("unit").getAsString();
            if (unit.equals("code_points")) {
                return String.valueOf(text.codePoints().count());
            } else if (unit.equals("utf8_bytes")) {
                return String.valueOf(new String(text.getBytes(StandardCharsets.UTF_8)).length());
            } else if (unit.equals("utf16_units")) {
                int count = 0;
                for (char c : text.toCharArray()) {
                    if (c > 65535) count += 2;
                    else count += 1;
                }
                return String.valueOf(count);
            } else {
                return "unsupported unit: " + unit;
            }
        } else if (toolName.equals("reverse")) {
            return new StringBuilder(input).reverse().toString();
        } else {
            return "unknown tool: " + toolName;
        }
    }

    static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default: sb.append(c);
            }
        }
        return sb.toString();
    }

    static JsonObject parseJson(String[] lines) {
        JsonObject json = new JsonObject();
        for (String line : lines) {
            if (line.trim().startsWith("{")) {
                json = parseJsonLine(line);
            }
        }
        return json;
    }

    static JsonObject parseJsonLine(String line) {
        JsonObject json = new JsonObject();
        int start = line.indexOf('{');
        int end = line.lastIndexOf('}');
        String content = line.substring(start, end + 1);
        return new JsonObject(content);
    }

    static class HttpClient {
        public HttpClient(StandardCharsets charset) {}
