                fh = f

        if r_fl >= 0.1 and r_fh >= 0.1 and r_fl + r_fh >= 0.6:
            low_idx = low_freqs.index(fl)
            high_idx = high_freqs.index(fh)
            mapping = [
                ['1', '2', '3', 'A'],
                ['4', '5', '6', 'B'],
                ['7', '8', '9', 'C'],
                ['*', '0', '#', 'D']
            ]
            digit = mapping[low_idx][high_idx]
            labels.append(digit)
        else:
            labels.append(None)

    return labels

def format_output(filename, rate, channels, num_blocks, labels):
    lines = []
    lines.append(f"{filename}: {rate} Hz, {channels} ch, {num_blocks} blocks")

    bridged_labels = list(labels)

    for i in range(len(bridged_labels)):
        if bridged_labels[i] is None:
            if i > 0 and i < len(bridged_labels) - 1:
                left = bridged_labels[i-1]
                right = bridged_labels[i+1]
                if left != None and right != None and left == right:
                    bridged_labels[i] = left

    events = []
    current_digit = None
    current_start = -1

    for i, label in enumerate(bridged_labels):
        if label == None:
            continue
        if current_digit != label:
            if current_digit is not None:
                if (i - current_start) >= 2:
                    events.append((current_start, i))
                current_digit = label
                current_start = i
            else:
                current_digit = label
                current_start = i
        else:
            pass

    if current_digit is not None:
        if (len(bridged_labels) - 1 - current_start) >= 2:
            events.append((current_start, len(bridged_labels)))

    digits_str = "".join(bridged_labels[start] for start, _ in events)
    lines.append(f"digits: {digits_str}")

    return lines

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    directory = sys.argv[1]

    try:
        files = sorted([f for f in os.listdir(directory) if f.endswith('.wav')])
    except Exception:
        sys.exit(0)

    results = []
    for filename in files:
        filepath = os.path.join(directory, filename)
        if not os.path.exists(filepath):
            continue

        info = parse_wav_file(filepath)
        if info is None:
            results.append(f"{filename}: unsupported")
            continue

        rate, channels, samples = info
        num_blocks = len(samples) // (rate // 50)
        labels = detect_dtfm(samples, rate, num_blocks)
        output_lines = format_output(filename, rate, channels, num_blocks, labels)
        results.extend(output_lines)

    if results:
        output = []
        for i, line in enumerate(results):
            output.append(line)
            if i < len(results) - 1:
                output.append('')
        print('\n'.join(output))

