fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: <data_dir> <base_url>");
        process::exit(1);
    }

    let data_dir = &args[0];
    let base_url = &args[1];

    let task_json = fs::read_to_string(format!("{}/task.json", data_dir))
        .expect("Failed to read task.json");
    let task: Task = serde_json::from_str(&task_json)
        .expect("Failed to parse task.json");

    let inventory_csv = fs::read_to_string(format!("{}/inventory.csv", data_dir))
        .expect("Failed to read inventory.csv");
    let inventory: Vec<InventoryItem> = parse_inventory(&inventory_csv);

    let rates_json = fs::read_to_string(format!("{}/rates.json", data_dir))
        .expect("Failed to read rates.json");
    let rates: Rates = serde_json::from_str(&rates_json)
        .expect("Failed to parse rates.json");

    let mut messages: Vec<Message> = vec![
        Message { role: "system".to_string(), content: task.system },
        Message { role: "user".to_string(), content: task.user },
    ];

    let mut prompt_tokens: u32 = 0;
    let mut completion_tokens: u32 = 0;
    let mut total_tokens: u32 = 0;
    let mut request_count: u32 = 0;

    let mut conversation: Vec<String> = vec![];
    let mut say_output: Vec<String> = vec![];
    let mut call_output: Vec<String> = vec![];
    let mut result_output: Vec<String> = vec![];
    let mut final_content: Option<String> = None;

    loop {
        let request = Request::new(
            task.model.clone(),
            messages.clone(),
            task.tools.clone(),
            "auto",
        );

        let response = http_request(base_url, &request);

        if response.status_code != 200 {
            print_output(&say_output, &call_output, &result_output, &final_content);
            println!("ERROR {} {}", response.status_code, response.error_message);
            return;
        }

        let response_body = response.body;
        let response: ChatResponse = serde_json::from_str(&response_body)
            .expect("Failed to parse chat response");

        let choice = response.choices.first()
            .expect("No choices in response");
        let message = &choice.message;
        let finish_reason = choice.finish_reason.as_str();

        if finish_reason == "tool_calls" {
            if let Some(content) = &message.content {
                if let Some(s) = content.as_str() {
                    say_output.push(format!("SAY {}", s));
                }
            }

            if let Some(tool_calls) = &message.tool_calls {
                for tool_call in tool_calls {
                    let id = tool_call.id.clone();
                    let name = tool_call.function.name.clone();
                    call_output.push(format!("CALL {} {}", id, name));
                    let args = tool_call.function.arguments.clone();
                    let result = execute_tool(&args, &inventory, &rates);
                    result_output.push(format!("RESULT {} {}", id, result));
                }
            }

            let next_message = Message {
                role: "assistant".to_string(),
                content: message.content.clone(),
                tool_calls: message.tool_calls.clone(),
                refusal: message.refusal.clone(),
                annotations: message.annotations.clone(),
            };

            messages.push(next_message);
            conversation.push(serde_json::to_string(&next_message).unwrap());
        } else if finish_reason == "stop" {
            if let Some(content) = &message.content {
                if let Some(s) = content.as_str() {
                    final_content = Some(s.to_string());
                }
            }
            break;
        }
    }

    print_output(&say_output, &call_output, &result_output, &final_content);

    let total_prompt = prompt_tokens + completion_tokens + total_tokens;
    println!("USAGE prompt={} completion={} total={} requests={}", 
             total_prompt, completion_tokens, total_tokens, request_count);
}

