fn execute_tool(args: &str, inventory: &[InventoryItem], rates: &Rates) -> String {
    let parsed: Value = serde_json::from_str(args).expect("Invalid JSON arguments");
    match parsed.get("tool_name").and_then(|v| v.as_str()) {
        Some("inventory_lookup") => {
            let sku = parsed.get("sku").and_then(|v| v.as_str())
                .expect("Missing sku");
            let item = inventory.iter().find(|i| i.sku == sku)
                .expect("No such sku");
            format!("{{\"sku\":\"{}\",\"name\":\"{}\",\"price_cents\":{},\"currency\":\"{}\",\"stock\":{}}}",
                    item.sku, item.name, item.price_cents, item.currency, item.stock)
        }
        Some("convert_currency") => {
            let amount_cents = parsed.get("amount_cents").and_then(|v| v.as_i64())
                .expect("Missing amount_cents");
            let from = parsed.get("from").and_then(|v| v.as_str())
                .expect("Missing from");
            let to = parsed.get("to").and_then(|v| v.as_str())
                .expect("Missing to");
            let amount_cents = amount_cents as u64;
            let from_rate = rates.rates.get(from).expect("Unknown currency");
            let to_rate = rates.rates.get(to).expect("Unknown currency");
            let converted = (amount_cents * to_rate * 2 + from_rate) / (from_rate * 2);
            format!("{{\"amount_cents\":{},\"currency\":\"{}}}", converted, to)
        }
        Some(_) => format!("{{\"error\":\"unknown tool: {}\"}}", parsed.get("tool_name").expect("Missing tool_name")),
        None => format!("{{\"error\":\"unknown tool: {}\"}}", parsed.get("tool_name").expect("Missing tool_name")),
    }
}

