fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\b' => result.push_str("\\b"),
            '\f' => result.push_str("\\f"),
            _ if c as u32 < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => result.push(c),
        }
    }
    result
}

fn parse_json_string(s: &str) -> Result<String, String> {
    // Simple unescape for JSON strings
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '"' {
            break;
        }
        match c {
            '\\' => {
                match chars.next() {
                    Some('"') => result.push('"'),
                    Some('\\') => result.push('\\'),
                    Some('/') => result.push('/'),
                    Some('n') => result.push('\n'),
                    Some('r') => result.push('\r'),
                    Some('t') => result.push('\t'),
                    Some('b') => result.push('\b'),
                    Some('f') => result.push('\f'),
                    Some('u') => {
                        let mut hex = String::new();
                        for _ in 0..4 {
                            if let Some(c) = chars.next() {
                                hex.push(c);
                            } else {
                                return Err("Invalid escape sequence".to_string());
                            }
                        }
                        match u32::from_str_radix(&hex, 16) {
                            Ok(code) => {
                                if let Some(c) = char::from_u32(code) {
                                    result.push(c);
                                } else {
                                    return Err("Invalid Unicode escape".to_string());
                                }
                            }
                            Err(_) => return Err("Invalid Unicode escape".to_string()),
                        }
                    }
                    Some(_) => return Err("Invalid escape sequence".to_string()),
                    None => return Err("Unexpected end of string".to_string()),
                }
            }
            _ => result.push(c),
        }
    }
    Ok(result)
}

fn parse_json(s: &str) -> Result<Value, String> {
    let mut cursor = 0;
    let len = s.len();

    fn next_char(s: &str, cursor: &mut usize) -> Result<char, String> {
        if *cursor >= s.len() {
            return Err("Unexpected end of input".to_string());
        }
        let c = s.chars().nth(*cursor).ok_or("Unexpected end of input")?.;
        *cursor += 1;
        Ok(c)
    }

    fn skip_whitespace(s: &str, cursor: &mut usize) {
        while *cursor < s.len() {
            let c = s.chars().nth(*cursor).unwrap();
            if c.is_whitespace() {
                *cursor += 1;
            } else {
                break;
            }
        }
    }

    fn parse_string(s: &str, cursor: &mut usize) -> Result<String, String> {
        if *cursor >= s.len() || s.chars().nth(*cursor).unwrap() != '"' {
            return Err("Expected string start".to_string());
        }
        *cursor += 1; // skip opening quote
        let mut result = String::new();
        while *cursor < s.len() {
            let c = s.chars().nth(*cursor).unwrap();
            if c == '"' {
                *cursor += 1; // skip closing quote
                return Ok(result);
            } else if c == '\\' {
                *cursor += 1;
                let escaped = s.chars().nth(*cursor).unwrap();
                match escaped {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    't' => result.push('\t'),
                    'b' => result.push('\b'),
                    'f' => result.push('\f'),
                    'u' => {
                        *cursor += 1;
                        let mut hex = String::new();
                        for _ in 0..4 {
                            if *cursor >= s.len() {
                                return Err("Invalid escape sequence".to_string());
                            }
                            hex.push(s.chars().nth(*cursor).unwrap());
                            *cursor += 1;
                        }
                        match u32::from_str_radix(&hex, 16) {
                            Ok(code) => {
                                if let Some(c) = char::from_u32(code) {
                                    result.push(c);
                                } else {
                                    return Err("Invalid Unicode escape".to_string());
                                }
                            }
                            Err(_) => return Err("Invalid Unicode escape".to_string()),
                        }
                    }
                    _ => return Err("Invalid escape sequence".to_string()),
                }
            } else {
                result.push(c);
            }
            *cursor += 1;
        }
        Err("Unexpected end of string".to_string())
    }

    fn parse_number(s: &str, cursor: &mut usize) -> Result<f64, String> {
        *cursor += 1; // skip leading digit
        let mut num_str = String::new();
        while *cursor < s.len() {
            let c = s.chars().nth(*cursor).unwrap();
            if c.is_ascii_digit() {
                num_str.push(c);
                *cursor += 1;
            } else if c == '.' && num_str.is_empty() {
                // decimal point
                *cursor += 1;
                let mut frac_str = String::new();
                while *cursor < s.len() {
                    let c = s.chars().nth(*cursor).unwrap();
                    if c.is_ascii_digit() {
                        frac_str.push(c);
                        *cursor += 1;
                    } else {
                        break;
                    }
                }
                if frac_str.is_empty() {
                    return Err("Invalid number".to_string());
                }
                num_str.push_str(&frac_str);
            } else {
                break;
            }
        }
        num_str.parse::<f64>().map_err(|_| "Invalid number".to_string())
    }

    fn parse_value(s: &str, cursor: &mut usize) -> Result<Value, String> {
        skip_whitespace(s, cursor);
        let c = s.chars().nth(*cursor).ok_or("Unexpected end of input")?;
        match c {
            '{' => {
                *cursor += 1;
                let mut map = HashMap::new();
                while *cursor < s.len() {
                    skip_whitespace(s, cursor);
                    if *cursor >= s.len() || s.chars().nth(*cursor).unwrap() != '"' {
                        return Err("Expected string key".to_string());
                    }
                    let key = parse_string(s, cursor)?;
                    skip_whitespace(s, cursor);
                    if *cursor >= s.len() || s.chars().nth(*cursor).unwrap() != ':' {
                        return Err("Expected colon".to_string());
                    }
                    *cursor += 1;
                    skip_whitespace(s, cursor);
                    let val = parse_value(s, cursor)?;
                    map.insert(key, val);
                    skip_whitespace(s, cursor);
                    if *cursor >= s.len() || s.chars().nth(*cursor).unwrap() != '}' {
                        return Err("Expected closing brace".to_string());
                    }
                    *cursor += 1;
                    if *cursor < s.len() {
                        skip_whitespace(s, cursor);
                        if s.chars().nth(*cursor).unwrap() != ',' {
                            return Err("Expected comma or end of object".to_string());
                        }
                        *cursor += 1;
                    }
                }
                Ok(Value::Map(map))
            }
            '[' => {
                *cursor += 1;
                let mut vec = Vec::new();
                while *cursor < s.len() {
                    skip_whitespace(s, cursor);
                    if *cursor >= s.len() || s.chars().nth(*cursor).unwrap() != ']' {
                        return Err("Expected closing bracket".to_string());
                    }
                    *cursor += 1;
                    if *cursor < s.len() {
                        skip_whitespace(s, cursor);
                        if s.chars().nth(*cursor).unwrap() != ',' {
                            return Err("Expected comma or end of array".to_string());
                        }
                        *cursor += 1;
                    }
                }
                Ok(Value::Vec(vec))
            }
            '"' => parse_string(s, cursor),
            '-' | '0'..='9' => parse_number(s, cursor),
            't' => {
                skip_whitespace(s, cursor);
                if s.chars().nth(*cursor).unwrap() == 'r' {
                    *cursor += 1;
                    if s.chars().nth(*cursor).unwrap() == 'u' {
                        *cursor += 1;
                        if s.chars().nth(*cursor).unwrap() == 'e' {
                            *cursor += 1;
                            return Ok(Value::Bool(true));
                        }
                    }
                }
                Err("Expected true".to_string())
            }
            'f' => {
                skip_whitespace(s, cursor);
                if s.chars().nth(*cursor).unwrap() == 'a' {
                    *cursor += 1;
                    if s.chars().nth(*cursor).unwrap() == 'l' {
                        *cursor += 1;
                        if s.chars().nth(*cursor).unwrap() == 's' {
                            *cursor += 1;
                            if s.chars().nth(*cursor).unwrap() == 'e' {
                                *cursor += 1;
                                return Ok(Value::Bool(false));
                            }
                        }
                    }
                }
                Err("Expected false".to_string())
            }
            'n' => {
                skip_whitespace(s, cursor);
                if s.chars().nth(*cursor).unwrap() == 'u' {
                    *cursor += 1;
                    if s.chars().nth(*cursor).unwrap() == 'l' {
                        *cursor += 1;
                        if s.chars().nth(*cursor).unwrap() == 'l' {
                            *cursor += 1;
                            if s.chars().nth(*cursor).unwrap() == ' ' {
                                *cursor += 1;
                                return Ok(Value::Null);
                            }
                        }
                    }
                }
                Err("Expected null".to_string())
            }
            _ => Err("Unexpected character".to_string()),
        }
    }

    parse_value(s, &mut 0)
}

fn parse_csv_line(s: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut current_field = String::new();
    let mut in_quotes = false;
    let mut chars = s.chars().peekable();

    while let Some(c) = chars.next() {
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    current_field.push('"');
                    chars.next();
                } else {
                    in_quotes = false;
                }
            } else {
                current_field.push(c);
            }
        } else {
            if c == '"' {
                in_quotes = true;
            } else if c == ',' {
                fields.push(current_field);
                current_field = String::new();
            } else {
                current_field.push(c);
            }
        }
    }
    fields.push(current_field);
    fields
}

fn parse_csv(s: &str) -> Vec<Vec<String>> {
    let mut lines = Vec::new();
    let mut current_line = String::new();
    for c in s.chars() {
        if c == '\n' {
            if !current_line.is_empty() || !lines.is_empty() {
                let fields = parse_csv_line(&current_line);
                lines.push(fields);
            }
            current_line = String::new();
        } else {
            current_line.push(c);
        }
    }
    if !current_line.is_empty() {
        let fields = parse_csv_line(&current_line);
        lines.push(fields);
    }
    lines
}

fn parse_inventory(s: &str) -> Vec<InventoryItem> {
    let mut rows = parse_csv(s);
    if rows.len() < 2 {
        return Vec::new();
    }
    let header = &rows[0];
    if header.len() != 5 {
        return Vec::new();
    }
    let mut items = Vec::new();
    for row in rows.iter().skip(1) {
        if row.len() < 5 {
            continue;
        }
        let sku = row[0].clone();
        let name = row[1].clone();
        let price_cents = row[2].parse::<u64>().unwrap_or(0);
        let currency = row[3].clone();
        let stock = row[4].parse::<u64>().unwrap_or(0);
        items.push(InventoryItem { sku, name, price_cents, currency, stock });
    }
    items
}

struct InventoryItem {
    sku: String,
    name: String,
    price_cents: u64,
    currency: String,
    stock: u64,
}

struct Rates {
    scale: u64,
    rates: HashMap<String, u64>,
}

struct ToolCall {
    id: String,
    type: String,
    function: FunctionCall,
}

struct FunctionCall {
    name: String,
    arguments: String,
}

struct Message {
    role: String,
    content: Option<String>,
    tool_calls: Option<Vec<ToolCall>>,
    refusal: Option<String>,
    annotations: Option<Vec<Annotation>>,
}

struct Annotation {
    type: String,
    value: String,
}

struct ChatResponse {
    choices: Vec<Choice>,
    usage: Usage,
}

struct Choice {
    message: Message,
    finish_reason: String,
}

struct Usage {
    prompt_tokens: u32,
    completion_tokens: u32,
    total_tokens: u32,
}

struct Request {
    model: String,
    messages: Vec<Message>,
    tools: Vec<Tool>,
    tool_choice: String,
}

struct Tool {
    name: String,
    description: String,
    parameters: Value,
}

fn execute_tool(args: &str, inventory: &[InventoryItem], rates: &Rates) -> String {
    let parsed: Value = parse_json(args).unwrap_or_else(|_| Value::Null);
    match parsed {
        Value::Map(ref map) => {
            if let Some(tool_name) = map.get("tool_name").and_then(|v| v.as_str()) {
                match tool_name {
                    "inventory_lookup" => {
                        if let Some(sku) = map.get("sku").and_then(|v| v.as_str()) {
                            if let Some(item) = inventory.iter().find(|i| i.sku == *sku) {
                                return format!(
                                    "{{\"sku\":\"{}\",\"name\":\"{}\",\"price_cents\":{},\"currency\":\"{}\",\"stock\":{}}}",
                                    item.sku, item.name, item.price_cents, item.currency, item.stock
                                );
                            }
                        }
                    }
                    "convert_currency" => {
                        if let Some(amount_cents) = map.get("amount_cents").and_then(|v| v.as_i64()) {
                            if let Some(from) = map.get("from").and_then(|v| v.as_str()) {
                                if let Some(to) = map.get("to").and_then(|v| v.as_str()) {
                                    let amount_cents = amount_cents as u64;
                                    let from_rate = rates.rates.get(from).copied().unwrap_or(0);
                                    let to_rate = rates.rates.get(to).copied().unwrap_or(0);
                                    let converted = (2 * amount_cents * to_rate + from_rate) / (2 * from_rate);
                                    return format!(
                                        "{{\"amount_cents\":{},\"currency\":\"{}}}",
                                        converted, to
                                    );
                                }
                            }
                        }
                    }
                    _ => {}
                }
                return format!("{{\"error\":\"unknown tool: {}\"}}", tool_name);
            }
        }
        _ => {}
    }
    format!("{{\"error\":\"unknown tool: {}\"}}", "unknown")
}

fn serialize_message(msg: &Message) -> String {
    let mut buf = String::new();
    buf.push('"');
    buf.push_str(&msg.role);
    buf.push_str(r#"": "}"#);
    if let Some(content) = &msg.content {
        buf.push_str(r#", "content": "#);
        buf.push_str(&escape_json_string(content));
    }
    if let Some(tool_calls) = &msg.tool_calls {
        buf.push_str(r#", "tool_calls": [#);
        for (i, call) in tool_calls.iter().enumerate() {
            if i > 0 { buf.push_str(", "); }
            buf.push_str("\"");
            buf.push_str(&call.id);
            buf.push_str(r#": {\");
            buf.push_str("\"type\": \"function\", \"function\": {");
            buf.push_str(r#""name": ");
            buf.push_str(&escape_json_string(&call.function.name));
            buf.push_str(r#", \"arguments": ");
            buf.push_str(&escape_json_string(&call.function.arguments));
            buf.push_str(r#"}}"#);
        }
        buf.push_str("]");
    }
    buf.push('"');
    buf
}

fn serialize_message_array(messages: &[Message]) -> String {
    let mut buf = String::new();
    buf.push('[');
    for (i, msg) in messages.iter().enumerate() {
        if i > 0 { buf.push_str(", "); }
        buf.push_str(&serialize_message(msg));
    }
    buf.push(']');
    buf
}

fn serialize_request(req: &Request) -> String {
    let mut buf = String::new();
    buf.push('"');
    buf.push_str(&req.model);
    buf.push_str(r#"": "#);
    buf.push_str(&escape_json_string(&req.model));
    buf.push_str(r#","messages": "#);
    buf.push_str(&serialize_message_array(&req.messages));
    buf.push_str(r#","tools": [#);
    for (i, tool) in req.tools.iter().enumerate() {
        if i > 0 { buf.push_str(", "); }
        buf.push_str("\"");
        buf.push_str(&tool.name);
        buf.push_str(r#": {"description": "#);
        buf.push_str(&escape_json_string(&tool.description));
        buf.push_str(r#", "parameters": {");
        buf.push_str(&serialize_value(&tool.parameters));
        buf.push_str(r#"}}}"#);
    }
    buf.push_str("],");
    buf.push_str(r#""tool_choice": "auto""#);
    buf.push('"');
    buf
}

fn serialize_value(val: &Value) -> String {
    match val {
        Value::Null => "null".to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => format!("{:.10}", n).replace('.', ""),
        Value::String(s) => format!("\"{}\"", escape_json_string(s)),
        Value::Vec(v) => {
            let mut buf = String::new();
            buf.push('[');
            for (i, item) in v.iter().enumerate() {
                if i > 0 { buf.push_str(", "); }
                buf.push_str(&serialize_value(item));
            }
            buf.push(']');
            buf
        }
        Value::Map(m) => {
            let mut buf = String::new();
            buf.push('{');
            for (i, (k, v)) in m.iter().enumerate() {
                if i > 0 { buf.push_str(", "); }
                buf.push('"');
                buf.push_str(&escape_json_string(k));
                buf.push_str(r#": "#);
                buf.push_str(&serialize_value(v));
            }
            buf.push('}');
            buf
        }
    }
}

fn http_request(base_url: &str, body: &str) -> Result<Response, String> {
    let url = format!("{}/chat/completions", base_url);
    let request = format!("POST {} HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}", url, body.len(), body);
    let mut stream = TcpStream::connect("127.0.0.1:50123").unwrap();
    stream.write_all(request.as_bytes()).unwrap();
    let mut buf = [0u8; 1024 * 1024];
    let mut response = String::new();
    stream.read_until(b'\n', &mut buf).unwrap();
    let mut response_str = String::new();
    response_str.push_str(&std::str::from_utf8(&buf).unwrap());
    // ...
    Ok(Response { status: 200, body: body.to_string() })
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: <data_dir> <base_url>");
        process::exit(1);
    }

    let data_dir = &args[0];
    let base_url = &args[1];

    let task_json = fs::read_to_string(format!("{}/task.json", data_dir))
        .expect("Failed to read task.json");
    let task: Task = serde_json::from_str(&task_json).expect("Failed to parse task.json");

    let inventory_csv = fs::read_to_string(format!("{}/inventory.csv", data_dir))
        .expect("Failed to read inventory.csv");
    let inventory: Vec<InventoryItem> = parse_inventory(&inventory_csv);

    let rates_json = fs::read_to_string(format!("{}/rates.json", data_dir))
        .expect("Failed to read rates.json");
    let rates: Rates = serde_json::from_str(&rates_json).expect("Failed to parse rates.json");

    let mut messages: Vec<Message> = vec![
        Message { role: "system".to_string(), content: Some(task.system), tool_calls: None, refusal: None, annotations: None },
        Message { role: "user".to_string(), content: Some(task.user), tool_calls: None, refusal: None, annotations: None },
    ];

    let mut prompt_tokens: u32 = 0;
    let mut completion_tokens: u32 = 0;
    let mut total_tokens: u32 = 0;
    let mut request_count: u32 = 0;

    loop {
        let request = Request {
            model: task.model.clone(),
            messages: messages.clone(),
            tools: task.tools.clone(),
            tool_choice: "auto".to_string(),
        };

        let response = http_request(base_url, &request);

        if response.status_code != 200 {
            print_output(&say_output, &call_output, &result_output, &final_content);
            println!("ERROR {} {}", response.status_code, response.error_message);
            return;
        }

        let response_body = response.body;
        let response: ChatResponse = parse_json(&response_body).expect("Failed to parse chat response");

        let choice = response.choices.first()
            .expect("No choices in response");
        let message = &choice.message;
        let finish_reason = choice.finish_reason.as_str();

        if finish_reason == "tool_calls" {
            if let Some(content) = &message.content {
                if let Some(s) = content {
                    say_output.push(format!("SAY {}", s));
                }
            }

            if let Some(tool_calls) = &message.tool_calls {
                for tool_call in tool_calls {
                    let id = tool_call.id.clone();
                    let name = tool_call.function.name.clone();
                    call_output.push(format!("CALL {} {}", id, name));
                    let args = tool_call.function.arguments.clone();
                    let result = execute_tool(&args, &inventory, &rates);
                    result_output.push(format!("RESULT {} {}", id, result));
                }
            }

            let next_message = Message {
                role: "assistant".to_string(),
                content: message.content.clone(),
                tool_calls: message.tool_calls.clone(),
                refusal: message.refusal.clone(),
                annotations: message.annotations.clone(),
            };

            messages.push(next_message);
        } else if finish_reason == "stop" {
            if let Some(content) = &message.content {
                if let Some(s) = content {
                    final_content = Some(s.to_string());
                }
            }
            break;
        }
    }

    print_output(&say_output, &call_output, &result_output, &final_content);

    let total_prompt = prompt_tokens + completion_tokens + total_tokens;
    println!("USAGE prompt={} completion={} total={} requests={}", 
             total_prompt, completion_tokens, total_tokens, request_count);
}
